window.KARNATAKA_BANK = {"patternSource": "https://karnatakabank.lntedutech.com/e/CNJDMT8X/login", "patternChecked": "2026-11-17", "tests": [{"id": "KBL-01", "title": "Karnataka Bank CSA Mock 01", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_01.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-01-Q1", "number": 1, "section": "verbal", "stem": "What was the main purpose of the appointment system?", "options": ["Stop walk-in services", "Remove all employees", "Increase service charges", "Reduce waiting time", "Close the branch"], "answerIndex": 3, "explanation": "Supported directly by the reading passage.", "passage": "A bank introduced a digital appointment system to reduce waiting time at its branch. Customers could choose a service and reserve a time slot before arriving. Staff continued to support walk-in customers, especially senior citizens. After a trial period, the branch noticed that queues became shorter during peak hours, but staff still needed to explain the system clearly to first-time users.", "sourcePage": 2}, {"id": "KBL-01-Q2", "number": 2, "section": "verbal", "stem": "Who continued to receive walk-in support?", "options": ["Only first-time users", "Walk-in customers, especially senior citizens", "Only online applicants", "Only students", "Only business owners"], "answerIndex": 1, "explanation": "Supported directly by the reading passage.", "passage": "A bank introduced a digital appointment system to reduce waiting time at its branch. Customers could choose a service and reserve a time slot before arriving. Staff continued to support walk-in customers, especially senior citizens. After a trial period, the branch noticed that queues became shorter during peak hours, but staff still needed to explain the system clearly to first-time users.", "sourcePage": 2}, {"id": "KBL-01-Q3", "number": 3, "section": "verbal", "stem": "What challenge remained after the trial?", "options": ["Buying new bank buildings", "Stopping all deposits", "Explaining the system to first-time users", "Changing national holidays", "Printing new currency"], "answerIndex": 2, "explanation": "Supported directly by the reading passage.", "passage": "A bank introduced a digital appointment system to reduce waiting time at its branch. Customers could choose a service and reserve a time slot before arriving. Staff continued to support walk-in customers, especially senior citizens. After a trial period, the branch noticed that queues became shorter during peak hours, but staff still needed to explain the system clearly to first-time users.", "sourcePage": 2}, {"id": "KBL-01-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"accurate\".", "options": ["precise", "hasty", "careless", "outdated", "vague"], "answerIndex": 0, "explanation": "\"accurate\" is closest in meaning to \"precise\".", "passage": "", "sourcePage": 2}, {"id": "KBL-01-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"rapid\".", "options": ["late", "weak", "slow", "minor", "swift"], "answerIndex": 4, "explanation": "\"rapid\" is closest in meaning to \"swift\".", "passage": "", "sourcePage": 2}, {"id": "KBL-01-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"scarce\".", "options": ["insufficient", "abundant", "few", "limited", "rare"], "answerIndex": 1, "explanation": "The opposite of \"scarce\" is \"abundant\".", "passage": "", "sourcePage": 2}, {"id": "KBL-01-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"increase\".", "options": ["grow", "decrease", "rise", "expand", "multiply"], "answerIndex": 1, "explanation": "The opposite of \"increase\" is \"decrease\".", "passage": "", "sourcePage": 3}, {"id": "KBL-01-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: Neither of the two documents ___ complete.", "options": ["have", "is", "were", "are", "be"], "answerIndex": 1, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-01-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: The manager, along with the officers, ___ present.", "options": ["are", "be", "have", "was", "were"], "answerIndex": 3, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-01-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: Each of the applicants ___ an identity proof.", "options": ["have", "are", "were", "be", "has"], "answerIndex": 4, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-01-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"He do not know the branch timings.\"", "options": ["He doing not know the branch timings.", "He does knows the branch timings.", "He do not knows the branch timings.", "He not knows the branch timings.", "He does not know the branch timings."], "answerIndex": 4, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-01-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The clerk verified the documents.\"", "options": ["The documents are verifying the clerk.", "The clerk was verified by the documents.", "The documents were verified by the clerk.", "The documents is verified by the clerk.", "The documents verified the clerk."], "answerIndex": 2, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-01-Q13", "number": 13, "section": "quant", "stem": "Find 20% of 240.", "options": ["48", "32", "40", "24", "56"], "answerIndex": 0, "explanation": "20/100 x 240 = 48.", "passage": "", "sourcePage": 3}, {"id": "KBL-01-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 5:6. If there are 187 students, how many girls are there?", "options": ["102", "85", "119", "68", "51"], "answerIndex": 0, "explanation": "One part = 187/(5+6) = 17; girls = 6 x 17.", "passage": "", "sourcePage": 4}, {"id": "KBL-01-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 1200 and sells it at 15% profit. Find the selling price (Rs).", "options": ["1404", "1332", "1356", "1308", "1380"], "answerIndex": 4, "explanation": "SP = 1200 x (1 + 15/100) = Rs 1380.", "passage": "", "sourcePage": 4}, {"id": "KBL-01-Q16", "number": 16, "section": "quant", "stem": "Find the average of 61, 65, 69, 73, 77.", "options": ["63", "69", "72", "60", "66"], "answerIndex": 1, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-01-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 4000 at 10% p.a. for 3 years.", "options": ["1240", "1080", "1200", "1120", "1160"], "answerIndex": 2, "explanation": "SI = 4000 x 10 x 3/100 = Rs 1200.", "passage": "", "sourcePage": 4}, {"id": "KBL-01-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 30000 at 10% per annum for 2 years, compounded annually.", "options": ["6600", "6300", "5400", "6000", "5700"], "answerIndex": 1, "explanation": "CI = 30000 x [(1+10/100)^2 -1] = Rs 6300.", "passage": "", "sourcePage": 4}, {"id": "KBL-01-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 6 days and B in 12 days. Working together, in how many days will they finish?", "options": ["3", "4", "5", "2", "1"], "answerIndex": 1, "explanation": "Combined time = (6 x 12)/(6+12) = 4 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-01-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 36 km/h for 2 hours. Find the distance travelled (km).", "options": ["54", "72", "36", "18", "90"], "answerIndex": 1, "explanation": "Distance = speed x time = 36 x 2 = 72 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-01-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 18, 26, 34, 42, ?", "options": ["42", "26", "50", "34", "58"], "answerIndex": 2, "explanation": "Each step adds 8.", "passage": "", "sourcePage": 5}, {"id": "KBL-01-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 800 is sold at 30% discount. Find the selling price (Rs).", "options": ["440", "600", "520", "480", "560"], "answerIndex": 4, "explanation": "SP = 800 x (100-30)/100 = Rs 560.", "passage": "", "sourcePage": 5}, {"id": "KBL-01-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 190 accounts on Monday and 170 on Tuesday. Branch B opened 240 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["600", "590", "610", "580", "570"], "answerIndex": 0, "explanation": "Total = 190 + 170 + 240 = 600.", "passage": "", "sourcePage": 5}, {"id": "KBL-01-Q24", "number": 24, "section": "quant", "stem": "Ravi is 10 years older than Meera. Their present ages add up to 36 years. What is Ravi's age?", "options": ["21", "25", "17", "23", "19"], "answerIndex": 3, "explanation": "Older age = (sum + difference)/2 = (36+10)/2 = 23.", "passage": "", "sourcePage": 5}, {"id": "KBL-01-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 6 and 12 hours; pipe C empties it in 6 hours. If all are opened together, when will the tank fill?", "options": ["12", "8", "10", "14", "6"], "answerIndex": 0, "explanation": "Net filling rate = 1/6 + 1/12 - 1/6 = 1/12 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-01-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 20 L and 15 L respectively. What is the simplified milk:water ratio?", "options": ["5:3", "6:3", "4:4", "3:4", "4:3"], "answerIndex": 4, "explanation": "Divide both quantities by HCF = 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-01-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 500. Its price rises by 25% and then falls by 20%. Find its final price (Rs).", "options": ["450", "475", "500", "525", "425"], "answerIndex": 2, "explanation": "Final price = 500 x 125/100 x 80/100 = 500.", "passage": "", "sourcePage": 5}, {"id": "KBL-01-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 3 place(s) forward in the alphabet. How is LOAN coded?", "options": ["ORDQ", "RUGT", "LOAN", "QTFS", "PSER"], "answerIndex": 0, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-01-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 40 people, A is 12th from the front. What is A's rank from the back?", "options": ["26", "29", "28", "27", "30"], "answerIndex": 1, "explanation": "Back rank = total - front rank +1 = 40-12+1 = 29.", "passage": "", "sourcePage": 6}, {"id": "KBL-01-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 2 km east, then 4 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["16", "20", "24", "12", "8"], "answerIndex": 1, "explanation": "Pythagoras: distance squared = 2^2 + 4^2 = 20.", "passage": "", "sourcePage": 6}, {"id": "KBL-01-Q31", "number": 31, "section": "reasoning", "stem": "A person faces North and turns 90 degrees to the left. Which direction does the person now face?", "options": ["South", "East", "Cannot be determined", "North", "West"], "answerIndex": 4, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-01-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All dogs are animals. Some animals are birds. Which conclusion definitely follows?", "options": ["Some animals are dogs", "All animals are dogs", "All birds are animals", "No dogs are animals", "All birds are dogs"], "answerIndex": 0, "explanation": "All dogs are animals implies some animals are dogs in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-01-Q33", "number": 33, "section": "reasoning", "stem": "Given J > L = G > K, which relation definitely holds?", "options": ["J = K", "G = K", "K > J", "L < K", "J > K"], "answerIndex": 4, "explanation": "Chain: J > L = G > K, so J > K.", "passage": "", "sourcePage": 6}, {"id": "KBL-01-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: C, A, J, F, G. Who sits immediately to the right of A?", "options": ["J", "C", "A", "G", "F"], "answerIndex": 0, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-01-Q35", "number": 35, "section": "reasoning", "stem": "Pooja is the mother of Neha. Rina is the sister of Neha. How is Pooja related to Rina?", "options": ["Sister", "Mother", "Aunt", "Grandmother", "Daughter"], "answerIndex": 1, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-01-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: Q > T > R > W > X. Who is immediately heavier than T?", "options": ["X", "R", "W", "Q", "T"], "answerIndex": 3, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-01-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 16, 32, 64, 128, ?", "options": ["288", "256", "224", "160", "192"], "answerIndex": 1, "explanation": "Every term is multiplied by 2.", "passage": "", "sourcePage": 7}, {"id": "KBL-01-Q38", "number": 38, "section": "reasoning", "stem": "If today is Monday, what day of the week will it be after 25 days?", "options": ["Saturday", "Friday", "Wednesday", "Sunday", "Tuesday"], "answerIndex": 1, "explanation": "Advance 4 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-01-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are J, A, E, M, L. Who occupies floor 4?", "options": ["L", "J", "E", "A", "M"], "answerIndex": 4, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-01-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in DEPOSIT?", "options": ["DEIOPST", "DEPOSIT", "EPOSITD", "TISOPED", "TDEPOSI"], "answerIndex": 3, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-01-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 6?", "options": ["24", "12", "18", "30", "43"], "answerIndex": 4, "explanation": "43 leaves a remainder when divided by 6.", "passage": "", "sourcePage": 8}, {"id": "KBL-01-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 8 km east, then 5 km west. Where is the final position relative to the starting point?", "options": ["13 km east", "13 km west", "3 km east", "3 km west", "8 km north"], "answerIndex": 2, "explanation": "Net eastward movement = 8-5 = 3 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-01-Q43", "number": 43, "section": "gk", "stem": "Which Indian authority issues most banknotes?", "options": ["Gram panchayat", "Municipal corporation", "District collector", "Reserve Bank of India", "Stock exchange"], "answerIndex": 3, "explanation": "Correct: Reserve Bank of India.", "passage": "", "sourcePage": 8}, {"id": "KBL-01-Q44", "number": 44, "section": "gk", "stem": "Which entity supervises securities markets in India?", "options": ["NABARD", "UIDAI", "NITI Aayog", "RBI training college", "SEBI"], "answerIndex": 4, "explanation": "Correct: SEBI.", "passage": "", "sourcePage": 8}, {"id": "KBL-01-Q45", "number": 45, "section": "gk", "stem": "What does PAN stand for in Indian taxation?", "options": ["Private Asset Note", "Payment Approval Number", "Permanent Account Number", "Permanent Address Name", "Public Account Nominee"], "answerIndex": 2, "explanation": "Correct: Permanent Account Number.", "passage": "", "sourcePage": 8}, {"id": "KBL-01-Q46", "number": 46, "section": "gk", "stem": "What is bank reconciliation used for?", "options": ["Authorising passport renewals", "Printing new banknotes", "Setting all rates to zero", "Changing a bank name", "Matching records and identifying differences"], "answerIndex": 4, "explanation": "Correct: Matching records and identifying differences.", "passage": "", "sourcePage": 8}, {"id": "KBL-01-Q47", "number": 47, "section": "gk", "stem": "What does DBT commonly stand for in Indian public payments?", "options": ["Debit Banking Token", "Daily Balance Test", "Digital Bond Trade", "Demand Budget Tax", "Direct Benefit Transfer"], "answerIndex": 4, "explanation": "Correct: Direct Benefit Transfer.", "passage": "", "sourcePage": 8}, {"id": "KBL-01-Q48", "number": 48, "section": "gk", "stem": "Where is Karnataka Bank headquartered?", "options": ["Udupi", "Mangaluru", "Chennai", "Mumbai", "New Delhi"], "answerIndex": 1, "explanation": "Correct: Mangaluru.", "passage": "", "sourcePage": 9}, {"id": "KBL-01-Q49", "number": 49, "section": "gk", "stem": "What does KYC stand for in banking?", "options": ["Know Your Customer", "Know Your Currency", "Know Your Cheque", "Keep Your Credit", "Keep Your Cash"], "answerIndex": 0, "explanation": "Correct: Know Your Customer.", "passage": "", "sourcePage": 9}, {"id": "KBL-01-Q50", "number": 50, "section": "gk", "stem": "What does NPA stand for?", "options": ["Non-Performing Asset", "Net Profit Addition", "National Payments Agency", "Non-Priority Account", "New Personal Account"], "answerIndex": 0, "explanation": "Correct: Non-Performing Asset.", "passage": "", "sourcePage": 9}, {"id": "KBL-01-Q51", "number": 51, "section": "gk", "stem": "What is inflation?", "options": ["A general rise in prices over time", "A guaranteed rise in bank deposits", "A fixed bank charge", "A reduction in money supply by definition", "A fall in all interest rates"], "answerIndex": 0, "explanation": "Correct: A general rise in prices over time.", "passage": "", "sourcePage": 9}, {"id": "KBL-01-Q52", "number": 52, "section": "gk", "stem": "What is the main purpose of deposit insurance?", "options": ["Protect eligible deposits within applicable limits", "Prevent all banking fraud", "Guarantee every investment return", "Eliminate loan repayment", "Replace financial statements"], "answerIndex": 0, "explanation": "Correct: Protect eligible deposits within applicable limits.", "passage": "", "sourcePage": 9}, {"id": "KBL-01-Q53", "number": 53, "section": "gk", "stem": "Which is an example of a collateral-backed loan?", "options": ["Loan secured by pledged property", "ATM withdrawal", "Salary slip", "Loan with no security by definition", "Interest-free grant"], "answerIndex": 0, "explanation": "Correct: Loan secured by pledged property.", "passage": "", "sourcePage": 9}, {"id": "KBL-01-Q54", "number": 54, "section": "computer", "stem": "Which memory is volatile?", "options": ["RAM", "ROM", "Hard disk", "DVD", "SSD"], "answerIndex": 0, "explanation": "Correct: RAM.", "passage": "", "sourcePage": 9}, {"id": "KBL-01-Q55", "number": 55, "section": "computer", "stem": "Which device is generally an input device?", "options": ["Projector", "Speaker", "Monitor", "Keyboard", "Printer"], "answerIndex": 3, "explanation": "Correct: Keyboard.", "passage": "", "sourcePage": 10}, {"id": "KBL-01-Q56", "number": 56, "section": "computer", "stem": "What is malware?", "options": ["Hardware warranty", "Network cable", "Printer paper", "Malicious software", "Legal banking software only"], "answerIndex": 3, "explanation": "Correct: Malicious software.", "passage": "", "sourcePage": 10}, {"id": "KBL-01-Q57", "number": 57, "section": "computer", "stem": "Which of these is an operating system?", "options": ["Windows", "Excel", "Photoshop", "Microsoft Word", "Google Search"], "answerIndex": 0, "explanation": "Correct: Windows.", "passage": "", "sourcePage": 10}, {"id": "KBL-01-Q58", "number": 58, "section": "computer", "stem": "What does USB stand for?", "options": ["User Service Backup", "Universal Storage Bank", "Unified Security Board", "Ultra System Binary", "Universal Serial Bus"], "answerIndex": 4, "explanation": "Correct: Universal Serial Bus.", "passage": "", "sourcePage": 10}, {"id": "KBL-01-Q59", "number": 59, "section": "computer", "stem": "What does RAM usually store while programs run?", "options": ["Paper records", "Only permanent engraved code", "Printed bank statements", "Optical labels", "Temporary working data"], "answerIndex": 4, "explanation": "Correct: Temporary working data.", "passage": "", "sourcePage": 10}, {"id": "KBL-01-Q60", "number": 60, "section": "computer", "stem": "Which file type commonly represents a compressed archive?", "options": [".jpg", ".txt", ".zip", ".wav", ".xlsx"], "answerIndex": 2, "explanation": "Correct: .zip.", "passage": "", "sourcePage": 10}, {"id": "KBL-01-Q61", "number": 61, "section": "computer", "stem": "Which service is primarily used to send email between servers?", "options": ["FTP", "HTTP", "USB", "DNS", "SMTP"], "answerIndex": 4, "explanation": "Correct: SMTP.", "passage": "", "sourcePage": 10}, {"id": "KBL-01-Q62", "number": 62, "section": "computer", "stem": "What does CPU stand for?", "options": ["Central Processing Unit", "Central Print Unit", "Control Program Unit", "Computer Personal Utility", "Central Power Utility"], "answerIndex": 0, "explanation": "Correct: Central Processing Unit.", "passage": "", "sourcePage": 11}, {"id": "KBL-01-Q63", "number": 63, "section": "computer", "stem": "Which device outputs printed documents?", "options": ["Scanner", "Printer", "Keyboard", "Microphone", "Mouse"], "answerIndex": 1, "explanation": "Correct: Printer.", "passage": "", "sourcePage": 11}, {"id": "KBL-01-Q64", "number": 64, "section": "computer", "stem": "What is two-factor authentication?", "options": ["Running two browsers", "Entering the same password twice", "Using two keyboards", "Using two different proof factors for login", "Keeping two bank accounts"], "answerIndex": 3, "explanation": "Correct: Using two different proof factors for login.", "passage": "", "sourcePage": 11}, {"id": "KBL-01-Q65", "number": 65, "section": "sales", "stem": "Case 1.1: A customer asks why a transaction is pending. What is best?", "options": ["Invent a completion time", "Ask the customer to pay you privately", "Check the status through authorised systems and explain next steps", "Delete the receipt", "Advise them to disclose the OTP"], "answerIndex": 2, "explanation": "Correct: Check the status through authorised systems and explain next steps.", "passage": "", "sourcePage": 11}, {"id": "KBL-01-Q66", "number": 66, "section": "sales", "stem": "A customer may benefit from a different product. What is good cross-selling?", "options": ["Misstate returns", "Apply pressure to vulnerable customers", "Skip disclosure of charges", "Explain an appropriate option and obtain informed consent", "Open it automatically"], "answerIndex": 3, "explanation": "Correct: Explain an appropriate option and obtain informed consent.", "passage": "", "sourcePage": 11}, {"id": "KBL-01-Q67", "number": 67, "section": "sales", "stem": "A customer wants to opt out of promotional contact. What should you do?", "options": ["Sell their number to others", "Invent a consent record", "Follow the bank's opt-out and consent process", "Continue calling regardless", "Demand a fee for an opt-out"], "answerIndex": 2, "explanation": "Correct: Follow the bank's opt-out and consent process.", "passage": "", "sourcePage": 11}, {"id": "KBL-01-Q68", "number": 68, "section": "sales", "stem": "Case 1.4: The customer does not understand loan interest. What helps?", "options": ["Explain the rate, interest calculation and illustrative total cost", "Alter the signed agreement", "Promise no interest will accrue", "Hide charges", "Quote only a monthly payment without context"], "answerIndex": 0, "explanation": "Correct: Explain the rate, interest calculation and illustrative total cost.", "passage": "", "sourcePage": 11}, {"id": "KBL-01-Q69", "number": 69, "section": "sales", "stem": "A customer complains about repeated sales calls. What should you do?", "options": ["Treat silence as consent", "Dismiss the objection", "Increase call frequency", "Listen and process consent preferences or complaints", "Sell the contact details"], "answerIndex": 3, "explanation": "Correct: Listen and process consent preferences or complaints.", "passage": "", "sourcePage": 12}, {"id": "KBL-01-Q70", "number": 70, "section": "sales", "stem": "A client asks for a loan that appears unaffordable. What should the CSA do?", "options": ["Tell them to ignore instalments", "Encourage exaggerating income", "Explain suitability, repayment obligations and evaluation process", "Hide repayment cost", "Promise automatic approval"], "answerIndex": 2, "explanation": "Correct: Explain suitability, repayment obligations and evaluation process.", "passage": "", "sourcePage": 12}, {"id": "KBL-01-Q71", "number": 71, "section": "sales", "stem": "Case 1.7: A customer wants a product you do not fully understand. What should you do?", "options": ["Promise a guaranteed return", "Invent terms to appear confident", "Ask a stranger for their login", "Consult approved product information or a qualified colleague", "Skip suitability questions"], "answerIndex": 3, "explanation": "Correct: Consult approved product information or a qualified colleague.", "passage": "", "sourcePage": 12}, {"id": "KBL-01-Q72", "number": 72, "section": "sales", "stem": "A customer wants to change registered contact information. What do you do?", "options": ["Tell them to post details publicly", "Follow approved identity verification and update procedures", "Change it based on a phone call with no verification", "Accept an unknown screenshot as final proof", "Share the existing password"], "answerIndex": 1, "explanation": "Correct: Follow approved identity verification and update procedures.", "passage": "", "sourcePage": 12}, {"id": "KBL-01-Q73", "number": 73, "section": "sales", "stem": "A customer requests a complaint reference. What should you do?", "options": ["Provide the official acknowledgement or reference as applicable", "Destroy the complaint", "Promise to call from a private number only", "Share a different customer's number", "Refuse any record"], "answerIndex": 0, "explanation": "Correct: Provide the official acknowledgement or reference as applicable.", "passage": "", "sourcePage": 12}, {"id": "KBL-01-Q74", "number": 74, "section": "sales", "stem": "Case 1.10: How should a CSA respond to a service mistake?", "options": ["Delete the audit trail", "Make an unofficial cash offer", "Hide the error", "Blame the customer without evidence", "Acknowledge the issue and follow correction procedures"], "answerIndex": 4, "explanation": "Correct: Acknowledge the issue and follow correction procedures.", "passage": "", "sourcePage": 12}, {"id": "KBL-01-Q75", "number": 75, "section": "sales", "stem": "A customer asks about an SMS alert service. What should be explained?", "options": ["That passwords should be shared", "The service, eligibility and any applicable charge", "That charges never change", "Only that it is mandatory for every product", "That SMS alerts replace all fraud checks"], "answerIndex": 1, "explanation": "Correct: The service, eligibility and any applicable charge.", "passage": "", "sourcePage": 12}]}, {"id": "KBL-02", "title": "Karnataka Bank CSA Mock 02", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_02.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-02-Q1", "number": 1, "section": "verbal", "stem": "How often does the owner review cash flow?", "options": ["Every Monday", "Only at year-end", "Once a year", "Every day", "Every Friday"], "answerIndex": 4, "explanation": "Supported directly by the reading passage.", "passage": "A small business owner reviews cash flow every Friday. She records incoming payments, rent, employee salaries and loan instalments. This habit helps her plan purchases without spending money needed for upcoming bills. When sales decline in one week, she does not automatically cancel all orders; instead, she checks which costs are essential and which can be postponed.", "sourcePage": 2}, {"id": "KBL-02-Q2", "number": 2, "section": "verbal", "stem": "Why does she record planned expenses?", "options": ["To increase rent", "To stop paying salaries", "To avoid using money needed for bills", "To eliminate all sales", "To avoid keeping records"], "answerIndex": 2, "explanation": "Supported directly by the reading passage.", "passage": "A small business owner reviews cash flow every Friday. She records incoming payments, rent, employee salaries and loan instalments. This habit helps her plan purchases without spending money needed for upcoming bills. When sales decline in one week, she does not automatically cancel all orders; instead, she checks which costs are essential and which can be postponed.", "sourcePage": 2}, {"id": "KBL-02-Q3", "number": 3, "section": "verbal", "stem": "What does she do when sales fall?", "options": ["Separates essential from postponable costs", "Closes her account", "Ignores future bills", "Cancels every order immediately", "Borrows without checking expenses"], "answerIndex": 0, "explanation": "Supported directly by the reading passage.", "passage": "A small business owner reviews cash flow every Friday. She records incoming payments, rent, employee salaries and loan instalments. This habit helps her plan purchases without spending money needed for upcoming bills. When sales decline in one week, she does not automatically cancel all orders; instead, she checks which costs are essential and which can be postponed.", "sourcePage": 2}, {"id": "KBL-02-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"prudent\".", "options": ["temporary", "unclear", "rare", "wise", "reckless"], "answerIndex": 3, "explanation": "\"prudent\" is closest in meaning to \"wise\".", "passage": "", "sourcePage": 2}, {"id": "KBL-02-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"essential\".", "options": ["optional", "minor", "late", "necessary", "unusual"], "answerIndex": 3, "explanation": "\"essential\" is closest in meaning to \"necessary\".", "passage": "", "sourcePage": 2}, {"id": "KBL-02-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"temporary\".", "options": ["permanent", "brief", "momentary", "passing", "short"], "answerIndex": 0, "explanation": "The opposite of \"temporary\" is \"permanent\".", "passage": "", "sourcePage": 2}, {"id": "KBL-02-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"transparent\".", "options": ["clear", "open", "visible", "opaque", "obvious"], "answerIndex": 3, "explanation": "The opposite of \"transparent\" is \"opaque\".", "passage": "", "sourcePage": 3}, {"id": "KBL-02-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: She has worked at the branch ___ 2022.", "options": ["until", "during", "from", "since", "for"], "answerIndex": 3, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-02-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: Please submit the form ___ Friday.", "options": ["across", "beside", "onwards", "at", "by"], "answerIndex": 4, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-02-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: The customer arrived ___ time for the appointment.", "options": ["in", "of", "on", "at", "by"], "answerIndex": 2, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-02-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"The forms has been checked.\"", "options": ["The forms is been checked.", "The forms have check.", "The forms has checked.", "The forms checking.", "The forms have been checked."], "answerIndex": 4, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-02-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The manager approved the request.\"", "options": ["The request approved the manager.", "The request was approved by the manager.", "The manager was approved by the request.", "The request is approve by the manager.", "The request has approve the manager."], "answerIndex": 1, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-02-Q13", "number": 13, "section": "quant", "stem": "Find 10% of 720.", "options": ["60", "76", "68", "64", "72"], "answerIndex": 4, "explanation": "10/100 x 720 = 72.", "passage": "", "sourcePage": 3}, {"id": "KBL-02-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 3:7. If there are 160 students, how many girls are there?", "options": ["80", "64", "112", "96", "128"], "answerIndex": 2, "explanation": "One part = 160/(3+7) = 16; girls = 7 x 16.", "passage": "", "sourcePage": 4}, {"id": "KBL-02-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 1000 and sells it at 25% profit. Find the selling price (Rs).", "options": ["1230", "1270", "1250", "1210", "1190"], "answerIndex": 2, "explanation": "SP = 1000 x (1 + 25/100) = Rs 1250.", "passage": "", "sourcePage": 4}, {"id": "KBL-02-Q16", "number": 16, "section": "quant", "stem": "Find the average of 55, 59, 63, 67, 71.", "options": ["54", "66", "63", "57", "60"], "answerIndex": 2, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-02-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 16000 at 8% p.a. for 3 years.", "options": ["3360", "4000", "3840", "3520", "3680"], "answerIndex": 2, "explanation": "SI = 16000 x 8 x 3/100 = Rs 3840.", "passage": "", "sourcePage": 4}, {"id": "KBL-02-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 20000 at 10% per annum for 2 years, compounded annually.", "options": ["4400", "3600", "3800", "4200", "4000"], "answerIndex": 3, "explanation": "CI = 20000 x [(1+10/100)^2 -1] = Rs 4200.", "passage": "", "sourcePage": 4}, {"id": "KBL-02-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 6 days and B in 12 days. Working together, in how many days will they finish?", "options": ["5", "2", "1", "4", "3"], "answerIndex": 3, "explanation": "Combined time = (6 x 12)/(6+12) = 4 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-02-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 50 km/h for 5 hours. Find the distance travelled (km).", "options": ["200", "275", "225", "175", "250"], "answerIndex": 4, "explanation": "Distance = speed x time = 50 x 5 = 250 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-02-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 3, 14, 25, 36, ?", "options": ["14", "25", "47", "36", "58"], "answerIndex": 2, "explanation": "Each step adds 11.", "passage": "", "sourcePage": 5}, {"id": "KBL-02-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 2000 is sold at 10% discount. Find the selling price (Rs).", "options": ["1800", "1700", "1900", "1600", "1500"], "answerIndex": 0, "explanation": "SP = 2000 x (100-10)/100 = Rs 1800.", "passage": "", "sourcePage": 5}, {"id": "KBL-02-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 150 accounts on Monday and 90 on Tuesday. Branch B opened 90 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["330", "300", "310", "340", "320"], "answerIndex": 0, "explanation": "Total = 150 + 90 + 90 = 330.", "passage": "", "sourcePage": 5}, {"id": "KBL-02-Q24", "number": 24, "section": "quant", "stem": "Ravi is 12 years older than Meera. Their present ages add up to 52 years. What is Ravi's age?", "options": ["32", "30", "26", "28", "34"], "answerIndex": 0, "explanation": "Older age = (sum + difference)/2 = (52+12)/2 = 32.", "passage": "", "sourcePage": 5}, {"id": "KBL-02-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 6 and 12 hours; pipe C empties it in 6 hours. If all are opened together, when will the tank fill?", "options": ["14", "12", "10", "8", "6"], "answerIndex": 1, "explanation": "Net filling rate = 1/6 + 1/12 - 1/6 = 1/12 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-02-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 20 L and 10 L respectively. What is the simplified milk:water ratio?", "options": ["2:1", "3:1", "1:2", "4:1", "2:2"], "answerIndex": 0, "explanation": "Divide both quantities by HCF = 10.", "passage": "", "sourcePage": 5}, {"id": "KBL-02-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 1000. Its price rises by 20% and then falls by 20%. Find its final price (Rs).", "options": ["860", "810", "1010", "910", "960"], "answerIndex": 4, "explanation": "Final price = 1000 x 120/100 x 80/100 = 960.", "passage": "", "sourcePage": 5}, {"id": "KBL-02-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 2 place(s) forward in the alphabet. How is COIN coded?", "options": ["EQKP", "HTNS", "COIN", "GSMR", "IUOT"], "answerIndex": 0, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-02-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 44 people, A is 29th from the front. What is A's rank from the back?", "options": ["14", "15", "16", "17", "13"], "answerIndex": 2, "explanation": "Back rank = total - front rank +1 = 44-29+1 = 16.", "passage": "", "sourcePage": 6}, {"id": "KBL-02-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 3 km east, then 4 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["21", "17", "29", "13", "25"], "answerIndex": 4, "explanation": "Pythagoras: distance squared = 3^2 + 4^2 = 25.", "passage": "", "sourcePage": 6}, {"id": "KBL-02-Q31", "number": 31, "section": "reasoning", "stem": "A person faces West and turns 90 degrees to the left. Which direction does the person now face?", "options": ["West", "Cannot be determined", "East", "North", "South"], "answerIndex": 4, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-02-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All pens are items. Some items are files. Which conclusion definitely follows?", "options": ["All files are items", "All items are pens", "All files are pens", "No pens are items", "Some items are pens"], "answerIndex": 4, "explanation": "All pens are items implies some items are pens in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-02-Q33", "number": 33, "section": "reasoning", "stem": "Given F > L = C > K, which relation definitely holds?", "options": ["C = K", "K > F", "F = K", "L < K", "F > K"], "answerIndex": 4, "explanation": "Chain: F > L = C > K, so F > K.", "passage": "", "sourcePage": 6}, {"id": "KBL-02-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: K, E, G, F, A. Who sits immediately to the right of G?", "options": ["F", "A", "K", "G", "E"], "answerIndex": 0, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-02-Q35", "number": 35, "section": "reasoning", "stem": "Divya is the mother of Pooja. Leena is the sister of Pooja. How is Divya related to Leena?", "options": ["Aunt", "Mother", "Grandmother", "Sister", "Daughter"], "answerIndex": 1, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-02-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: R > T > S > V > X. Who is immediately heavier than S?", "options": ["X", "V", "S", "R", "T"], "answerIndex": 4, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-02-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 18, 54, 162, 486, ?", "options": ["1512", "1458", "1404", "1350", "1296"], "answerIndex": 1, "explanation": "Every term is multiplied by 3.", "passage": "", "sourcePage": 7}, {"id": "KBL-02-Q38", "number": 38, "section": "reasoning", "stem": "If today is Sunday, what day of the week will it be after 17 days?", "options": ["Tuesday", "Thursday", "Saturday", "Friday", "Wednesday"], "answerIndex": 4, "explanation": "Advance 3 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-02-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are D, A, K, L, N. Who occupies floor 3?", "options": ["A", "L", "K", "D", "N"], "answerIndex": 2, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-02-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in BANKING?", "options": ["ABGIKNN", "GBANKIN", "ANKINGB", "BANKING", "GNIKNAB"], "answerIndex": 4, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-02-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 5?", "options": ["10", "36", "25", "15", "20"], "answerIndex": 1, "explanation": "36 leaves a remainder when divided by 5.", "passage": "", "sourcePage": 8}, {"id": "KBL-02-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 10 km east, then 3 km west. Where is the final position relative to the starting point?", "options": ["7 km west", "7 km east", "13 km east", "10 km north", "13 km west"], "answerIndex": 1, "explanation": "Net eastward movement = 10-3 = 7 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-02-Q43", "number": 43, "section": "gk", "stem": "What is the main purpose of deposit insurance?", "options": ["Eliminate loan repayment", "Replace financial statements", "Prevent all banking fraud", "Protect eligible deposits within applicable limits", "Guarantee every investment return"], "answerIndex": 3, "explanation": "Correct: Protect eligible deposits within applicable limits.", "passage": "", "sourcePage": 8}, {"id": "KBL-02-Q44", "number": 44, "section": "gk", "stem": "Which is an example of a collateral-backed loan?", "options": ["Interest-free grant", "Loan with no security by definition", "ATM withdrawal", "Salary slip", "Loan secured by pledged property"], "answerIndex": 4, "explanation": "Correct: Loan secured by pledged property.", "passage": "", "sourcePage": 8}, {"id": "KBL-02-Q45", "number": 45, "section": "gk", "stem": "What is the role of a bank branch manager?", "options": ["Approve weather forecasts", "Issue driving permits", "Control national elections", "Print government passports", "Oversee branch operations and service"], "answerIndex": 4, "explanation": "Correct: Oversee branch operations and service.", "passage": "", "sourcePage": 8}, {"id": "KBL-02-Q46", "number": 46, "section": "gk", "stem": "What is the purpose of a recurring deposit?", "options": ["Create a debit card PIN", "Withdraw cash without an account", "Eliminate financial planning", "Save a fixed amount at regular intervals", "Borrow a fixed amount daily"], "answerIndex": 3, "explanation": "Correct: Save a fixed amount at regular intervals.", "passage": "", "sourcePage": 8}, {"id": "KBL-02-Q47", "number": 47, "section": "gk", "stem": "Which institution is the central bank of India?", "options": ["SIDBI", "SEBI", "NABARD", "State Bank of India", "Reserve Bank of India"], "answerIndex": 4, "explanation": "Correct: Reserve Bank of India.", "passage": "", "sourcePage": 8}, {"id": "KBL-02-Q48", "number": 48, "section": "gk", "stem": "What does IFSC identify?", "options": ["ATM cash level", "Customer age", "Account balance", "Bank branch for electronic payments", "Cheque paper quality"], "answerIndex": 3, "explanation": "Correct: Bank branch for electronic payments.", "passage": "", "sourcePage": 9}, {"id": "KBL-02-Q49", "number": 49, "section": "gk", "stem": "What is a standing instruction?", "options": ["An authorisation for recurring account transactions", "A cheque without a date", "A banknote verification stamp", "A branch opening advertisement", "A request to close every account"], "answerIndex": 0, "explanation": "Correct: An authorisation for recurring account transactions.", "passage": "", "sourcePage": 9}, {"id": "KBL-02-Q50", "number": 50, "section": "gk", "stem": "Which money is usually held to meet near-term cash needs?", "options": ["Fixed assets only", "Liquid funds", "Building depreciation", "Inventory write-off", "Goodwill"], "answerIndex": 1, "explanation": "Correct: Liquid funds.", "passage": "", "sourcePage": 9}, {"id": "KBL-02-Q51", "number": 51, "section": "gk", "stem": "What does EMI mean?", "options": ["Equated Monthly Instalment", "Emergency Monetary Insurance", "Equal Monthly Income", "Electronic Money Index", "Easy Market Investment"], "answerIndex": 0, "explanation": "Correct: Equated Monthly Instalment.", "passage": "", "sourcePage": 9}, {"id": "KBL-02-Q52", "number": 52, "section": "gk", "stem": "What is a bank overdraft?", "options": ["A free insurance guarantee", "A cash deposit receipt", "A fixed investment return", "A currency exchange rate", "An approved facility allowing debit beyond available balance up to a limit"], "answerIndex": 4, "explanation": "Correct: An approved facility allowing debit beyond available balance up to a limit.", "passage": "", "sourcePage": 9}, {"id": "KBL-02-Q53", "number": 53, "section": "gk", "stem": "What does a bank sanction letter generally convey?", "options": ["A property sale agreement", "A pension card", "Final proof all instalments were paid", "Terms of a credit facility approved subject to conditions", "A withdrawal receipt"], "answerIndex": 3, "explanation": "Correct: Terms of a credit facility approved subject to conditions.", "passage": "", "sourcePage": 9}, {"id": "KBL-02-Q54", "number": 54, "section": "computer", "stem": "What is two-factor authentication?", "options": ["Running two browsers", "Using two keyboards", "Using two different proof factors for login", "Keeping two bank accounts", "Entering the same password twice"], "answerIndex": 2, "explanation": "Correct: Using two different proof factors for login.", "passage": "", "sourcePage": 9}, {"id": "KBL-02-Q55", "number": 55, "section": "computer", "stem": "What is the default function of Ctrl+Z in many applications?", "options": ["Zoom to 100%", "Save", "Print", "Paste", "Undo"], "answerIndex": 4, "explanation": "Correct: Undo.", "passage": "", "sourcePage": 10}, {"id": "KBL-02-Q56", "number": 56, "section": "computer", "stem": "Which storage device usually has no moving mechanical disks?", "options": ["Magnetic tape drive", "Hard disk drive", "DVD drive", "SSD", "Floppy drive"], "answerIndex": 3, "explanation": "Correct: SSD.", "passage": "", "sourcePage": 10}, {"id": "KBL-02-Q57", "number": 57, "section": "computer", "stem": "Which tool can help compare two sets of numbers visually?", "options": ["Antivirus scan", "Password manager alone", "Keyboard driver", "Operating-system update", "Chart"], "answerIndex": 4, "explanation": "Correct: Chart.", "passage": "", "sourcePage": 10}, {"id": "KBL-02-Q58", "number": 58, "section": "computer", "stem": "What is an operating-system user account used for?", "options": ["To guarantee a loan", "Only to calculate interest", "Only to scan cheques", "Managing individual access and settings", "To control the national currency"], "answerIndex": 3, "explanation": "Correct: Managing individual access and settings.", "passage": "", "sourcePage": 10}, {"id": "KBL-02-Q59", "number": 59, "section": "computer", "stem": "What is a computer virus?", "options": ["A computer monitor", "An internet cable", "Malicious code that can replicate by infecting files or programs", "A normal spreadsheet formula", "A bank cheque"], "answerIndex": 2, "explanation": "Correct: Malicious code that can replicate by infecting files or programs.", "passage": "", "sourcePage": 10}, {"id": "KBL-02-Q60", "number": 60, "section": "computer", "stem": "What is a cache?", "options": ["A tax deduction", "A type of keyboard layout only", "A loan guarantee", "A mandatory paper passbook", "Storage that helps speed up repeated access to data"], "answerIndex": 4, "explanation": "Correct: Storage that helps speed up repeated access to data.", "passage": "", "sourcePage": 10}, {"id": "KBL-02-Q61", "number": 61, "section": "computer", "stem": "Which file extension is common for modern Excel workbooks?", "options": [".exe", ".zip", ".png", ".xlsx", ".mp3"], "answerIndex": 3, "explanation": "Correct: .xlsx.", "passage": "", "sourcePage": 10}, {"id": "KBL-02-Q62", "number": 62, "section": "computer", "stem": "What does PDF stand for?", "options": ["Personal Data Folder", "Portable Document Format", "Public Display File", "Program Data Form", "Printed Document Function"], "answerIndex": 1, "explanation": "Correct: Portable Document Format.", "passage": "", "sourcePage": 11}, {"id": "KBL-02-Q63", "number": 63, "section": "computer", "stem": "What is a backup?", "options": ["A web advertisement", "A deleted file only", "A separate copy of data for recovery", "A renamed folder", "A bank overdraft"], "answerIndex": 2, "explanation": "Correct: A separate copy of data for recovery.", "passage": "", "sourcePage": 11}, {"id": "KBL-02-Q64", "number": 64, "section": "computer", "stem": "What is the main purpose of a strong password?", "options": ["Speed up broadband automatically", "Reduce risk of unauthorised account access", "Increase screen brightness", "Create credit history", "Improve print quality"], "answerIndex": 1, "explanation": "Correct: Reduce risk of unauthorised account access.", "passage": "", "sourcePage": 11}, {"id": "KBL-02-Q65", "number": 65, "section": "sales", "stem": "Case 2.1: How should a CSA respond to a service mistake?", "options": ["Delete the audit trail", "Acknowledge the issue and follow correction procedures", "Blame the customer without evidence", "Make an unofficial cash offer", "Hide the error"], "answerIndex": 1, "explanation": "Correct: Acknowledge the issue and follow correction procedures.", "passage": "", "sourcePage": 11}, {"id": "KBL-02-Q66", "number": 66, "section": "sales", "stem": "A customer asks about an SMS alert service. What should be explained?", "options": ["The service, eligibility and any applicable charge", "That passwords should be shared", "Only that it is mandatory for every product", "That charges never change", "That SMS alerts replace all fraud checks"], "answerIndex": 0, "explanation": "Correct: The service, eligibility and any applicable charge.", "passage": "", "sourcePage": 11}, {"id": "KBL-02-Q67", "number": 67, "section": "sales", "stem": "You are unsure whether a customer qualifies for an offer. What should you do?", "options": ["Ask for cash to secure the offer", "Invent a waiver", "Say they qualify without checking", "Check eligibility using verified bank rules", "Change the eligibility rules"], "answerIndex": 3, "explanation": "Correct: Check eligibility using verified bank rules.", "passage": "", "sourcePage": 11}, {"id": "KBL-02-Q68", "number": 68, "section": "sales", "stem": "Case 2.4: An elderly visitor struggles with a digital token machine. What is best?", "options": ["Mock the visitor", "Collect their password", "Skip verification rules", "Offer respectful assistance and explain the process", "Ask the visitor to leave"], "answerIndex": 3, "explanation": "Correct: Offer respectful assistance and explain the process.", "passage": "", "sourcePage": 11}, {"id": "KBL-02-Q69", "number": 69, "section": "sales", "stem": "A customer notices an unknown debit. What is the correct action?", "options": ["Post their account details online", "Guide them to report it promptly through official channels", "Guarantee funds will return without investigation", "Ask for their PIN", "Tell them to ignore it"], "answerIndex": 1, "explanation": "Correct: Guide them to report it promptly through official channels.", "passage": "", "sourcePage": 12}, {"id": "KBL-02-Q70", "number": 70, "section": "sales", "stem": "A client has not understood the difference between debit and credit cards. What is best?", "options": ["Ignore interest and charges", "Explain how each works, including repayment terms for credit cards", "Say the two products are identical", "Emphasise benefits only", "Request card PINs"], "answerIndex": 1, "explanation": "Correct: Explain how each works, including repayment terms for credit cards.", "passage": "", "sourcePage": 12}, {"id": "KBL-02-Q71", "number": 71, "section": "sales", "stem": "Case 2.7: A customer asks about a fee waiver. What is the best response?", "options": ["Check eligibility and the published policy", "Change the fee table personally", "Promise a waiver to everyone", "Ask for an unofficial payment", "Avoid documenting the request"], "answerIndex": 0, "explanation": "Correct: Check eligibility and the published policy.", "passage": "", "sourcePage": 12}, {"id": "KBL-02-Q72", "number": 72, "section": "sales", "stem": "The customer is considering a loan but worries about instalments. What helps?", "options": ["Focus only on the maximum loan amount", "Omit interest rates", "Promise a grant", "Show repayment obligations and assess affordability", "Suggest hiding existing debts"], "answerIndex": 3, "explanation": "Correct: Show repayment obligations and assess affordability.", "passage": "", "sourcePage": 12}, {"id": "KBL-02-Q73", "number": 73, "section": "sales", "stem": "A client wants to open an account for another adult without that person present or authorised. What is best?", "options": ["Explain valid account-opening and authorisation requirements", "Skip all consent", "Forge the absent person's signature", "Create a fictional address", "Use your own identity"], "answerIndex": 0, "explanation": "Correct: Explain valid account-opening and authorisation requirements.", "passage": "", "sourcePage": 12}, {"id": "KBL-02-Q74", "number": 74, "section": "sales", "stem": "Case 2.10: A customer forgot online-banking credentials. What is best?", "options": ["Ask for an old password aloud", "Disable all verification", "Guide them through official recovery after verification", "Share an employee's password", "Set a shared password for everyone"], "answerIndex": 2, "explanation": "Correct: Guide them through official recovery after verification.", "passage": "", "sourcePage": 12}, {"id": "KBL-02-Q75", "number": 75, "section": "sales", "stem": "A customer says the mobile banking app feels unsafe. What should the CSA do?", "options": ["Force immediate enrolment", "Explain security features, verify needs, and offer guided help", "Dismiss the concern", "Ask for the OTP to demonstrate", "Promise no digital fraud can ever occur"], "answerIndex": 1, "explanation": "Correct: Explain security features, verify needs, and offer guided help.", "passage": "", "sourcePage": 12}]}, {"id": "KBL-03", "title": "Karnataka Bank CSA Mock 03", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_03.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-03-Q1", "number": 1, "section": "verbal", "stem": "What was the workshop mainly about?", "options": ["Recognising banking fraud", "Choosing a television", "Printing cheques", "Learning to drive", "Calculating interest"], "answerIndex": 0, "explanation": "Supported directly by the reading passage.", "passage": "A community workshop taught first-time customers how to recognise fraudulent banking messages. Participants learned that genuine bank staff never ask for a one-time password. They also practised checking the address of a banking website before logging in. The organisers emphasised that a quick phone call to the bank can prevent a costly mistake when a message appears suspicious.", "sourcePage": 2}, {"id": "KBL-03-Q2", "number": 2, "section": "verbal", "stem": "Which information should never be shared with a caller?", "options": ["Branch opening hours", "One-time password", "Published loan rates", "Public ATM location", "Bank website home page"], "answerIndex": 1, "explanation": "Supported directly by the reading passage.", "passage": "A community workshop taught first-time customers how to recognise fraudulent banking messages. Participants learned that genuine bank staff never ask for a one-time password. They also practised checking the address of a banking website before logging in. The organisers emphasised that a quick phone call to the bank can prevent a costly mistake when a message appears suspicious.", "sourcePage": 2}, {"id": "KBL-03-Q3", "number": 3, "section": "verbal", "stem": "What can customers do when a message seems suspicious?", "options": ["Download an unknown app", "Ignore account alerts forever", "Contact the bank through an official number", "Share the message widely", "Send the OTP immediately"], "answerIndex": 2, "explanation": "Supported directly by the reading passage.", "passage": "A community workshop taught first-time customers how to recognise fraudulent banking messages. Participants learned that genuine bank staff never ask for a one-time password. They also practised checking the address of a banking website before logging in. The organisers emphasised that a quick phone call to the bank can prevent a costly mistake when a message appears suspicious.", "sourcePage": 2}, {"id": "KBL-03-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"reliable\".", "options": ["temporary", "careless", "fragile", "doubtful", "dependable"], "answerIndex": 4, "explanation": "\"reliable\" is closest in meaning to \"dependable\".", "passage": "", "sourcePage": 2}, {"id": "KBL-03-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"transparent\".", "options": ["distant", "hidden", "slow", "costly", "open"], "answerIndex": 4, "explanation": "\"transparent\" is closest in meaning to \"open\".", "passage": "", "sourcePage": 2}, {"id": "KBL-03-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"accept\".", "options": ["reject", "receive", "welcome", "approve", "admit"], "answerIndex": 0, "explanation": "The opposite of \"accept\" is \"reject\".", "passage": "", "sourcePage": 2}, {"id": "KBL-03-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"optimistic\".", "options": ["confident", "positive", "pessimistic", "cheerful", "hopeful"], "answerIndex": 2, "explanation": "The opposite of \"optimistic\" is \"pessimistic\".", "passage": "", "sourcePage": 3}, {"id": "KBL-03-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: The funds ___ transferred yesterday.", "options": ["were", "was", "is", "be", "has"], "answerIndex": 0, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-03-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: Each of the applicants ___ an identity proof.", "options": ["were", "are", "have", "be", "has"], "answerIndex": 4, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-03-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: Hardly had the branch opened ___ customers began to queue.", "options": ["because", "that", "when", "than", "then"], "answerIndex": 2, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-03-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"They was waiting near the counter.\"", "options": ["They is waiting near the counter.", "They were wait near the counter.", "They were waiting near the counter.", "They be waiting near the counter.", "They has waiting near the counter."], "answerIndex": 2, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-03-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The team completed the audit.\"", "options": ["The audit completed the team.", "The audit is completing by the team.", "The audit were completed by the team.", "The team was completed by the audit.", "The audit was completed by the team."], "answerIndex": 4, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-03-Q13", "number": 13, "section": "quant", "stem": "Find 30% of 240.", "options": ["48", "56", "80", "72", "64"], "answerIndex": 3, "explanation": "30/100 x 240 = 72.", "passage": "", "sourcePage": 3}, {"id": "KBL-03-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 3:5. If there are 120 students, how many girls are there?", "options": ["90", "45", "30", "75", "60"], "answerIndex": 3, "explanation": "One part = 120/(3+5) = 15; girls = 5 x 15.", "passage": "", "sourcePage": 4}, {"id": "KBL-03-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 1600 and sells it at 10% profit. Find the selling price (Rs).", "options": ["1792", "1664", "1696", "1760", "1728"], "answerIndex": 3, "explanation": "SP = 1600 x (1 + 10/100) = Rs 1760.", "passage": "", "sourcePage": 4}, {"id": "KBL-03-Q16", "number": 16, "section": "quant", "stem": "Find the average of 61, 65, 69, 73, 77.", "options": ["63", "66", "69", "60", "72"], "answerIndex": 2, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-03-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 16000 at 10% p.a. for 2 years.", "options": ["2720", "3040", "3200", "2880", "3360"], "answerIndex": 2, "explanation": "SI = 16000 x 10 x 2/100 = Rs 3200.", "passage": "", "sourcePage": 4}, {"id": "KBL-03-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 20000 at 20% per annum for 2 years, compounded annually.", "options": ["8400", "8600", "9000", "8800", "8200"], "answerIndex": 3, "explanation": "CI = 20000 x [(1+20/100)^2 -1] = Rs 8800.", "passage": "", "sourcePage": 4}, {"id": "KBL-03-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 6 days and B in 12 days. Working together, in how many days will they finish?", "options": ["2", "5", "1", "3", "4"], "answerIndex": 4, "explanation": "Combined time = (6 x 12)/(6+12) = 4 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-03-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 60 km/h for 5 hours. Find the distance travelled (km).", "options": ["270", "300", "330", "210", "240"], "answerIndex": 1, "explanation": "Distance = speed x time = 60 x 5 = 300 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-03-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 12, 19, 26, 33, ?", "options": ["33", "26", "47", "40", "19"], "answerIndex": 3, "explanation": "Each step adds 7.", "passage": "", "sourcePage": 5}, {"id": "KBL-03-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 1200 is sold at 20% discount. Find the selling price (Rs).", "options": ["960", "900", "1020", "840", "780"], "answerIndex": 0, "explanation": "SP = 1200 x (100-20)/100 = Rs 960.", "passage": "", "sourcePage": 5}, {"id": "KBL-03-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 220 accounts on Monday and 160 on Tuesday. Branch B opened 170 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["550", "530", "560", "540", "520"], "answerIndex": 0, "explanation": "Total = 220 + 160 + 170 = 550.", "passage": "", "sourcePage": 5}, {"id": "KBL-03-Q24", "number": 24, "section": "quant", "stem": "Ravi is 8 years older than Meera. Their present ages add up to 40 years. What is Ravi's age?", "options": ["24", "22", "20", "26", "18"], "answerIndex": 0, "explanation": "Older age = (sum + difference)/2 = (40+8)/2 = 24.", "passage": "", "sourcePage": 5}, {"id": "KBL-03-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 10 and 20 hours; pipe C empties it in 10 hours. If all are opened together, when will the tank fill?", "options": ["20", "16", "14", "18", "22"], "answerIndex": 0, "explanation": "Net filling rate = 1/10 + 1/20 - 1/10 = 1/20 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-03-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 20 L and 15 L respectively. What is the simplified milk:water ratio?", "options": ["3:4", "4:3", "6:3", "4:4", "5:3"], "answerIndex": 1, "explanation": "Divide both quantities by HCF = 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-03-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 400. Its price rises by 10% and then falls by 20%. Find its final price (Rs).", "options": ["372", "292", "332", "312", "352"], "answerIndex": 4, "explanation": "Final price = 400 x 110/100 x 80/100 = 352.", "passage": "", "sourcePage": 5}, {"id": "KBL-03-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 2 place(s) forward in the alphabet. How is CARD coded?", "options": ["IGXJ", "GEVH", "CARD", "ECTF", "HFWI"], "answerIndex": 3, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-03-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 72 people, A is 8th from the front. What is A's rank from the back?", "options": ["66", "64", "65", "63", "62"], "answerIndex": 2, "explanation": "Back rank = total - front rank +1 = 72-8+1 = 65.", "passage": "", "sourcePage": 6}, {"id": "KBL-03-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 4 km east, then 7 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["69", "53", "65", "61", "57"], "answerIndex": 2, "explanation": "Pythagoras: distance squared = 4^2 + 7^2 = 65.", "passage": "", "sourcePage": 6}, {"id": "KBL-03-Q31", "number": 31, "section": "reasoning", "stem": "A person faces East and turns 90 degrees to the right. Which direction does the person now face?", "options": ["South", "West", "North", "Cannot be determined", "East"], "answerIndex": 0, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-03-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All chairs are furniture. Some furniture are tables. Which conclusion definitely follows?", "options": ["All tables are chairs", "All furniture are chairs", "No chairs are furniture", "Some furniture are chairs", "All tables are furniture"], "answerIndex": 3, "explanation": "All chairs are furniture implies some furniture are chairs in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-03-Q33", "number": 33, "section": "reasoning", "stem": "Given H > P = F > A, which relation definitely holds?", "options": ["H = A", "F = A", "A > H", "P < A", "H > A"], "answerIndex": 4, "explanation": "Chain: H > P = F > A, so H > A.", "passage": "", "sourcePage": 6}, {"id": "KBL-03-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: C, D, A, E, B. Who sits immediately to the right of D?", "options": ["C", "E", "D", "A", "B"], "answerIndex": 3, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-03-Q35", "number": 35, "section": "reasoning", "stem": "Leena is the mother of Rina. Pooja is the sister of Rina. How is Leena related to Pooja?", "options": ["Daughter", "Grandmother", "Sister", "Aunt", "Mother"], "answerIndex": 4, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-03-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: P > X > T > S > V. Who is immediately heavier than S?", "options": ["V", "P", "S", "X", "T"], "answerIndex": 4, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-03-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 10, 20, 40, 80, ?", "options": ["100", "160", "120", "180", "140"], "answerIndex": 1, "explanation": "Every term is multiplied by 2.", "passage": "", "sourcePage": 7}, {"id": "KBL-03-Q38", "number": 38, "section": "reasoning", "stem": "If today is Thursday, what day of the week will it be after 23 days?", "options": ["Wednesday", "Thursday", "Friday", "Tuesday", "Saturday"], "answerIndex": 4, "explanation": "Advance 2 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-03-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are K, D, M, E, B. Who occupies floor 4?", "options": ["E", "B", "K", "D", "M"], "answerIndex": 0, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-03-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in CASHIER?", "options": ["ACEHIRS", "RCASHIE", "CASHIER", "ASHIERC", "REIHSAC"], "answerIndex": 4, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-03-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 5?", "options": ["20", "15", "25", "36", "10"], "answerIndex": 3, "explanation": "36 leaves a remainder when divided by 5.", "passage": "", "sourcePage": 8}, {"id": "KBL-03-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 8 km east, then 5 km west. Where is the final position relative to the starting point?", "options": ["8 km north", "3 km east", "3 km west", "13 km west", "13 km east"], "answerIndex": 1, "explanation": "Net eastward movement = 8-5 = 3 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-03-Q43", "number": 43, "section": "gk", "stem": "What is a bank overdraft?", "options": ["A currency exchange rate", "An approved facility allowing debit beyond available balance up to a limit", "A free insurance guarantee", "A cash deposit receipt", "A fixed investment return"], "answerIndex": 1, "explanation": "Correct: An approved facility allowing debit beyond available balance up to a limit.", "passage": "", "sourcePage": 8}, {"id": "KBL-03-Q44", "number": 44, "section": "gk", "stem": "What does a bank sanction letter generally convey?", "options": ["A withdrawal receipt", "Terms of a credit facility approved subject to conditions", "A pension card", "Final proof all instalments were paid", "A property sale agreement"], "answerIndex": 1, "explanation": "Correct: Terms of a credit facility approved subject to conditions.", "passage": "", "sourcePage": 8}, {"id": "KBL-03-Q45", "number": 45, "section": "gk", "stem": "Which channel is commonly used to make instant UPI payments?", "options": ["Only postal mail", "A printed passbook only", "A paper ledger only", "An unsigned cheque", "A compatible payment app"], "answerIndex": 4, "explanation": "Correct: A compatible payment app.", "passage": "", "sourcePage": 8}, {"id": "KBL-03-Q46", "number": 46, "section": "gk", "stem": "Which of these usually earns interest for a fixed agreed tenure?", "options": ["Current account", "Passbook", "Fixed deposit", "Demand draft", "Debit card"], "answerIndex": 2, "explanation": "Correct: Fixed deposit.", "passage": "", "sourcePage": 8}, {"id": "KBL-03-Q47", "number": 47, "section": "gk", "stem": "Which payment instrument is a written order directing a bank to pay?", "options": ["Passbook", "Balance sheet", "Invoice", "Cheque", "Receipt"], "answerIndex": 3, "explanation": "Correct: Cheque.", "passage": "", "sourcePage": 8}, {"id": "KBL-03-Q48", "number": 48, "section": "gk", "stem": "Which type of rate is used for RBI lending to banks under a repo transaction?", "options": ["Stamp duty", "Repo rate", "GST rate", "Dividend yield", "Exchange commission"], "answerIndex": 1, "explanation": "Correct: Repo rate.", "passage": "", "sourcePage": 9}, {"id": "KBL-03-Q49", "number": 49, "section": "gk", "stem": "What is a credit score intended to help assess?", "options": ["Branch temperature", "Creditworthiness", "Mobile data speed", "Physical cash weight", "Height of a customer"], "answerIndex": 1, "explanation": "Correct: Creditworthiness.", "passage": "", "sourcePage": 9}, {"id": "KBL-03-Q50", "number": 50, "section": "gk", "stem": "A transaction reference number helps to do what?", "options": ["Change the account type automatically", "Create currency", "Set the interest rate", "Track or identify a specific transaction", "Reveal the customer PIN"], "answerIndex": 3, "explanation": "Correct: Track or identify a specific transaction.", "passage": "", "sourcePage": 9}, {"id": "KBL-03-Q51", "number": 51, "section": "gk", "stem": "What is the meaning of liquidity for an asset?", "options": ["Its physical size", "Its tax bracket always", "Ease of turning it into cash with limited loss", "Its storage location only", "Its printed colour"], "answerIndex": 2, "explanation": "Correct: Ease of turning it into cash with limited loss.", "passage": "", "sourcePage": 9}, {"id": "KBL-03-Q52", "number": 52, "section": "gk", "stem": "What is interest on a deposit?", "options": ["Amount paid by the bank under the deposit terms", "The customer identity number", "An ATM access code", "A penalty on every cash withdrawal", "Branch rent"], "answerIndex": 0, "explanation": "Correct: Amount paid by the bank under the deposit terms.", "passage": "", "sourcePage": 9}, {"id": "KBL-03-Q53", "number": 53, "section": "gk", "stem": "What does ATM stand for?", "options": ["Automatic Transfer Money", "Account Tracking Module", "Automated Teller Machine", "Automated Tax Machine", "Approved Transaction Method"], "answerIndex": 2, "explanation": "Correct: Automated Teller Machine.", "passage": "", "sourcePage": 9}, {"id": "KBL-03-Q54", "number": 54, "section": "computer", "stem": "What is the main purpose of a strong password?", "options": ["Reduce risk of unauthorised account access", "Increase screen brightness", "Speed up broadband automatically", "Improve print quality", "Create credit history"], "answerIndex": 0, "explanation": "Correct: Reduce risk of unauthorised account access.", "passage": "", "sourcePage": 9}, {"id": "KBL-03-Q55", "number": 55, "section": "computer", "stem": "What does SQL stand for?", "options": ["System Query Loop", "Sequential Quality Link", "Standard Quick Logic", "Secure Queue Ledger", "Structured Query Language"], "answerIndex": 4, "explanation": "Correct: Structured Query Language.", "passage": "", "sourcePage": 10}, {"id": "KBL-03-Q56", "number": 56, "section": "computer", "stem": "What is software update primarily used for?", "options": ["Increasing electricity voltage", "Printing cash vouchers", "Changing the computer's weight", "Replacing all files with images", "Applying improvements and security fixes"], "answerIndex": 4, "explanation": "Correct: Applying improvements and security fixes.", "passage": "", "sourcePage": 10}, {"id": "KBL-03-Q57", "number": 57, "section": "computer", "stem": "Which part of a computer executes arithmetic and logic operations?", "options": ["Cooling fan", "Display panel", "ALU", "Optical drive", "Printer port"], "answerIndex": 2, "explanation": "Correct: ALU.", "passage": "", "sourcePage": 10}, {"id": "KBL-03-Q58", "number": 58, "section": "computer", "stem": "What does DNS commonly do?", "options": ["Maps domain names to IP addresses", "Provides loan interest", "Prints pages", "Increases hardware RAM", "Deletes all cookies"], "answerIndex": 0, "explanation": "Correct: Maps domain names to IP addresses.", "passage": "", "sourcePage": 10}, {"id": "KBL-03-Q59", "number": 59, "section": "computer", "stem": "What is a web browser used for?", "options": ["Cooling a computer", "Changing network cables", "Scanning banknotes", "Accessing web pages", "Printing cheques only"], "answerIndex": 3, "explanation": "Correct: Accessing web pages.", "passage": "", "sourcePage": 10}, {"id": "KBL-03-Q60", "number": 60, "section": "computer", "stem": "Which keyboard shortcut typically saves a document?", "options": ["Ctrl+S", "Ctrl+F", "Ctrl+O", "Ctrl+N", "Ctrl+A"], "answerIndex": 0, "explanation": "Correct: Ctrl+S.", "passage": "", "sourcePage": 10}, {"id": "KBL-03-Q61", "number": 61, "section": "computer", "stem": "Which formula adds cells A1 to A5 in Excel?", "options": ["=ADD(A1-A5)", "=COUNT(A1:A5)", "=PLUS(A1,A5)", "=TOTAL(A1:A5)", "=SUM(A1:A5)"], "answerIndex": 4, "explanation": "Correct: =SUM(A1:A5).", "passage": "", "sourcePage": 10}, {"id": "KBL-03-Q62", "number": 62, "section": "computer", "stem": "What is an email attachment?", "options": ["A phone call", "A file sent along with an email message", "The subject line only", "The inbox folder only", "The sender's password"], "answerIndex": 1, "explanation": "Correct: A file sent along with an email message.", "passage": "", "sourcePage": 11}, {"id": "KBL-03-Q63", "number": 63, "section": "computer", "stem": "What is a database?", "options": ["An ink cartridge", "A cash drawer", "Only a monitor", "A keyboard shortcut", "Organised collection of data"], "answerIndex": 4, "explanation": "Correct: Organised collection of data.", "passage": "", "sourcePage": 11}, {"id": "KBL-03-Q64", "number": 64, "section": "computer", "stem": "Which is safer for online banking?", "options": ["Saving PIN in public notes", "Sharing OTP in chat", "Disabling all security checks", "Using the official site or app and verifying its address", "Following an unknown short link"], "answerIndex": 3, "explanation": "Correct: Using the official site or app and verifying its address.", "passage": "", "sourcePage": 11}, {"id": "KBL-03-Q65", "number": 65, "section": "sales", "stem": "Case 3.1: A customer forgot online-banking credentials. What is best?", "options": ["Set a shared password for everyone", "Share an employee's password", "Guide them through official recovery after verification", "Disable all verification", "Ask for an old password aloud"], "answerIndex": 2, "explanation": "Correct: Guide them through official recovery after verification.", "passage": "", "sourcePage": 11}, {"id": "KBL-03-Q66", "number": 66, "section": "sales", "stem": "A customer says the mobile banking app feels unsafe. What should the CSA do?", "options": ["Dismiss the concern", "Explain security features, verify needs, and offer guided help", "Promise no digital fraud can ever occur", "Ask for the OTP to demonstrate", "Force immediate enrolment"], "answerIndex": 1, "explanation": "Correct: Explain security features, verify needs, and offer guided help.", "passage": "", "sourcePage": 11}, {"id": "KBL-03-Q67", "number": 67, "section": "sales", "stem": "A customer asks which savings account suits frequent withdrawals. What is best?", "options": ["Recommend a long lock-in without asking", "Open accounts without approval", "Ask about usage and compare account features transparently", "Sell only the account with the highest sales incentive", "Hide account fees"], "answerIndex": 2, "explanation": "Correct: Ask about usage and compare account features transparently.", "passage": "", "sourcePage": 11}, {"id": "KBL-03-Q68", "number": 68, "section": "sales", "stem": "Case 3.4: A customer asks for loan processing charges. What should you do?", "options": ["Hide charges until after signature", "State the applicable charges and refer to official disclosures", "Ask the customer to pay your personal account", "Make up a lower fee", "Say there are never any charges"], "answerIndex": 1, "explanation": "Correct: State the applicable charges and refer to official disclosures.", "passage": "", "sourcePage": 11}, {"id": "KBL-03-Q69", "number": 69, "section": "sales", "stem": "Your sales target conflicts with customer suitability. Which takes priority?", "options": ["Customer suitability and compliance", "Highest sales commission", "Closing a sale irrespective of need", "Hiding risk warnings", "Changing signed forms"], "answerIndex": 0, "explanation": "Correct: Customer suitability and compliance.", "passage": "", "sourcePage": 12}, {"id": "KBL-03-Q70", "number": 70, "section": "sales", "stem": "A customer asks whether minimum balance charges apply. What is best?", "options": ["Hide exceptions", "Ask for a password first", "Explain the relevant account conditions accurately", "Say all accounts are free", "Invent a new charge"], "answerIndex": 2, "explanation": "Correct: Explain the relevant account conditions accurately.", "passage": "", "sourcePage": 12}, {"id": "KBL-03-Q71", "number": 71, "section": "sales", "stem": "Case 3.7: You discover a marketing leaflet has an outdated rate. What should you do?", "options": ["Use updated approved information and report the outdated material", "Continue distributing it knowingly", "Conceal the issue", "Promise the old rate", "Change the date by hand without approval"], "answerIndex": 0, "explanation": "Correct: Use updated approved information and report the outdated material.", "passage": "", "sourcePage": 12}, {"id": "KBL-03-Q72", "number": 72, "section": "sales", "stem": "An employee suggests using an informal payment link to collect fees. What is best?", "options": ["Suppress receipts", "Keep collections off the record", "Use only approved bank payment channels", "Share the login to the payment system", "Accept payments to a personal wallet"], "answerIndex": 2, "explanation": "Correct: Use only approved bank payment channels.", "passage": "", "sourcePage": 12}, {"id": "KBL-03-Q73", "number": 73, "section": "sales", "stem": "A customer requests a private conversation about debt difficulties. What is best?", "options": ["Discuss the debt loudly in a queue", "Threaten the customer", "Arrange a discreet discussion and explain permitted assistance options", "Promise automatic loan cancellation", "Reveal details to strangers"], "answerIndex": 2, "explanation": "Correct: Arrange a discreet discussion and explain permitted assistance options.", "passage": "", "sourcePage": 12}, {"id": "KBL-03-Q74", "number": 74, "section": "sales", "stem": "Case 3.10: A customer has difficulty reading a product disclosure. What should you do?", "options": ["Conceal charges", "Read only the advertised benefits", "Explain the key terms in plain language and allow questions", "Ask them to sign unread", "Suggest they trust the salesperson blindly"], "answerIndex": 2, "explanation": "Correct: Explain the key terms in plain language and allow questions.", "passage": "", "sourcePage": 12}, {"id": "KBL-03-Q75", "number": 75, "section": "sales", "stem": "The advertised offer does not fit a customer's needs. What is ethical?", "options": ["Offer appropriate alternatives and explain why", "Misrepresent the offer", "Pressure the customer to sign", "Apply in another person's name", "Conceal charges"], "answerIndex": 0, "explanation": "Correct: Offer appropriate alternatives and explain why.", "passage": "", "sourcePage": 12}]}, {"id": "KBL-04", "title": "Karnataka Bank CSA Mock 04", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_04.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-04-Q1", "number": 1, "section": "verbal", "stem": "What made the savings plan convenient?", "options": ["Deposits only once a year", "No account records", "Borrowing without documents", "Small regular deposits", "Mandatory large deposits"], "answerIndex": 3, "explanation": "Supported directly by the reading passage.", "passage": "An agricultural cooperative began offering members a monthly savings plan. Members could make small deposits rather than waiting to save a large amount. The plan also provided simple statements showing the deposits made during the year. Participation increased after the cooperative held meetings where members could ask questions in their preferred language.", "sourcePage": 2}, {"id": "KBL-04-Q2", "number": 2, "section": "verbal", "stem": "What information did the statements show?", "options": ["Deposits made during the year", "Weather forecasts", "School timetables", "Market closing times", "Bus routes"], "answerIndex": 0, "explanation": "Supported directly by the reading passage.", "passage": "An agricultural cooperative began offering members a monthly savings plan. Members could make small deposits rather than waiting to save a large amount. The plan also provided simple statements showing the deposits made during the year. Participation increased after the cooperative held meetings where members could ask questions in their preferred language.", "sourcePage": 2}, {"id": "KBL-04-Q3", "number": 3, "section": "verbal", "stem": "Why did participation increase?", "options": ["No explanation was provided", "Banking hours were eliminated", "Every member received a loan", "Members could ask questions in their preferred language", "All payments became cash-only"], "answerIndex": 3, "explanation": "Supported directly by the reading passage.", "passage": "An agricultural cooperative began offering members a monthly savings plan. Members could make small deposits rather than waiting to save a large amount. The plan also provided simple statements showing the deposits made during the year. Participation increased after the cooperative held meetings where members could ask questions in their preferred language.", "sourcePage": 2}, {"id": "KBL-04-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"brief\".", "options": ["complex", "remote", "short", "ancient", "lengthy"], "answerIndex": 2, "explanation": "\"brief\" is closest in meaning to \"short\".", "passage": "", "sourcePage": 2}, {"id": "KBL-04-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"assist\".", "options": ["avoid", "refuse", "doubt", "help", "delay"], "answerIndex": 3, "explanation": "\"assist\" is closest in meaning to \"help\".", "passage": "", "sourcePage": 2}, {"id": "KBL-04-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"flexible\".", "options": ["adaptable", "adjustable", "easy", "rigid", "movable"], "answerIndex": 3, "explanation": "The opposite of \"flexible\" is \"rigid\".", "passage": "", "sourcePage": 2}, {"id": "KBL-04-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"frequent\".", "options": ["daily", "regular", "repeated", "common", "rare"], "answerIndex": 4, "explanation": "The opposite of \"frequent\" is \"rare\".", "passage": "", "sourcePage": 3}, {"id": "KBL-04-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: I am looking forward to ___ from you.", "options": ["heard", "hear", "have hear", "hearing", "be hear"], "answerIndex": 3, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-04-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: The customer arrived ___ time for the appointment.", "options": ["in", "on", "by", "of", "at"], "answerIndex": 1, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-04-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: The report was prepared ___ the assistant.", "options": ["at", "to", "for", "by", "from"], "answerIndex": 3, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-04-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"She is working here since 2020.\"", "options": ["She has been working here since 2020.", "She work here since 2020.", "She have been working here since 2020.", "She was been working here since 2020.", "She worked here since 2020 and still."], "answerIndex": 0, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-04-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The clerk verified the documents.\"", "options": ["The clerk was verified by the documents.", "The documents verified the clerk.", "The documents is verified by the clerk.", "The documents were verified by the clerk.", "The documents are verifying the clerk."], "answerIndex": 3, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-04-Q13", "number": 13, "section": "quant", "stem": "Find 30% of 720.", "options": ["216", "212", "220", "208", "204"], "answerIndex": 0, "explanation": "30/100 x 720 = 216.", "passage": "", "sourcePage": 3}, {"id": "KBL-04-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 3:7. If there are 110 students, how many girls are there?", "options": ["66", "55", "77", "44", "88"], "answerIndex": 2, "explanation": "One part = 110/(3+7) = 11; girls = 7 x 11.", "passage": "", "sourcePage": 4}, {"id": "KBL-04-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 1200 and sells it at 10% profit. Find the selling price (Rs).", "options": ["1272", "1248", "1344", "1296", "1320"], "answerIndex": 4, "explanation": "SP = 1200 x (1 + 10/100) = Rs 1320.", "passage": "", "sourcePage": 4}, {"id": "KBL-04-Q16", "number": 16, "section": "quant", "stem": "Find the average of 51, 55, 59, 63, 67.", "options": ["50", "56", "62", "53", "59"], "answerIndex": 4, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-04-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 17000 at 12% p.a. for 3 years.", "options": ["5610", "5780", "6290", "6120", "5950"], "answerIndex": 3, "explanation": "SI = 17000 x 12 x 3/100 = Rs 6120.", "passage": "", "sourcePage": 4}, {"id": "KBL-04-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 30000 at 20% per annum for 2 years, compounded annually.", "options": ["12300", "12600", "13500", "13200", "12900"], "answerIndex": 3, "explanation": "CI = 30000 x [(1+20/100)^2 -1] = Rs 13200.", "passage": "", "sourcePage": 4}, {"id": "KBL-04-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 8 days and B in 24 days. Working together, in how many days will they finish?", "options": ["3", "7", "6", "5", "4"], "answerIndex": 2, "explanation": "Combined time = (8 x 24)/(8+24) = 6 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-04-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 54 km/h for 3 hours. Find the distance travelled (km).", "options": ["135", "162", "81", "189", "108"], "answerIndex": 1, "explanation": "Distance = speed x time = 54 x 3 = 162 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-04-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 6, 16, 26, 36, ?", "options": ["16", "46", "26", "36", "56"], "answerIndex": 1, "explanation": "Each step adds 10.", "passage": "", "sourcePage": 5}, {"id": "KBL-04-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 2400 is sold at 30% discount. Find the selling price (Rs).", "options": ["1440", "1680", "1560", "1320", "1800"], "answerIndex": 1, "explanation": "SP = 2400 x (100-30)/100 = Rs 1680.", "passage": "", "sourcePage": 5}, {"id": "KBL-04-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 240 accounts on Monday and 90 on Tuesday. Branch B opened 190 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["520", "490", "530", "510", "500"], "answerIndex": 0, "explanation": "Total = 240 + 90 + 190 = 520.", "passage": "", "sourcePage": 5}, {"id": "KBL-04-Q24", "number": 24, "section": "quant", "stem": "Ravi is 10 years older than Meera. Their present ages add up to 58 years. What is Ravi's age?", "options": ["28", "34", "36", "30", "32"], "answerIndex": 1, "explanation": "Older age = (sum + difference)/2 = (58+10)/2 = 34.", "passage": "", "sourcePage": 5}, {"id": "KBL-04-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 8 and 24 hours; pipe C empties it in 12 hours. If all are opened together, when will the tank fill?", "options": ["6", "12", "10", "8", "14"], "answerIndex": 1, "explanation": "Net filling rate = 1/8 + 1/24 - 1/12 = 1/12 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-04-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 50 L and 5 L respectively. What is the simplified milk:water ratio?", "options": ["1:10", "12:1", "10:1", "10:2", "11:1"], "answerIndex": 2, "explanation": "Divide both quantities by HCF = 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-04-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 600. Its price rises by 10% and then falls by 20%. Find its final price (Rs).", "options": ["438", "528", "558", "498", "468"], "answerIndex": 1, "explanation": "Final price = 600 x 110/100 x 80/100 = 528.", "passage": "", "sourcePage": 5}, {"id": "KBL-04-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 2 place(s) forward in the alphabet. How is RATE coded?", "options": ["WFYJ", "VEXI", "XGZK", "TCVG", "RATE"], "answerIndex": 3, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-04-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 38 people, A is 29th from the front. What is A's rank from the back?", "options": ["9", "11", "8", "7", "10"], "answerIndex": 4, "explanation": "Back rank = total - front rank +1 = 38-29+1 = 10.", "passage": "", "sourcePage": 6}, {"id": "KBL-04-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 4 km east, then 8 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["80", "76", "72", "68", "84"], "answerIndex": 0, "explanation": "Pythagoras: distance squared = 4^2 + 8^2 = 80.", "passage": "", "sourcePage": 6}, {"id": "KBL-04-Q31", "number": 31, "section": "reasoning", "stem": "A person faces North and turns 90 degrees to the left. Which direction does the person now face?", "options": ["Cannot be determined", "North", "South", "West", "East"], "answerIndex": 3, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-04-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All roses are flowers. Some flowers are plants. Which conclusion definitely follows?", "options": ["No roses are flowers", "All plants are roses", "All flowers are roses", "All plants are flowers", "Some flowers are roses"], "answerIndex": 4, "explanation": "All roses are flowers implies some flowers are roses in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-04-Q33", "number": 33, "section": "reasoning", "stem": "Given D > N = E > J, which relation definitely holds?", "options": ["D = J", "J > D", "E = J", "D > J", "N < J"], "answerIndex": 3, "explanation": "Chain: D > N = E > J, so D > J.", "passage": "", "sourcePage": 6}, {"id": "KBL-04-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: D, F, A, H, K. Who sits immediately to the right of H?", "options": ["H", "F", "A", "K", "D"], "answerIndex": 3, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-04-Q35", "number": 35, "section": "reasoning", "stem": "Tara is the mother of Leena. Neha is the sister of Leena. How is Tara related to Neha?", "options": ["Grandmother", "Mother", "Sister", "Daughter", "Aunt"], "answerIndex": 1, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-04-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: X > S > R > P > U. Who is immediately heavier than S?", "options": ["S", "R", "P", "X", "U"], "answerIndex": 3, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-04-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 23, 69, 207, 621, ?", "options": ["1794", "1656", "1725", "1932", "1863"], "answerIndex": 4, "explanation": "Every term is multiplied by 3.", "passage": "", "sourcePage": 7}, {"id": "KBL-04-Q38", "number": 38, "section": "reasoning", "stem": "If today is Tuesday, what day of the week will it be after 22 days?", "options": ["Saturday", "Wednesday", "Tuesday", "Sunday", "Thursday"], "answerIndex": 1, "explanation": "Advance 1 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-04-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are A, H, C, B, K. Who occupies floor 2?", "options": ["B", "K", "A", "C", "H"], "answerIndex": 4, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-04-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in BANKING?", "options": ["BANKING", "ANKINGB", "GNIKNAB", "ABGIKNN", "GBANKIN"], "answerIndex": 2, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-04-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 2?", "options": ["8", "10", "15", "6", "4"], "answerIndex": 2, "explanation": "15 leaves a remainder when divided by 2.", "passage": "", "sourcePage": 8}, {"id": "KBL-04-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 6 km east, then 2 km west. Where is the final position relative to the starting point?", "options": ["8 km east", "8 km west", "4 km east", "6 km north", "4 km west"], "answerIndex": 2, "explanation": "Net eastward movement = 6-2 = 4 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-04-Q43", "number": 43, "section": "gk", "stem": "What is interest on a deposit?", "options": ["Branch rent", "An ATM access code", "The customer identity number", "A penalty on every cash withdrawal", "Amount paid by the bank under the deposit terms"], "answerIndex": 4, "explanation": "Correct: Amount paid by the bank under the deposit terms.", "passage": "", "sourcePage": 8}, {"id": "KBL-04-Q44", "number": 44, "section": "gk", "stem": "What does ATM stand for?", "options": ["Automatic Transfer Money", "Account Tracking Module", "Automated Teller Machine", "Automated Tax Machine", "Approved Transaction Method"], "answerIndex": 2, "explanation": "Correct: Automated Teller Machine.", "passage": "", "sourcePage": 8}, {"id": "KBL-04-Q45", "number": 45, "section": "gk", "stem": "What is the full form of UPI?", "options": ["Universal Payment Insurance", "Unified Payments Interface", "United Processing Index", "User Payment Institution", "Unified Postal Interface"], "answerIndex": 1, "explanation": "Correct: Unified Payments Interface.", "passage": "", "sourcePage": 8}, {"id": "KBL-04-Q46", "number": 46, "section": "gk", "stem": "A bank balance sheet shows assets, liabilities and what?", "options": ["Election dates", "Sales slogans", "Daily weather", "Equity / capital", "Train schedules"], "answerIndex": 3, "explanation": "Correct: Equity / capital.", "passage": "", "sourcePage": 8}, {"id": "KBL-04-Q47", "number": 47, "section": "gk", "stem": "Which is a common feature of a current account?", "options": ["Mandatory fixed term", "No payment capability", "Designed for frequent business transactions", "Only quarterly deposits", "Only for children"], "answerIndex": 2, "explanation": "Correct: Designed for frequent business transactions.", "passage": "", "sourcePage": 8}, {"id": "KBL-04-Q48", "number": 48, "section": "gk", "stem": "What is a direct debit mandate?", "options": ["A new cheque number", "Permission for eligible automated debits", "A credit score report", "Unlimited permission to share passwords", "A bank holiday notice"], "answerIndex": 1, "explanation": "Correct: Permission for eligible automated debits.", "passage": "", "sourcePage": 9}, {"id": "KBL-04-Q49", "number": 49, "section": "gk", "stem": "What is financial inclusion?", "options": ["Stopping digital payments", "Replacing loans with cash only", "Eliminating savings accounts", "Expanding access to useful affordable financial services", "Restricting banking to high incomes"], "answerIndex": 3, "explanation": "Correct: Expanding access to useful affordable financial services.", "passage": "", "sourcePage": 9}, {"id": "KBL-04-Q50", "number": 50, "section": "gk", "stem": "What happens when a customer transfers money from their own account to another account?", "options": ["No ledger changes", "Funds are debited from sender and credited to recipient", "Both accounts are always credited", "Both accounts are always debited", "All transfers become loans"], "answerIndex": 1, "explanation": "Correct: Funds are debited from sender and credited to recipient.", "passage": "", "sourcePage": 9}, {"id": "KBL-04-Q51", "number": 51, "section": "gk", "stem": "What does RTGS stand for?", "options": ["Regional Trade Gross Service", "Real Transfer Government System", "Rapid Transaction General Service", "Real Time Government Savings", "Real Time Gross Settlement"], "answerIndex": 4, "explanation": "Correct: Real Time Gross Settlement.", "passage": "", "sourcePage": 9}, {"id": "KBL-04-Q52", "number": 52, "section": "gk", "stem": "What is a nominee in banking?", "options": ["The loan guarantor in all cases", "The bank cashier", "The branch security guard", "The account auditor", "A person designated to receive proceeds as per applicable rules"], "answerIndex": 4, "explanation": "Correct: A person designated to receive proceeds as per applicable rules.", "passage": "", "sourcePage": 9}, {"id": "KBL-04-Q53", "number": 53, "section": "gk", "stem": "Which institution mainly supports agriculture and rural development financing?", "options": ["ECI", "NABARD", "IRDAI", "SEBI", "ISRO"], "answerIndex": 1, "explanation": "Correct: NABARD.", "passage": "", "sourcePage": 9}, {"id": "KBL-04-Q54", "number": 54, "section": "computer", "stem": "Which is safer for online banking?", "options": ["Saving PIN in public notes", "Disabling all security checks", "Following an unknown short link", "Using the official site or app and verifying its address", "Sharing OTP in chat"], "answerIndex": 3, "explanation": "Correct: Using the official site or app and verifying its address.", "passage": "", "sourcePage": 9}, {"id": "KBL-04-Q55", "number": 55, "section": "computer", "stem": "Which shortcut commonly searches within a document?", "options": ["Ctrl+R", "Ctrl+B", "Ctrl+F", "Ctrl+Q", "Ctrl+W"], "answerIndex": 2, "explanation": "Correct: Ctrl+F.", "passage": "", "sourcePage": 10}, {"id": "KBL-04-Q56", "number": 56, "section": "computer", "stem": "In a spreadsheet, which symbol usually begins a formula?", "options": ["@", "#", "!", "&", "="], "answerIndex": 4, "explanation": "Correct: =.", "passage": "", "sourcePage": 10}, {"id": "KBL-04-Q57", "number": 57, "section": "computer", "stem": "What is phishing?", "options": ["Saving a spreadsheet", "Encrypting a hard drive", "Fraudulent attempt to steal information through deception", "Replacing a keyboard", "Installing a printer"], "answerIndex": 2, "explanation": "Correct: Fraudulent attempt to steal information through deception.", "passage": "", "sourcePage": 10}, {"id": "KBL-04-Q58", "number": 58, "section": "computer", "stem": "Which application is primarily used for spreadsheets?", "options": ["Microsoft Paint", "Calculator", "Media Player", "Microsoft Excel", "Notepad"], "answerIndex": 3, "explanation": "Correct: Microsoft Excel.", "passage": "", "sourcePage": 10}, {"id": "KBL-04-Q59", "number": 59, "section": "computer", "stem": "What is cloud storage?", "options": ["A physical bank locker", "A type of printer ink", "Data stored on remote servers accessible via a network", "An offline-only keyboard", "Only a local paper filing cabinet"], "answerIndex": 2, "explanation": "Correct: Data stored on remote servers accessible via a network.", "passage": "", "sourcePage": 10}, {"id": "KBL-04-Q60", "number": 60, "section": "computer", "stem": "What is a spreadsheet cell?", "options": ["An email address", "Intersection of row and column", "A network password", "A printer cartridge", "A cloud server"], "answerIndex": 1, "explanation": "Correct: Intersection of row and column.", "passage": "", "sourcePage": 10}, {"id": "KBL-04-Q61", "number": 61, "section": "computer", "stem": "What is a hyperlink?", "options": ["A mouse cable", "An antivirus alert", "Clickable reference to another resource", "A printer driver", "A storage disk"], "answerIndex": 2, "explanation": "Correct: Clickable reference to another resource.", "passage": "", "sourcePage": 10}, {"id": "KBL-04-Q62", "number": 62, "section": "computer", "stem": "What does IP address identify on a network?", "options": ["A printer toner size", "The amount of RAM", "A fixed deposit maturity date", "The user's Aadhaar details", "Network interface location for communication"], "answerIndex": 4, "explanation": "Correct: Network interface location for communication.", "passage": "", "sourcePage": 11}, {"id": "KBL-04-Q63", "number": 63, "section": "computer", "stem": "Which shortcut commonly selects all text or items?", "options": ["Ctrl+S", "Ctrl+P", "Ctrl+D", "Ctrl+L", "Ctrl+A"], "answerIndex": 4, "explanation": "Correct: Ctrl+A.", "passage": "", "sourcePage": 11}, {"id": "KBL-04-Q64", "number": 64, "section": "computer", "stem": "Which tool is normally used to create presentations?", "options": ["Microsoft PowerPoint", "Windows Explorer", "Calculator", "Notepad", "File compression utility"], "answerIndex": 0, "explanation": "Correct: Microsoft PowerPoint.", "passage": "", "sourcePage": 11}, {"id": "KBL-04-Q65", "number": 65, "section": "sales", "stem": "Case 4.1: A customer has difficulty reading a product disclosure. What should you do?", "options": ["Ask them to sign unread", "Conceal charges", "Read only the advertised benefits", "Suggest they trust the salesperson blindly", "Explain the key terms in plain language and allow questions"], "answerIndex": 4, "explanation": "Correct: Explain the key terms in plain language and allow questions.", "passage": "", "sourcePage": 11}, {"id": "KBL-04-Q66", "number": 66, "section": "sales", "stem": "The advertised offer does not fit a customer's needs. What is ethical?", "options": ["Apply in another person's name", "Misrepresent the offer", "Conceal charges", "Pressure the customer to sign", "Offer appropriate alternatives and explain why"], "answerIndex": 4, "explanation": "Correct: Offer appropriate alternatives and explain why.", "passage": "", "sourcePage": 11}, {"id": "KBL-04-Q67", "number": 67, "section": "sales", "stem": "A customer struggles with a form in English. What should you do?", "options": ["Explain the form clearly in a language you can appropriately support", "Ask for passwords", "Refuse to explain", "Skip essential disclosures", "Fill in details without consent"], "answerIndex": 0, "explanation": "Correct: Explain the form clearly in a language you can appropriately support.", "passage": "", "sourcePage": 11}, {"id": "KBL-04-Q68", "number": 68, "section": "sales", "stem": "Case 4.4: A customer says a cheque was deposited but not credited. What do you do?", "options": ["Verify the deposit and explain clearing and complaint steps", "Share someone else's cheque image", "Discard the deposit receipt", "Ignore the customer", "Promise immediate settlement regardless of status"], "answerIndex": 0, "explanation": "Correct: Verify the deposit and explain clearing and complaint steps.", "passage": "", "sourcePage": 11}, {"id": "KBL-04-Q69", "number": 69, "section": "sales", "stem": "A customer reports an ATM cash-withdrawal dispute. What is best?", "options": ["Immediately reimburse from personal cash", "Request the card PIN", "Close the account without consent", "Ignore transaction evidence", "Capture details and initiate the official dispute process"], "answerIndex": 4, "explanation": "Correct: Capture details and initiate the official dispute process.", "passage": "", "sourcePage": 12}, {"id": "KBL-04-Q70", "number": 70, "section": "sales", "stem": "A client asks to compare account options. What is good practice?", "options": ["Guarantee every account has the same terms", "Show only the promoted plan", "Hide a cheaper suitable option", "Compare costs and benefits against the customer's needs", "Make up competitor charges"], "answerIndex": 3, "explanation": "Correct: Compare costs and benefits against the customer's needs.", "passage": "", "sourcePage": 12}, {"id": "KBL-04-Q71", "number": 71, "section": "sales", "stem": "Case 4.7: A customer asks about an account nomination. What should you do?", "options": ["Hide the form", "Insist the CSA must be nominee", "Explain the nomination facility and approved procedure", "Choose a nominee without consent", "Promise legal ownership rules are identical in all cases"], "answerIndex": 2, "explanation": "Correct: Explain the nomination facility and approved procedure.", "passage": "", "sourcePage": 12}, {"id": "KBL-04-Q72", "number": 72, "section": "sales", "stem": "A colleague suggests skipping KYC to meet a target. What should you do?", "options": ["Use someone else's identity documents", "Follow KYC procedures and escalate pressure if necessary", "Alter the forms", "Skip steps to close the sale", "Ignore suspicious activity"], "answerIndex": 1, "explanation": "Correct: Follow KYC procedures and escalate pressure if necessary.", "passage": "", "sourcePage": 12}, {"id": "KBL-04-Q73", "number": 73, "section": "sales", "stem": "A customer reports a phishing call. The best guidance is to:", "options": ["Share OTP with the caller", "Install an unknown app", "Avoid sharing credentials and contact the bank using official channels", "Click all links in the message", "Send a photo of their password"], "answerIndex": 2, "explanation": "Correct: Avoid sharing credentials and contact the bank using official channels.", "passage": "", "sourcePage": 12}, {"id": "KBL-04-Q74", "number": 74, "section": "sales", "stem": "Case 4.10: A client asks whether an investment is risk free. What should the CSA do?", "options": ["Guarantee all investments", "Claim all returns are fixed by law", "Recommend borrowing to invest without review", "Conceal product documents", "Provide accurate risk information and avoid absolute guarantees"], "answerIndex": 4, "explanation": "Correct: Provide accurate risk information and avoid absolute guarantees.", "passage": "", "sourcePage": 12}, {"id": "KBL-04-Q75", "number": 75, "section": "sales", "stem": "During cash handling you notice a mismatch. What is the correct step?", "options": ["Alter figures to match", "Reconcile carefully and report under procedure", "Use a personal payment to avoid a record", "Accuse the next customer", "Hide the shortage"], "answerIndex": 1, "explanation": "Correct: Reconcile carefully and report under procedure.", "passage": "", "sourcePage": 12}]}, {"id": "KBL-05", "title": "Karnataka Bank CSA Mock 05", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_05.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-05-Q1", "number": 1, "section": "verbal", "stem": "What did the officer first do?", "options": ["Delete the transaction record", "Listen and record transaction details", "Blame the customer", "Ignore the report", "Promise an instant refund"], "answerIndex": 1, "explanation": "Supported directly by the reading passage.", "passage": "During a busy morning, a customer reported a transfer to the wrong beneficiary. The service officer listened carefully, noted the transaction reference number, and explained the complaint process. The officer did not promise that the money would certainly be returned. Instead, the officer gave the customer a complaint acknowledgement and the expected process for receiving updates.", "sourcePage": 2}, {"id": "KBL-05-Q2", "number": 2, "section": "verbal", "stem": "Which document was given to the customer?", "options": ["A new cheque book", "A new identity card", "A loan sanction letter", "A tax certificate", "Complaint acknowledgement"], "answerIndex": 4, "explanation": "Supported directly by the reading passage.", "passage": "During a busy morning, a customer reported a transfer to the wrong beneficiary. The service officer listened carefully, noted the transaction reference number, and explained the complaint process. The officer did not promise that the money would certainly be returned. Instead, the officer gave the customer a complaint acknowledgement and the expected process for receiving updates.", "sourcePage": 2}, {"id": "KBL-05-Q3", "number": 3, "section": "verbal", "stem": "Why did the officer avoid promising a refund?", "options": ["The bank never handles complaints", "All transfers are reversible instantly", "The officer forgot the amount", "The outcome could not be guaranteed", "The branch had no customers"], "answerIndex": 3, "explanation": "Supported directly by the reading passage.", "passage": "During a busy morning, a customer reported a transfer to the wrong beneficiary. The service officer listened carefully, noted the transaction reference number, and explained the complaint process. The officer did not promise that the money would certainly be returned. Instead, the officer gave the customer a complaint acknowledgement and the expected process for receiving updates.", "sourcePage": 2}, {"id": "KBL-05-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"prompt\".", "options": ["uncertain", "rare", "slow", "distant", "quick"], "answerIndex": 4, "explanation": "\"prompt\" is closest in meaning to \"quick\".", "passage": "", "sourcePage": 2}, {"id": "KBL-05-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"secure\".", "options": ["delayed", "fragile", "risky", "open", "safe"], "answerIndex": 4, "explanation": "\"secure\" is closest in meaning to \"safe\".", "passage": "", "sourcePage": 2}, {"id": "KBL-05-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"mandatory\".", "options": ["compulsory", "necessary", "binding", "optional", "required"], "answerIndex": 3, "explanation": "The opposite of \"mandatory\" is \"optional\".", "passage": "", "sourcePage": 2}, {"id": "KBL-05-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"accurate\".", "options": ["true", "exact", "incorrect", "careful", "precise"], "answerIndex": 2, "explanation": "The opposite of \"accurate\" is \"incorrect\".", "passage": "", "sourcePage": 3}, {"id": "KBL-05-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: The cashier is responsible ___ checking entries.", "options": ["to", "at", "in", "for", "with"], "answerIndex": 3, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-05-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: Hardly had the branch opened ___ customers began to queue.", "options": ["because", "than", "that", "then", "when"], "answerIndex": 4, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-05-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: The staff members ___ attending training today.", "options": ["are", "be", "was", "has", "is"], "answerIndex": 0, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-05-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"The information are confidential.\"", "options": ["The information were confidential always.", "The information have confidential.", "The information is confidential.", "The informations are confidential.", "The information be confidential."], "answerIndex": 2, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-05-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The manager approved the request.\"", "options": ["The request was approved by the manager.", "The request is approve by the manager.", "The request has approve the manager.", "The manager was approved by the request.", "The request approved the manager."], "answerIndex": 0, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-05-Q13", "number": 13, "section": "quant", "stem": "Find 40% of 240.", "options": ["66", "76", "96", "106", "86"], "answerIndex": 2, "explanation": "40/100 x 240 = 96.", "passage": "", "sourcePage": 3}, {"id": "KBL-05-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 4:7. If there are 154 students, how many girls are there?", "options": ["84", "70", "112", "56", "98"], "answerIndex": 4, "explanation": "One part = 154/(4+7) = 14; girls = 7 x 14.", "passage": "", "sourcePage": 4}, {"id": "KBL-05-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 600 and sells it at 15% profit. Find the selling price (Rs).", "options": ["702", "690", "654", "666", "678"], "answerIndex": 1, "explanation": "SP = 600 x (1 + 15/100) = Rs 690.", "passage": "", "sourcePage": 4}, {"id": "KBL-05-Q16", "number": 16, "section": "quant", "stem": "Find the average of 36, 40, 44, 48, 52.", "options": ["47", "38", "44", "41", "35"], "answerIndex": 2, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-05-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 11000 at 10% p.a. for 2 years.", "options": ["2310", "2200", "1870", "1980", "2090"], "answerIndex": 1, "explanation": "SI = 11000 x 10 x 2/100 = Rs 2200.", "passage": "", "sourcePage": 4}, {"id": "KBL-05-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 30000 at 20% per annum for 2 years, compounded annually.", "options": ["13500", "12900", "12600", "12300", "13200"], "answerIndex": 4, "explanation": "CI = 30000 x [(1+20/100)^2 -1] = Rs 13200.", "passage": "", "sourcePage": 4}, {"id": "KBL-05-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 10 days and B in 15 days. Working together, in how many days will they finish?", "options": ["6", "5", "7", "3", "4"], "answerIndex": 0, "explanation": "Combined time = (10 x 15)/(10+15) = 6 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-05-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 80 km/h for 4 hours. Find the distance travelled (km).", "options": ["200", "280", "320", "240", "360"], "answerIndex": 2, "explanation": "Distance = speed x time = 80 x 4 = 320 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-05-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 15, 20, 25, 30, ?", "options": ["40", "20", "30", "35", "25"], "answerIndex": 3, "explanation": "Each step adds 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-05-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 1000 is sold at 25% discount. Find the selling price (Rs).", "options": ["700", "800", "600", "750", "650"], "answerIndex": 3, "explanation": "SP = 1000 x (100-25)/100 = Rs 750.", "passage": "", "sourcePage": 5}, {"id": "KBL-05-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 90 accounts on Monday and 190 on Tuesday. Branch B opened 190 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["460", "470", "450", "480", "440"], "answerIndex": 1, "explanation": "Total = 90 + 190 + 190 = 470.", "passage": "", "sourcePage": 5}, {"id": "KBL-05-Q24", "number": 24, "section": "quant", "stem": "Ravi is 10 years older than Meera. Their present ages add up to 34 years. What is Ravi's age?", "options": ["22", "20", "16", "24", "18"], "answerIndex": 0, "explanation": "Older age = (sum + difference)/2 = (34+10)/2 = 22.", "passage": "", "sourcePage": 5}, {"id": "KBL-05-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 8 and 24 hours; pipe C empties it in 12 hours. If all are opened together, when will the tank fill?", "options": ["8", "10", "12", "6", "14"], "answerIndex": 2, "explanation": "Net filling rate = 1/8 + 1/24 - 1/12 = 1/12 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-05-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 50 L and 10 L respectively. What is the simplified milk:water ratio?", "options": ["5:1", "5:2", "7:1", "1:5", "6:1"], "answerIndex": 0, "explanation": "Divide both quantities by HCF = 10.", "passage": "", "sourcePage": 5}, {"id": "KBL-05-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 600. Its price rises by 10% and then falls by 20%. Find its final price (Rs).", "options": ["438", "558", "528", "468", "498"], "answerIndex": 2, "explanation": "Final price = 600 x 110/100 x 80/100 = 528.", "passage": "", "sourcePage": 5}, {"id": "KBL-05-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 2 place(s) forward in the alphabet. How is BANK coded?", "options": ["FERO", "GFSP", "BANK", "HGTQ", "DCPM"], "answerIndex": 4, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-05-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 79 people, A is 58th from the front. What is A's rank from the back?", "options": ["21", "23", "19", "20", "22"], "answerIndex": 4, "explanation": "Back rank = total - front rank +1 = 79-58+1 = 22.", "passage": "", "sourcePage": 6}, {"id": "KBL-05-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 2 km east, then 4 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["16", "24", "20", "8", "12"], "answerIndex": 2, "explanation": "Pythagoras: distance squared = 2^2 + 4^2 = 20.", "passage": "", "sourcePage": 6}, {"id": "KBL-05-Q31", "number": 31, "section": "reasoning", "stem": "A person faces North and turns 90 degrees to the left. Which direction does the person now face?", "options": ["West", "South", "North", "East", "Cannot be determined"], "answerIndex": 0, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-05-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All dogs are animals. Some animals are birds. Which conclusion definitely follows?", "options": ["All birds are animals", "No dogs are animals", "All birds are dogs", "Some animals are dogs", "All animals are dogs"], "answerIndex": 3, "explanation": "All dogs are animals implies some animals are dogs in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-05-Q33", "number": 33, "section": "reasoning", "stem": "Given H > D = M > G, which relation definitely holds?", "options": ["D < G", "H = G", "M = G", "G > H", "H > G"], "answerIndex": 4, "explanation": "Chain: H > D = M > G, so H > G.", "passage": "", "sourcePage": 6}, {"id": "KBL-05-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: H, K, B, A, D. Who sits immediately to the right of B?", "options": ["B", "D", "H", "K", "A"], "answerIndex": 4, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-05-Q35", "number": 35, "section": "reasoning", "stem": "Rina is the mother of Tara. Asha is the sister of Tara. How is Rina related to Asha?", "options": ["Grandmother", "Aunt", "Sister", "Mother", "Daughter"], "answerIndex": 3, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-05-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: U > W > R > V > P. Who is immediately heavier than R?", "options": ["R", "V", "U", "W", "P"], "answerIndex": 3, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-05-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 15, 30, 60, 120, ?", "options": ["270", "210", "150", "240", "180"], "answerIndex": 3, "explanation": "Every term is multiplied by 2.", "passage": "", "sourcePage": 7}, {"id": "KBL-05-Q38", "number": 38, "section": "reasoning", "stem": "If today is Sunday, what day of the week will it be after 15 days?", "options": ["Thursday", "Monday", "Saturday", "Wednesday", "Tuesday"], "answerIndex": 1, "explanation": "Advance 1 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-05-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are A, L, B, N, H. Who occupies floor 5?", "options": ["L", "A", "H", "B", "N"], "answerIndex": 2, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-05-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in DEPOSIT?", "options": ["TDEPOSI", "EPOSITD", "DEPOSIT", "DEIOPST", "TISOPED"], "answerIndex": 4, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-05-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 2?", "options": ["6", "15", "10", "4", "8"], "answerIndex": 1, "explanation": "15 leaves a remainder when divided by 2.", "passage": "", "sourcePage": 8}, {"id": "KBL-05-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 4 km east, then 5 km west. Where is the final position relative to the starting point?", "options": ["9 km west", "4 km north", "9 km east", "-1 km west", "-1 km east"], "answerIndex": 4, "explanation": "Net eastward movement = 4-5 = -1 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-05-Q43", "number": 43, "section": "gk", "stem": "What is a nominee in banking?", "options": ["A person designated to receive proceeds as per applicable rules", "The loan guarantor in all cases", "The branch security guard", "The account auditor", "The bank cashier"], "answerIndex": 0, "explanation": "Correct: A person designated to receive proceeds as per applicable rules.", "passage": "", "sourcePage": 8}, {"id": "KBL-05-Q44", "number": 44, "section": "gk", "stem": "Which institution mainly supports agriculture and rural development financing?", "options": ["NABARD", "ISRO", "ECI", "SEBI", "IRDAI"], "answerIndex": 0, "explanation": "Correct: NABARD.", "passage": "", "sourcePage": 8}, {"id": "KBL-05-Q45", "number": 45, "section": "gk", "stem": "Who issues regulations governing many Indian banking operations?", "options": ["Food Corporation of India", "Election Commission", "Reserve Bank of India", "Indian Railways", "University Grants Commission"], "answerIndex": 2, "explanation": "Correct: Reserve Bank of India.", "passage": "", "sourcePage": 8}, {"id": "KBL-05-Q46", "number": 46, "section": "gk", "stem": "What is a beneficiary in a fund transfer?", "options": ["ATM manufacturer", "Intended recipient of funds", "Person printing the receipt", "Branch architect", "Insurance surveyor"], "answerIndex": 1, "explanation": "Correct: Intended recipient of funds.", "passage": "", "sourcePage": 8}, {"id": "KBL-05-Q47", "number": 47, "section": "gk", "stem": "What is a fixed deposit maturity date?", "options": ["Last day of every financial quarter", "Date of account opening always", "Date when the agreed deposit tenure ends", "Bank nationalisation day", "ATM maintenance time"], "answerIndex": 2, "explanation": "Correct: Date when the agreed deposit tenure ends.", "passage": "", "sourcePage": 8}, {"id": "KBL-05-Q48", "number": 48, "section": "gk", "stem": "What is a bank audit mainly intended to examine?", "options": ["Branch wall colour", "Local cinema schedules", "Staff dress preferences", "Election rallies", "Records, controls and compliance"], "answerIndex": 4, "explanation": "Correct: Records, controls and compliance.", "passage": "", "sourcePage": 9}, {"id": "KBL-05-Q49", "number": 49, "section": "gk", "stem": "What is the full form of NEFT?", "options": ["New Electronic Funds Trade", "National Easy Finance Transaction", "National Exchange Fund Transfer", "Net Electronic Fiscal Transfer", "National Electronic Funds Transfer"], "answerIndex": 4, "explanation": "Correct: National Electronic Funds Transfer.", "passage": "", "sourcePage": 9}, {"id": "KBL-05-Q50", "number": 50, "section": "gk", "stem": "What is a debit card commonly linked to?", "options": ["Driving licence", "Electricity meter", "Property deed", "Bank account", "Insurance claim"], "answerIndex": 3, "explanation": "Correct: Bank account.", "passage": "", "sourcePage": 9}, {"id": "KBL-05-Q51", "number": 51, "section": "gk", "stem": "What is the full form of MICR?", "options": ["Magnetic Internal Credit Record", "Machine Integrated Cash Receipt", "Magnetic Ink Character Recognition", "Monthly Income Credit Rule", "Money Information Card Reader"], "answerIndex": 2, "explanation": "Correct: Magnetic Ink Character Recognition.", "passage": "", "sourcePage": 9}, {"id": "KBL-05-Q52", "number": 52, "section": "gk", "stem": "What is Aadhaar primarily used as in banking onboarding?", "options": ["An identity number used under applicable KYC rules", "A debit card PIN", "A guaranteed credit score", "A bank loan agreement", "A fixed-deposit certificate"], "answerIndex": 0, "explanation": "Correct: An identity number used under applicable KYC rules.", "passage": "", "sourcePage": 9}, {"id": "KBL-05-Q53", "number": 53, "section": "gk", "stem": "What is the main purpose of a bank passbook or statement?", "options": ["Set government budgets", "Guarantee unlimited cash", "Record transactions and balances", "Eliminate audits", "Replace PAN for every purpose"], "answerIndex": 2, "explanation": "Correct: Record transactions and balances.", "passage": "", "sourcePage": 9}, {"id": "KBL-05-Q54", "number": 54, "section": "computer", "stem": "Which tool is normally used to create presentations?", "options": ["File compression utility", "Notepad", "Calculator", "Windows Explorer", "Microsoft PowerPoint"], "answerIndex": 4, "explanation": "Correct: Microsoft PowerPoint.", "passage": "", "sourcePage": 9}, {"id": "KBL-05-Q55", "number": 55, "section": "computer", "stem": "Which shortcut pastes copied content?", "options": ["Ctrl+S", "Ctrl+Z", "Ctrl+C", "Ctrl+V", "Ctrl+F"], "answerIndex": 3, "explanation": "Correct: Ctrl+V.", "passage": "", "sourcePage": 10}, {"id": "KBL-05-Q56", "number": 56, "section": "computer", "stem": "Which protocol helps secure website traffic?", "options": ["HTTPS", "HTTP without encryption", "SMTP only", "POP3 only", "FTP only"], "answerIndex": 0, "explanation": "Correct: HTTPS.", "passage": "", "sourcePage": 10}, {"id": "KBL-05-Q57", "number": 57, "section": "computer", "stem": "What is the purpose of antivirus software?", "options": ["Make passwords public", "Create banknotes", "Detect and help block malicious software", "Replace all backups", "Increase loan interest"], "answerIndex": 2, "explanation": "Correct: Detect and help block malicious software.", "passage": "", "sourcePage": 10}, {"id": "KBL-05-Q58", "number": 58, "section": "computer", "stem": "Which device connects network segments and forwards packets based on network addresses?", "options": ["Speaker", "Projector", "Monitor", "Router", "Scanner"], "answerIndex": 3, "explanation": "Correct: Router.", "passage": "", "sourcePage": 10}, {"id": "KBL-05-Q59", "number": 59, "section": "computer", "stem": "What does OTP mean in digital authentication?", "options": ["Only Transfer Protocol", "One-Time Password", "Original Transfer Password", "Online Transaction Printout", "Open Token Port"], "answerIndex": 1, "explanation": "Correct: One-Time Password.", "passage": "", "sourcePage": 10}, {"id": "KBL-05-Q60", "number": 60, "section": "computer", "stem": "What is a screenshot?", "options": ["Network backup cable", "Computer restart", "Keyboard battery", "Microphone recording", "Image capture of screen content"], "answerIndex": 4, "explanation": "Correct: Image capture of screen content.", "passage": "", "sourcePage": 10}, {"id": "KBL-05-Q61", "number": 61, "section": "computer", "stem": "What does HTTP stand for?", "options": ["Hyper Token Time Process", "Host Text Transfer Print", "High Transfer Text Program", "HyperText Transfer Protocol", "Home Transaction Token Process"], "answerIndex": 3, "explanation": "Correct: HyperText Transfer Protocol.", "passage": "", "sourcePage": 10}, {"id": "KBL-05-Q62", "number": 62, "section": "computer", "stem": "What is encryption used for?", "options": ["Increasing screen resolution", "Deleting browser history always", "Protecting information by transforming it into coded form", "Replacing computer memory", "Printing reports"], "answerIndex": 2, "explanation": "Correct: Protecting information by transforming it into coded form.", "passage": "", "sourcePage": 11}, {"id": "KBL-05-Q63", "number": 63, "section": "computer", "stem": "Which shortcut commonly copies selected content in Windows?", "options": ["Ctrl+X", "Ctrl+V", "Alt+F4", "Ctrl+P", "Ctrl+C"], "answerIndex": 4, "explanation": "Correct: Ctrl+C.", "passage": "", "sourcePage": 11}, {"id": "KBL-05-Q64", "number": 64, "section": "computer", "stem": "What does URL stand for?", "options": ["Uniform Resource Locator", "Unified Record Ledger", "Universal Router Login", "Utility Resource Library", "User Reference Language"], "answerIndex": 0, "explanation": "Correct: Uniform Resource Locator.", "passage": "", "sourcePage": 11}, {"id": "KBL-05-Q65", "number": 65, "section": "sales", "stem": "Case 5.1: A client asks whether an investment is risk free. What should the CSA do?", "options": ["Conceal product documents", "Recommend borrowing to invest without review", "Provide accurate risk information and avoid absolute guarantees", "Claim all returns are fixed by law", "Guarantee all investments"], "answerIndex": 2, "explanation": "Correct: Provide accurate risk information and avoid absolute guarantees.", "passage": "", "sourcePage": 11}, {"id": "KBL-05-Q66", "number": 66, "section": "sales", "stem": "During cash handling you notice a mismatch. What is the correct step?", "options": ["Reconcile carefully and report under procedure", "Accuse the next customer", "Hide the shortage", "Alter figures to match", "Use a personal payment to avoid a record"], "answerIndex": 0, "explanation": "Correct: Reconcile carefully and report under procedure.", "passage": "", "sourcePage": 11}, {"id": "KBL-05-Q67", "number": 67, "section": "sales", "stem": "The bank changes a product fee. What should the CSA communicate?", "options": ["A personal discount not authorised", "Only old promotional claims", "The current published terms and effective conditions", "An arbitrary amount", "A claim the fee is impossible to change"], "answerIndex": 2, "explanation": "Correct: The current published terms and effective conditions.", "passage": "", "sourcePage": 11}, {"id": "KBL-05-Q68", "number": 68, "section": "sales", "stem": "Case 5.4: A customer with a disability requests a reasonable accommodation. What is best?", "options": ["Refuse all assistance", "Sell a higher-priced product instead", "Mock the request", "Require public disclosure of medical records", "Follow accessible service procedures and offer appropriate help"], "answerIndex": 4, "explanation": "Correct: Follow accessible service procedures and offer appropriate help.", "passage": "", "sourcePage": 11}, {"id": "KBL-05-Q69", "number": 69, "section": "sales", "stem": "A customer offers a personal gift in exchange for bypassing checks. What do you do?", "options": ["Accept the gift", "Decline and follow the bank's ethics policy", "Offer a private rate", "Skip controls", "Hide the exception"], "answerIndex": 1, "explanation": "Correct: Decline and follow the bank's ethics policy.", "passage": "", "sourcePage": 12}, {"id": "KBL-05-Q70", "number": 70, "section": "sales", "stem": "A customer declines insurance after the terms are explained. What should the CSA do?", "options": ["Keep pressuring until they agree", "Hide the rejection", "Respect the decision and document consent appropriately", "Add it without permission", "Claim it is legally mandatory when it is not"], "answerIndex": 2, "explanation": "Correct: Respect the decision and document consent appropriately.", "passage": "", "sourcePage": 12}, {"id": "KBL-05-Q71", "number": 71, "section": "sales", "stem": "Case 5.7: A customer asks about a recurring deposit. The best response is to:", "options": ["Omit penalties and conditions", "Explain deposit frequency, tenure, rates and premature withdrawal rules", "Tell them returns cannot vary by product", "Discuss only a sales slogan", "Open it with no instruction"], "answerIndex": 1, "explanation": "Correct: Explain deposit frequency, tenure, rates and premature withdrawal rules.", "passage": "", "sourcePage": 12}, {"id": "KBL-05-Q72", "number": 72, "section": "sales", "stem": "A customer with a fixed deposit asks about early withdrawal. What do you do?", "options": ["Promise there will never be a penalty", "Ignore the request", "Explain available premature closure rules and potential charges", "Hide the maturity date", "Change tenure without permission"], "answerIndex": 2, "explanation": "Correct: Explain available premature closure rules and potential charges.", "passage": "", "sourcePage": 12}, {"id": "KBL-05-Q73", "number": 73, "section": "sales", "stem": "Someone asks for another customer's account balance. What should you do?", "options": ["Email a screenshot", "Read out the account number", "Send login credentials", "Protect confidentiality and decline unauthorised disclosure", "Share the balance verbally"], "answerIndex": 3, "explanation": "Correct: Protect confidentiality and decline unauthorised disclosure.", "passage": "", "sourcePage": 12}, {"id": "KBL-05-Q74", "number": 74, "section": "sales", "stem": "Case 5.10: A customer wants to activate digital banking. What should happen first?", "options": ["Activate someone else's account", "Send credentials through unsecured chat", "Ask them to tell you their PIN", "Use a fake website", "Explain features and verify identity using approved channels"], "answerIndex": 4, "explanation": "Correct: Explain features and verify identity using approved channels.", "passage": "", "sourcePage": 12}, {"id": "KBL-05-Q75", "number": 75, "section": "sales", "stem": "A potential customer refuses to share optional marketing data. What should you do?", "options": ["Respect consent and collect only data lawfully required", "Deny all services automatically", "Threaten extra charges", "Publish personal data", "Guess answers on the form"], "answerIndex": 0, "explanation": "Correct: Respect consent and collect only data lawfully required.", "passage": "", "sourcePage": 12}]}, {"id": "KBL-06", "title": "Karnataka Bank CSA Mock 06", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_06.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-06-Q1", "number": 1, "section": "verbal", "stem": "What was the officer's approach?", "options": ["Skip the charges", "Recommend only the most expensive product", "Hide account limitations", "Apply without consent", "Explain features and let the student choose"], "answerIndex": 4, "explanation": "Supported directly by the reading passage.", "passage": "A student compared two savings products offered by a bank. One account permitted frequent withdrawals, while the other was intended for money that would remain untouched for a fixed period. The bank officer explained the conditions, charges, and limitations of each product before asking the student to choose. The student selected the option that matched a short-term emergency fund.", "sourcePage": 2}, {"id": "KBL-06-Q2", "number": 2, "section": "verbal", "stem": "Which feature mattered for an emergency fund?", "options": ["Unclear withdrawal conditions", "No written terms", "Access to money when needed", "Mandatory borrowing", "Highest possible lock-in"], "answerIndex": 2, "explanation": "Supported directly by the reading passage.", "passage": "A student compared two savings products offered by a bank. One account permitted frequent withdrawals, while the other was intended for money that would remain untouched for a fixed period. The bank officer explained the conditions, charges, and limitations of each product before asking the student to choose. The student selected the option that matched a short-term emergency fund.", "sourcePage": 2}, {"id": "KBL-06-Q3", "number": 3, "section": "verbal", "stem": "What did the bank officer explain?", "options": ["Employee birthdays", "Only advertisements", "Competitors' passwords", "Unrelated travel plans", "Conditions, charges and limitations"], "answerIndex": 4, "explanation": "Supported directly by the reading passage.", "passage": "A student compared two savings products offered by a bank. One account permitted frequent withdrawals, while the other was intended for money that would remain untouched for a fixed period. The bank officer explained the conditions, charges, and limitations of each product before asking the student to choose. The student selected the option that matched a short-term emergency fund.", "sourcePage": 2}, {"id": "KBL-06-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"genuine\".", "options": ["temporary", "minor", "authentic", "false", "risky"], "answerIndex": 2, "explanation": "\"genuine\" is closest in meaning to \"authentic\".", "passage": "", "sourcePage": 2}, {"id": "KBL-06-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"adequate\".", "options": ["late", "unrelated", "rare", "inadequate", "sufficient"], "answerIndex": 4, "explanation": "\"adequate\" is closest in meaning to \"sufficient\".", "passage": "", "sourcePage": 2}, {"id": "KBL-06-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"credit\".", "options": ["lend", "deposit", "debit", "loan", "borrow"], "answerIndex": 2, "explanation": "The opposite of \"credit\" is \"debit\".", "passage": "", "sourcePage": 2}, {"id": "KBL-06-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"maximum\".", "options": ["highest", "greatest", "peak", "minimum", "largest"], "answerIndex": 3, "explanation": "The opposite of \"maximum\" is \"minimum\".", "passage": "", "sourcePage": 3}, {"id": "KBL-06-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: The officer asked whether the address ___ correct.", "options": ["were", "are", "be", "was", "have"], "answerIndex": 3, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-06-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: The report was prepared ___ the assistant.", "options": ["from", "by", "at", "for", "to"], "answerIndex": 1, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-06-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: He is senior ___ me in the department.", "options": ["than", "from", "to", "for", "as"], "answerIndex": 2, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-06-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"He do not know the branch timings.\"", "options": ["He does not know the branch timings.", "He do not knows the branch timings.", "He not knows the branch timings.", "He doing not know the branch timings.", "He does knows the branch timings."], "answerIndex": 0, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-06-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The team completed the audit.\"", "options": ["The audit were completed by the team.", "The audit completed the team.", "The audit is completing by the team.", "The audit was completed by the team.", "The team was completed by the audit."], "answerIndex": 3, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-06-Q13", "number": 13, "section": "quant", "stem": "Find 10% of 400.", "options": ["40", "50", "10", "20", "30"], "answerIndex": 0, "explanation": "10/100 x 400 = 40.", "passage": "", "sourcePage": 3}, {"id": "KBL-06-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 5:6. If there are 99 students, how many girls are there?", "options": ["54", "63", "36", "27", "45"], "answerIndex": 0, "explanation": "One part = 99/(5+6) = 9; girls = 6 x 9.", "passage": "", "sourcePage": 4}, {"id": "KBL-06-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 700 and sells it at 20% profit. Find the selling price (Rs).", "options": ["840", "854", "798", "826", "812"], "answerIndex": 0, "explanation": "SP = 700 x (1 + 20/100) = Rs 840.", "passage": "", "sourcePage": 4}, {"id": "KBL-06-Q16", "number": 16, "section": "quant", "stem": "Find the average of 21, 25, 29, 33, 37.", "options": ["32", "20", "29", "26", "23"], "answerIndex": 2, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-06-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 10000 at 8% p.a. for 2 years.", "options": ["1600", "1400", "1500", "1700", "1300"], "answerIndex": 0, "explanation": "SI = 10000 x 8 x 2/100 = Rs 1600.", "passage": "", "sourcePage": 4}, {"id": "KBL-06-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 30000 at 10% per annum for 2 years, compounded annually.", "options": ["6000", "6600", "5700", "6300", "5400"], "answerIndex": 3, "explanation": "CI = 30000 x [(1+10/100)^2 -1] = Rs 6300.", "passage": "", "sourcePage": 4}, {"id": "KBL-06-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 8 days and B in 24 days. Working together, in how many days will they finish?", "options": ["3", "6", "5", "7", "4"], "answerIndex": 1, "explanation": "Combined time = (8 x 24)/(8+24) = 6 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-06-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 50 km/h for 4 hours. Find the distance travelled (km).", "options": ["200", "125", "175", "150", "225"], "answerIndex": 0, "explanation": "Distance = speed x time = 50 x 4 = 200 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-06-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 10, 15, 20, 25, ?", "options": ["25", "15", "20", "35", "30"], "answerIndex": 4, "explanation": "Each step adds 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-06-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 800 is sold at 30% discount. Find the selling price (Rs).", "options": ["480", "520", "560", "440", "600"], "answerIndex": 2, "explanation": "SP = 800 x (100-30)/100 = Rs 560.", "passage": "", "sourcePage": 5}, {"id": "KBL-06-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 220 accounts on Monday and 140 on Tuesday. Branch B opened 120 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["460", "490", "470", "480", "450"], "answerIndex": 3, "explanation": "Total = 220 + 140 + 120 = 480.", "passage": "", "sourcePage": 5}, {"id": "KBL-06-Q24", "number": 24, "section": "quant", "stem": "Ravi is 12 years older than Meera. Their present ages add up to 46 years. What is Ravi's age?", "options": ["31", "23", "27", "25", "29"], "answerIndex": 4, "explanation": "Older age = (sum + difference)/2 = (46+12)/2 = 29.", "passage": "", "sourcePage": 5}, {"id": "KBL-06-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 8 and 24 hours; pipe C empties it in 12 hours. If all are opened together, when will the tank fill?", "options": ["12", "6", "8", "14", "10"], "answerIndex": 0, "explanation": "Net filling rate = 1/8 + 1/24 - 1/12 = 1/12 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-06-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 40 L and 15 L respectively. What is the simplified milk:water ratio?", "options": ["10:3", "9:3", "3:8", "8:3", "8:4"], "answerIndex": 3, "explanation": "Divide both quantities by HCF = 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-06-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 800. Its price rises by 10% and then falls by 20%. Find its final price (Rs).", "options": ["704", "744", "664", "584", "624"], "answerIndex": 0, "explanation": "Final price = 800 x 110/100 x 80/100 = 704.", "passage": "", "sourcePage": 5}, {"id": "KBL-06-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 2 place(s) forward in the alphabet. How is SAVE coded?", "options": ["SAVE", "XFAJ", "YGBK", "WEZI", "UCXG"], "answerIndex": 4, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-06-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 76 people, A is 30th from the front. What is A's rank from the back?", "options": ["45", "48", "47", "46", "44"], "answerIndex": 2, "explanation": "Back rank = total - front rank +1 = 76-30+1 = 47.", "passage": "", "sourcePage": 6}, {"id": "KBL-06-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 2 km east, then 3 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["13", "1", "5", "9", "17"], "answerIndex": 0, "explanation": "Pythagoras: distance squared = 2^2 + 3^2 = 13.", "passage": "", "sourcePage": 6}, {"id": "KBL-06-Q31", "number": 31, "section": "reasoning", "stem": "A person faces North and turns 90 degrees to the left. Which direction does the person now face?", "options": ["North", "West", "Cannot be determined", "South", "East"], "answerIndex": 1, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-06-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All chairs are furniture. Some furniture are tables. Which conclusion definitely follows?", "options": ["Some furniture are chairs", "No chairs are furniture", "All tables are chairs", "All furniture are chairs", "All tables are furniture"], "answerIndex": 0, "explanation": "All chairs are furniture implies some furniture are chairs in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-06-Q33", "number": 33, "section": "reasoning", "stem": "Given E > K = J > C, which relation definitely holds?", "options": ["K < C", "E > C", "C > E", "E = C", "J = C"], "answerIndex": 1, "explanation": "Chain: E > K = J > C, so E > C.", "passage": "", "sourcePage": 6}, {"id": "KBL-06-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: J, G, E, B, A. Who sits immediately to the right of E?", "options": ["E", "G", "B", "J", "A"], "answerIndex": 2, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-06-Q35", "number": 35, "section": "reasoning", "stem": "Neha is the mother of Maya. Asha is the sister of Maya. How is Neha related to Asha?", "options": ["Sister", "Aunt", "Grandmother", "Daughter", "Mother"], "answerIndex": 4, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-06-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: T > S > X > U > W. Who is immediately heavier than X?", "options": ["X", "T", "S", "W", "U"], "answerIndex": 2, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-06-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 3, 9, 27, 81, ?", "options": ["252", "243", "216", "234", "225"], "answerIndex": 1, "explanation": "Every term is multiplied by 3.", "passage": "", "sourcePage": 7}, {"id": "KBL-06-Q38", "number": 38, "section": "reasoning", "stem": "If today is Wednesday, what day of the week will it be after 26 days?", "options": ["Monday", "Tuesday", "Thursday", "Sunday", "Friday"], "answerIndex": 0, "explanation": "Advance 5 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-06-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are D, B, H, N, J. Who occupies floor 3?", "options": ["N", "D", "H", "J", "B"], "answerIndex": 2, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-06-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in CASHIER?", "options": ["REIHSAC", "ASHIERC", "ACEHIRS", "CASHIER", "RCASHIE"], "answerIndex": 0, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-06-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 6?", "options": ["18", "30", "24", "12", "43"], "answerIndex": 4, "explanation": "43 leaves a remainder when divided by 6.", "passage": "", "sourcePage": 8}, {"id": "KBL-06-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 10 km east, then 3 km west. Where is the final position relative to the starting point?", "options": ["7 km west", "7 km east", "13 km west", "10 km north", "13 km east"], "answerIndex": 1, "explanation": "Net eastward movement = 10-3 = 7 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-06-Q43", "number": 43, "section": "gk", "stem": "What is Aadhaar primarily used as in banking onboarding?", "options": ["A debit card PIN", "A guaranteed credit score", "An identity number used under applicable KYC rules", "A fixed-deposit certificate", "A bank loan agreement"], "answerIndex": 2, "explanation": "Correct: An identity number used under applicable KYC rules.", "passage": "", "sourcePage": 8}, {"id": "KBL-06-Q44", "number": 44, "section": "gk", "stem": "What is the main purpose of a bank passbook or statement?", "options": ["Eliminate audits", "Replace PAN for every purpose", "Guarantee unlimited cash", "Set government budgets", "Record transactions and balances"], "answerIndex": 4, "explanation": "Correct: Record transactions and balances.", "passage": "", "sourcePage": 8}, {"id": "KBL-06-Q45", "number": 45, "section": "gk", "stem": "Which bank instrument can transfer money through an authorised digital payment system?", "options": ["Blank receipt", "Unfilled deposit slip", "NEFT", "Account brochure", "Unsigned letter"], "answerIndex": 2, "explanation": "Correct: NEFT.", "passage": "", "sourcePage": 8}, {"id": "KBL-06-Q46", "number": 46, "section": "gk", "stem": "Karnataka Bank is classified as which type of bank?", "options": ["Foreign central bank", "Cooperative society only", "Private sector bank", "Central bank", "Payments bank only"], "answerIndex": 2, "explanation": "Correct: Private sector bank.", "passage": "", "sourcePage": 8}, {"id": "KBL-06-Q47", "number": 47, "section": "gk", "stem": "Which account generally allows frequent deposits and withdrawals by individuals?", "options": ["Savings account", "Demat account", "Loan account", "Fixed deposit only", "Recurring deposit only"], "answerIndex": 0, "explanation": "Correct: Savings account.", "passage": "", "sourcePage": 8}, {"id": "KBL-06-Q48", "number": 48, "section": "gk", "stem": "Which Indian authority issues most banknotes?", "options": ["Reserve Bank of India", "Gram panchayat", "District collector", "Municipal corporation", "Stock exchange"], "answerIndex": 0, "explanation": "Correct: Reserve Bank of India.", "passage": "", "sourcePage": 9}, {"id": "KBL-06-Q49", "number": 49, "section": "gk", "stem": "Which entity supervises securities markets in India?", "options": ["SEBI", "UIDAI", "NABARD", "NITI Aayog", "RBI training college"], "answerIndex": 0, "explanation": "Correct: SEBI.", "passage": "", "sourcePage": 9}, {"id": "KBL-06-Q50", "number": 50, "section": "gk", "stem": "What does PAN stand for in Indian taxation?", "options": ["Public Account Nominee", "Payment Approval Number", "Permanent Address Name", "Private Asset Note", "Permanent Account Number"], "answerIndex": 4, "explanation": "Correct: Permanent Account Number.", "passage": "", "sourcePage": 9}, {"id": "KBL-06-Q51", "number": 51, "section": "gk", "stem": "What is bank reconciliation used for?", "options": ["Authorising passport renewals", "Changing a bank name", "Setting all rates to zero", "Matching records and identifying differences", "Printing new banknotes"], "answerIndex": 3, "explanation": "Correct: Matching records and identifying differences.", "passage": "", "sourcePage": 9}, {"id": "KBL-06-Q52", "number": 52, "section": "gk", "stem": "What does DBT commonly stand for in Indian public payments?", "options": ["Digital Bond Trade", "Debit Banking Token", "Demand Budget Tax", "Daily Balance Test", "Direct Benefit Transfer"], "answerIndex": 4, "explanation": "Correct: Direct Benefit Transfer.", "passage": "", "sourcePage": 9}, {"id": "KBL-06-Q53", "number": 53, "section": "gk", "stem": "Where is Karnataka Bank headquartered?", "options": ["Mumbai", "Chennai", "Udupi", "Mangaluru", "New Delhi"], "answerIndex": 3, "explanation": "Correct: Mangaluru.", "passage": "", "sourcePage": 9}, {"id": "KBL-06-Q54", "number": 54, "section": "computer", "stem": "What does URL stand for?", "options": ["Uniform Resource Locator", "Universal Router Login", "Utility Resource Library", "Unified Record Ledger", "User Reference Language"], "answerIndex": 0, "explanation": "Correct: Uniform Resource Locator.", "passage": "", "sourcePage": 9}, {"id": "KBL-06-Q55", "number": 55, "section": "computer", "stem": "What is a firewall used for?", "options": ["Typing letters", "Filtering network traffic according to security rules", "Editing images", "Printing receipts", "Charging a battery"], "answerIndex": 1, "explanation": "Correct: Filtering network traffic according to security rules.", "passage": "", "sourcePage": 10}, {"id": "KBL-06-Q56", "number": 56, "section": "computer", "stem": "What does LAN stand for?", "options": ["Local Application Note", "Local Area Network", "Long Address Node", "Large Access Number", "Linked Account Name"], "answerIndex": 1, "explanation": "Correct: Local Area Network.", "passage": "", "sourcePage": 10}, {"id": "KBL-06-Q57", "number": 57, "section": "computer", "stem": "What is a computer network?", "options": ["One disconnected calculator", "A desk telephone alone", "A fixed deposit", "Interconnected devices exchanging data", "A paper register"], "answerIndex": 3, "explanation": "Correct: Interconnected devices exchanging data.", "passage": "", "sourcePage": 10}, {"id": "KBL-06-Q58", "number": 58, "section": "computer", "stem": "What is a folder in a computer file system?", "options": ["An arithmetic operator", "A type of email spam", "A payment gateway", "A printer head", "Container for files and subfolders"], "answerIndex": 4, "explanation": "Correct: Container for files and subfolders.", "passage": "", "sourcePage": 10}, {"id": "KBL-06-Q59", "number": 59, "section": "computer", "stem": "What does HTML stand for?", "options": ["High Transfer Machine Language", "HighText Money Ledger", "Hyper Transfer Mail Link", "Home Tool Markup Line", "HyperText Markup Language"], "answerIndex": 4, "explanation": "Correct: HyperText Markup Language.", "passage": "", "sourcePage": 10}, {"id": "KBL-06-Q60", "number": 60, "section": "computer", "stem": "What is a strong sign of a suspicious banking email?", "options": ["It asks you to reveal an OTP or password", "It lists official working hours", "It contains a publicly known helpline", "It advertises a published product", "It gives a public branch address"], "answerIndex": 0, "explanation": "Correct: It asks you to reveal an OTP or password.", "passage": "", "sourcePage": 10}, {"id": "KBL-06-Q61", "number": 61, "section": "computer", "stem": "Which memory is volatile?", "options": ["DVD", "ROM", "Hard disk", "RAM", "SSD"], "answerIndex": 3, "explanation": "Correct: RAM.", "passage": "", "sourcePage": 10}, {"id": "KBL-06-Q62", "number": 62, "section": "computer", "stem": "Which device is generally an input device?", "options": ["Speaker", "Projector", "Keyboard", "Monitor", "Printer"], "answerIndex": 2, "explanation": "Correct: Keyboard.", "passage": "", "sourcePage": 11}, {"id": "KBL-06-Q63", "number": 63, "section": "computer", "stem": "What is malware?", "options": ["Hardware warranty", "Network cable", "Legal banking software only", "Malicious software", "Printer paper"], "answerIndex": 3, "explanation": "Correct: Malicious software.", "passage": "", "sourcePage": 11}, {"id": "KBL-06-Q64", "number": 64, "section": "computer", "stem": "Which of these is an operating system?", "options": ["Excel", "Google Search", "Microsoft Word", "Windows", "Photoshop"], "answerIndex": 3, "explanation": "Correct: Windows.", "passage": "", "sourcePage": 11}, {"id": "KBL-06-Q65", "number": 65, "section": "sales", "stem": "Case 6.1: A customer wants to activate digital banking. What should happen first?", "options": ["Use a fake website", "Explain features and verify identity using approved channels", "Activate someone else's account", "Ask them to tell you their PIN", "Send credentials through unsecured chat"], "answerIndex": 1, "explanation": "Correct: Explain features and verify identity using approved channels.", "passage": "", "sourcePage": 11}, {"id": "KBL-06-Q66", "number": 66, "section": "sales", "stem": "A potential customer refuses to share optional marketing data. What should you do?", "options": ["Threaten extra charges", "Guess answers on the form", "Publish personal data", "Respect consent and collect only data lawfully required", "Deny all services automatically"], "answerIndex": 3, "explanation": "Correct: Respect consent and collect only data lawfully required.", "passage": "", "sourcePage": 11}, {"id": "KBL-06-Q67", "number": 67, "section": "sales", "stem": "A customer urgently needs proof of a payment. What should you provide?", "options": ["An unverifiable verbal guarantee", "An available official transaction receipt or reference", "A fabricated UTR number", "An altered screenshot", "Another customer's statement"], "answerIndex": 1, "explanation": "Correct: An available official transaction receipt or reference.", "passage": "", "sourcePage": 11}, {"id": "KBL-06-Q68", "number": 68, "section": "sales", "stem": "Case 6.4: A customer complains angrily about a delayed transfer. What is the best first step?", "options": ["Listen, verify details and explain complaint handling", "Promise an instant refund without checking", "Delete transaction history", "Share another customer's details", "Argue with the customer"], "answerIndex": 0, "explanation": "Correct: Listen, verify details and explain complaint handling.", "passage": "", "sourcePage": 11}, {"id": "KBL-06-Q69", "number": 69, "section": "sales", "stem": "You have two customers waiting and one needs accessibility assistance. What should you do?", "options": ["Apply the branch's fair-service and accessibility procedures", "Give preferential service for a private gift", "Publicly disclose personal information", "Refuse assistance", "Make the visitor wait indefinitely"], "answerIndex": 0, "explanation": "Correct: Apply the branch's fair-service and accessibility procedures.", "passage": "", "sourcePage": 12}, {"id": "KBL-06-Q70", "number": 70, "section": "sales", "stem": "A customer asks why a transaction is pending. What is best?", "options": ["Check the status through authorised systems and explain next steps", "Ask the customer to pay you privately", "Invent a completion time", "Delete the receipt", "Advise them to disclose the OTP"], "answerIndex": 0, "explanation": "Correct: Check the status through authorised systems and explain next steps.", "passage": "", "sourcePage": 12}, {"id": "KBL-06-Q71", "number": 71, "section": "sales", "stem": "Case 6.7: A customer may benefit from a different product. What is good cross-selling?", "options": ["Explain an appropriate option and obtain informed consent", "Misstate returns", "Open it automatically", "Apply pressure to vulnerable customers", "Skip disclosure of charges"], "answerIndex": 0, "explanation": "Correct: Explain an appropriate option and obtain informed consent.", "passage": "", "sourcePage": 12}, {"id": "KBL-06-Q72", "number": 72, "section": "sales", "stem": "A customer wants to opt out of promotional contact. What should you do?", "options": ["Invent a consent record", "Demand a fee for an opt-out", "Continue calling regardless", "Follow the bank's opt-out and consent process", "Sell their number to others"], "answerIndex": 3, "explanation": "Correct: Follow the bank's opt-out and consent process.", "passage": "", "sourcePage": 12}, {"id": "KBL-06-Q73", "number": 73, "section": "sales", "stem": "The customer does not understand loan interest. What helps?", "options": ["Quote only a monthly payment without context", "Explain the rate, interest calculation and illustrative total cost", "Promise no interest will accrue", "Hide charges", "Alter the signed agreement"], "answerIndex": 1, "explanation": "Correct: Explain the rate, interest calculation and illustrative total cost.", "passage": "", "sourcePage": 12}, {"id": "KBL-06-Q74", "number": 74, "section": "sales", "stem": "Case 6.10: A customer complains about repeated sales calls. What should you do?", "options": ["Dismiss the objection", "Treat silence as consent", "Listen and process consent preferences or complaints", "Increase call frequency", "Sell the contact details"], "answerIndex": 2, "explanation": "Correct: Listen and process consent preferences or complaints.", "passage": "", "sourcePage": 12}, {"id": "KBL-06-Q75", "number": 75, "section": "sales", "stem": "A client asks for a loan that appears unaffordable. What should the CSA do?", "options": ["Encourage exaggerating income", "Explain suitability, repayment obligations and evaluation process", "Hide repayment cost", "Tell them to ignore instalments", "Promise automatic approval"], "answerIndex": 1, "explanation": "Correct: Explain suitability, repayment obligations and evaluation process.", "passage": "", "sourcePage": 12}]}, {"id": "KBL-07", "title": "Karnataka Bank CSA Mock 07", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_07.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-07-Q1", "number": 1, "section": "verbal", "stem": "What did the electronic display show?", "options": ["The token currently being served", "Daily interest rates", "Bank profits", "ATM passwords", "Employee salaries"], "answerIndex": 0, "explanation": "Supported directly by the reading passage.", "passage": "A branch decided to introduce an electronic token display for customer service desks. The display showed which token number was being served. Staff also checked whether visitors with accessibility needs required assistance. Although the system improved the orderliness of queues, the branch kept a staffed help desk for customers who had difficulty using tokens.", "sourcePage": 2}, {"id": "KBL-07-Q2", "number": 2, "section": "verbal", "stem": "What did staff check?", "options": ["Customers' shopping habits", "Private family matters", "Whether accessibility assistance was needed", "Preferred music", "Personal social media passwords"], "answerIndex": 2, "explanation": "Supported directly by the reading passage.", "passage": "A branch decided to introduce an electronic token display for customer service desks. The display showed which token number was being served. Staff also checked whether visitors with accessibility needs required assistance. Although the system improved the orderliness of queues, the branch kept a staffed help desk for customers who had difficulty using tokens.", "sourcePage": 2}, {"id": "KBL-07-Q3", "number": 3, "section": "verbal", "stem": "Why was the staffed help desk retained?", "options": ["To stop withdrawals", "To support people who struggled with tokens", "To eliminate customer service", "To block new accounts", "To replace all security controls"], "answerIndex": 1, "explanation": "Supported directly by the reading passage.", "passage": "A branch decided to introduce an electronic token display for customer service desks. The display showed which token number was being served. Staff also checked whether visitors with accessibility needs required assistance. Although the system improved the orderliness of queues, the branch kept a staffed help desk for customers who had difficulty using tokens.", "sourcePage": 2}, {"id": "KBL-07-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"valid\".", "options": ["foreign", "expired", "incorrect", "doubtful", "acceptable"], "answerIndex": 4, "explanation": "\"valid\" is closest in meaning to \"acceptable\".", "passage": "", "sourcePage": 2}, {"id": "KBL-07-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"efficient\".", "options": ["slow", "unreliable", "wasteful", "productive", "fragile"], "answerIndex": 3, "explanation": "\"efficient\" is closest in meaning to \"productive\".", "passage": "", "sourcePage": 2}, {"id": "KBL-07-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"early\".", "options": ["first", "soon", "late", "timely", "quick"], "answerIndex": 2, "explanation": "The opposite of \"early\" is \"late\".", "passage": "", "sourcePage": 2}, {"id": "KBL-07-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"success\".", "options": ["victory", "failure", "achievement", "reward", "progress"], "answerIndex": 1, "explanation": "The opposite of \"success\" is \"failure\".", "passage": "", "sourcePage": 3}, {"id": "KBL-07-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: No sooner did the call end ___ the next one began.", "options": ["that", "then", "when", "as", "than"], "answerIndex": 4, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-07-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: The staff members ___ attending training today.", "options": ["was", "has", "are", "is", "be"], "answerIndex": 2, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-07-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: Every form ___ checked before submission.", "options": ["is", "be", "were", "are", "have"], "answerIndex": 0, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-07-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"The forms has been checked.\"", "options": ["The forms has checked.", "The forms is been checked.", "The forms checking.", "The forms have been checked.", "The forms have check."], "answerIndex": 3, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-07-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The clerk verified the documents.\"", "options": ["The documents were verified by the clerk.", "The clerk was verified by the documents.", "The documents verified the clerk.", "The documents is verified by the clerk.", "The documents are verifying the clerk."], "answerIndex": 0, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-07-Q13", "number": 13, "section": "quant", "stem": "Find 25% of 960.", "options": ["220", "240", "230", "210", "250"], "answerIndex": 1, "explanation": "25/100 x 960 = 240.", "passage": "", "sourcePage": 3}, {"id": "KBL-07-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 3:7. If there are 120 students, how many girls are there?", "options": ["60", "48", "96", "84", "72"], "answerIndex": 3, "explanation": "One part = 120/(3+7) = 12; girls = 7 x 12.", "passage": "", "sourcePage": 4}, {"id": "KBL-07-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 1000 and sells it at 10% profit. Find the selling price (Rs).", "options": ["1040", "1100", "1080", "1120", "1060"], "answerIndex": 1, "explanation": "SP = 1000 x (1 + 10/100) = Rs 1100.", "passage": "", "sourcePage": 4}, {"id": "KBL-07-Q16", "number": 16, "section": "quant", "stem": "Find the average of 62, 66, 70, 74, 78.", "options": ["61", "67", "64", "73", "70"], "answerIndex": 4, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-07-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 12000 at 12% p.a. for 2 years.", "options": ["2520", "3000", "2880", "2640", "2760"], "answerIndex": 2, "explanation": "SI = 12000 x 12 x 2/100 = Rs 2880.", "passage": "", "sourcePage": 4}, {"id": "KBL-07-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 10000 at 10% per annum for 2 years, compounded annually.", "options": ["1900", "2100", "1800", "2200", "2000"], "answerIndex": 1, "explanation": "CI = 10000 x [(1+10/100)^2 -1] = Rs 2100.", "passage": "", "sourcePage": 4}, {"id": "KBL-07-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 6 days and B in 12 days. Working together, in how many days will they finish?", "options": ["5", "3", "4", "2", "1"], "answerIndex": 2, "explanation": "Combined time = (6 x 12)/(6+12) = 4 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-07-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 45 km/h for 5 hours. Find the distance travelled (km).", "options": ["203", "225", "181", "159", "247"], "answerIndex": 1, "explanation": "Distance = speed x time = 45 x 5 = 225 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-07-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 13, 23, 33, 43, ?", "options": ["23", "33", "63", "53", "43"], "answerIndex": 3, "explanation": "Each step adds 10.", "passage": "", "sourcePage": 5}, {"id": "KBL-07-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 2000 is sold at 30% discount. Find the selling price (Rs).", "options": ["1500", "1300", "1100", "1400", "1200"], "answerIndex": 3, "explanation": "SP = 2000 x (100-30)/100 = Rs 1400.", "passage": "", "sourcePage": 5}, {"id": "KBL-07-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 110 accounts on Monday and 210 on Tuesday. Branch B opened 110 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["440", "400", "420", "410", "430"], "answerIndex": 4, "explanation": "Total = 110 + 210 + 110 = 430.", "passage": "", "sourcePage": 5}, {"id": "KBL-07-Q24", "number": 24, "section": "quant", "stem": "Ravi is 12 years older than Meera. Their present ages add up to 36 years. What is Ravi's age?", "options": ["18", "24", "20", "26", "22"], "answerIndex": 1, "explanation": "Older age = (sum + difference)/2 = (36+12)/2 = 24.", "passage": "", "sourcePage": 5}, {"id": "KBL-07-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 8 and 24 hours; pipe C empties it in 12 hours. If all are opened together, when will the tank fill?", "options": ["6", "8", "12", "14", "10"], "answerIndex": 2, "explanation": "Net filling rate = 1/8 + 1/24 - 1/12 = 1/12 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-07-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 50 L and 15 L respectively. What is the simplified milk:water ratio?", "options": ["10:3", "10:4", "12:3", "11:3", "3:10"], "answerIndex": 0, "explanation": "Divide both quantities by HCF = 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-07-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 800. Its price rises by 25% and then falls by 20%. Find its final price (Rs).", "options": ["760", "840", "680", "800", "720"], "answerIndex": 3, "explanation": "Final price = 800 x 125/100 x 80/100 = 800.", "passage": "", "sourcePage": 5}, {"id": "KBL-07-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 1 place(s) forward in the alphabet. How is SAFE coded?", "options": ["TBGF", "XFKJ", "SAFE", "WEJI", "YGLK"], "answerIndex": 0, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-07-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 38 people, A is 25th from the front. What is A's rank from the back?", "options": ["11", "13", "15", "14", "12"], "answerIndex": 3, "explanation": "Back rank = total - front rank +1 = 38-25+1 = 14.", "passage": "", "sourcePage": 6}, {"id": "KBL-07-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 5 km east, then 4 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["45", "41", "37", "29", "33"], "answerIndex": 1, "explanation": "Pythagoras: distance squared = 5^2 + 4^2 = 41.", "passage": "", "sourcePage": 6}, {"id": "KBL-07-Q31", "number": 31, "section": "reasoning", "stem": "A person faces North and turns 90 degrees to the left. Which direction does the person now face?", "options": ["North", "West", "East", "Cannot be determined", "South"], "answerIndex": 1, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-07-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All pens are items. Some items are files. Which conclusion definitely follows?", "options": ["All files are pens", "All files are items", "No pens are items", "All items are pens", "Some items are pens"], "answerIndex": 4, "explanation": "All pens are items implies some items are pens in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-07-Q33", "number": 33, "section": "reasoning", "stem": "Given C > B = A > P, which relation definitely holds?", "options": ["B < P", "P > C", "C > P", "A = P", "C = P"], "answerIndex": 2, "explanation": "Chain: C > B = A > P, so C > P.", "passage": "", "sourcePage": 6}, {"id": "KBL-07-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: A, G, C, F, B. Who sits immediately to the right of F?", "options": ["A", "B", "F", "C", "G"], "answerIndex": 1, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-07-Q35", "number": 35, "section": "reasoning", "stem": "Asha is the mother of Leena. Divya is the sister of Leena. How is Asha related to Divya?", "options": ["Daughter", "Grandmother", "Sister", "Aunt", "Mother"], "answerIndex": 4, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-07-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: Q > X > P > S > R. Who is immediately heavier than P?", "options": ["Q", "X", "S", "P", "R"], "answerIndex": 1, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-07-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 7, 14, 28, 56, ?", "options": ["84", "126", "70", "112", "98"], "answerIndex": 3, "explanation": "Every term is multiplied by 2.", "passage": "", "sourcePage": 7}, {"id": "KBL-07-Q38", "number": 38, "section": "reasoning", "stem": "If today is Friday, what day of the week will it be after 28 days?", "options": ["Thursday", "Friday", "Saturday", "Tuesday", "Wednesday"], "answerIndex": 1, "explanation": "Advance 0 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-07-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are N, D, B, E, L. Who occupies floor 3?", "options": ["B", "N", "E", "L", "D"], "answerIndex": 0, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-07-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in BRANCH?", "options": ["HBRANC", "HCNARB", "RANCHB", "ABCHNR", "BRANCH"], "answerIndex": 1, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-07-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 2?", "options": ["8", "4", "15", "6", "10"], "answerIndex": 2, "explanation": "15 leaves a remainder when divided by 2.", "passage": "", "sourcePage": 8}, {"id": "KBL-07-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 6 km east, then 5 km west. Where is the final position relative to the starting point?", "options": ["1 km west", "11 km east", "11 km west", "1 km east", "6 km north"], "answerIndex": 3, "explanation": "Net eastward movement = 6-5 = 1 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-07-Q43", "number": 43, "section": "gk", "stem": "What does DBT commonly stand for in Indian public payments?", "options": ["Digital Bond Trade", "Daily Balance Test", "Direct Benefit Transfer", "Debit Banking Token", "Demand Budget Tax"], "answerIndex": 2, "explanation": "Correct: Direct Benefit Transfer.", "passage": "", "sourcePage": 8}, {"id": "KBL-07-Q44", "number": 44, "section": "gk", "stem": "Where is Karnataka Bank headquartered?", "options": ["Mumbai", "Udupi", "Mangaluru", "Chennai", "New Delhi"], "answerIndex": 2, "explanation": "Correct: Mangaluru.", "passage": "", "sourcePage": 8}, {"id": "KBL-07-Q45", "number": 45, "section": "gk", "stem": "What does KYC stand for in banking?", "options": ["Know Your Cheque", "Keep Your Credit", "Know Your Customer", "Know Your Currency", "Keep Your Cash"], "answerIndex": 2, "explanation": "Correct: Know Your Customer.", "passage": "", "sourcePage": 8}, {"id": "KBL-07-Q46", "number": 46, "section": "gk", "stem": "What does NPA stand for?", "options": ["Non-Performing Asset", "National Payments Agency", "Non-Priority Account", "Net Profit Addition", "New Personal Account"], "answerIndex": 0, "explanation": "Correct: Non-Performing Asset.", "passage": "", "sourcePage": 8}, {"id": "KBL-07-Q47", "number": 47, "section": "gk", "stem": "What is inflation?", "options": ["A guaranteed rise in bank deposits", "A reduction in money supply by definition", "A fixed bank charge", "A general rise in prices over time", "A fall in all interest rates"], "answerIndex": 3, "explanation": "Correct: A general rise in prices over time.", "passage": "", "sourcePage": 8}, {"id": "KBL-07-Q48", "number": 48, "section": "gk", "stem": "What is the main purpose of deposit insurance?", "options": ["Replace financial statements", "Protect eligible deposits within applicable limits", "Prevent all banking fraud", "Eliminate loan repayment", "Guarantee every investment return"], "answerIndex": 1, "explanation": "Correct: Protect eligible deposits within applicable limits.", "passage": "", "sourcePage": 9}, {"id": "KBL-07-Q49", "number": 49, "section": "gk", "stem": "Which is an example of a collateral-backed loan?", "options": ["Interest-free grant", "Loan with no security by definition", "Loan secured by pledged property", "Salary slip", "ATM withdrawal"], "answerIndex": 2, "explanation": "Correct: Loan secured by pledged property.", "passage": "", "sourcePage": 9}, {"id": "KBL-07-Q50", "number": 50, "section": "gk", "stem": "What is the role of a bank branch manager?", "options": ["Issue driving permits", "Approve weather forecasts", "Oversee branch operations and service", "Control national elections", "Print government passports"], "answerIndex": 2, "explanation": "Correct: Oversee branch operations and service.", "passage": "", "sourcePage": 9}, {"id": "KBL-07-Q51", "number": 51, "section": "gk", "stem": "What is the purpose of a recurring deposit?", "options": ["Save a fixed amount at regular intervals", "Borrow a fixed amount daily", "Withdraw cash without an account", "Create a debit card PIN", "Eliminate financial planning"], "answerIndex": 0, "explanation": "Correct: Save a fixed amount at regular intervals.", "passage": "", "sourcePage": 9}, {"id": "KBL-07-Q52", "number": 52, "section": "gk", "stem": "Which institution is the central bank of India?", "options": ["SEBI", "NABARD", "Reserve Bank of India", "SIDBI", "State Bank of India"], "answerIndex": 2, "explanation": "Correct: Reserve Bank of India.", "passage": "", "sourcePage": 9}, {"id": "KBL-07-Q53", "number": 53, "section": "gk", "stem": "What does IFSC identify?", "options": ["Account balance", "Customer age", "ATM cash level", "Cheque paper quality", "Bank branch for electronic payments"], "answerIndex": 4, "explanation": "Correct: Bank branch for electronic payments.", "passage": "", "sourcePage": 9}, {"id": "KBL-07-Q54", "number": 54, "section": "computer", "stem": "Which of these is an operating system?", "options": ["Microsoft Word", "Windows", "Excel", "Google Search", "Photoshop"], "answerIndex": 1, "explanation": "Correct: Windows.", "passage": "", "sourcePage": 9}, {"id": "KBL-07-Q55", "number": 55, "section": "computer", "stem": "What does USB stand for?", "options": ["Unified Security Board", "Universal Serial Bus", "User Service Backup", "Universal Storage Bank", "Ultra System Binary"], "answerIndex": 1, "explanation": "Correct: Universal Serial Bus.", "passage": "", "sourcePage": 10}, {"id": "KBL-07-Q56", "number": 56, "section": "computer", "stem": "What does RAM usually store while programs run?", "options": ["Temporary working data", "Optical labels", "Printed bank statements", "Only permanent engraved code", "Paper records"], "answerIndex": 0, "explanation": "Correct: Temporary working data.", "passage": "", "sourcePage": 10}, {"id": "KBL-07-Q57", "number": 57, "section": "computer", "stem": "Which file type commonly represents a compressed archive?", "options": [".wav", ".xlsx", ".jpg", ".zip", ".txt"], "answerIndex": 3, "explanation": "Correct: .zip.", "passage": "", "sourcePage": 10}, {"id": "KBL-07-Q58", "number": 58, "section": "computer", "stem": "Which service is primarily used to send email between servers?", "options": ["HTTP", "SMTP", "DNS", "FTP", "USB"], "answerIndex": 1, "explanation": "Correct: SMTP.", "passage": "", "sourcePage": 10}, {"id": "KBL-07-Q59", "number": 59, "section": "computer", "stem": "What does CPU stand for?", "options": ["Central Power Utility", "Central Print Unit", "Computer Personal Utility", "Central Processing Unit", "Control Program Unit"], "answerIndex": 3, "explanation": "Correct: Central Processing Unit.", "passage": "", "sourcePage": 10}, {"id": "KBL-07-Q60", "number": 60, "section": "computer", "stem": "Which device outputs printed documents?", "options": ["Keyboard", "Microphone", "Scanner", "Mouse", "Printer"], "answerIndex": 4, "explanation": "Correct: Printer.", "passage": "", "sourcePage": 10}, {"id": "KBL-07-Q61", "number": 61, "section": "computer", "stem": "What is two-factor authentication?", "options": ["Entering the same password twice", "Keeping two bank accounts", "Running two browsers", "Using two keyboards", "Using two different proof factors for login"], "answerIndex": 4, "explanation": "Correct: Using two different proof factors for login.", "passage": "", "sourcePage": 10}, {"id": "KBL-07-Q62", "number": 62, "section": "computer", "stem": "What is the default function of Ctrl+Z in many applications?", "options": ["Paste", "Undo", "Save", "Zoom to 100%", "Print"], "answerIndex": 1, "explanation": "Correct: Undo.", "passage": "", "sourcePage": 11}, {"id": "KBL-07-Q63", "number": 63, "section": "computer", "stem": "Which storage device usually has no moving mechanical disks?", "options": ["Magnetic tape drive", "Floppy drive", "Hard disk drive", "SSD", "DVD drive"], "answerIndex": 3, "explanation": "Correct: SSD.", "passage": "", "sourcePage": 11}, {"id": "KBL-07-Q64", "number": 64, "section": "computer", "stem": "Which tool can help compare two sets of numbers visually?", "options": ["Keyboard driver", "Password manager alone", "Operating-system update", "Chart", "Antivirus scan"], "answerIndex": 3, "explanation": "Correct: Chart.", "passage": "", "sourcePage": 11}, {"id": "KBL-07-Q65", "number": 65, "section": "sales", "stem": "Case 7.1: A customer complains about repeated sales calls. What should you do?", "options": ["Treat silence as consent", "Listen and process consent preferences or complaints", "Increase call frequency", "Dismiss the objection", "Sell the contact details"], "answerIndex": 1, "explanation": "Correct: Listen and process consent preferences or complaints.", "passage": "", "sourcePage": 11}, {"id": "KBL-07-Q66", "number": 66, "section": "sales", "stem": "A client asks for a loan that appears unaffordable. What should the CSA do?", "options": ["Hide repayment cost", "Encourage exaggerating income", "Tell them to ignore instalments", "Promise automatic approval", "Explain suitability, repayment obligations and evaluation process"], "answerIndex": 4, "explanation": "Correct: Explain suitability, repayment obligations and evaluation process.", "passage": "", "sourcePage": 11}, {"id": "KBL-07-Q67", "number": 67, "section": "sales", "stem": "A customer wants a product you do not fully understand. What should you do?", "options": ["Consult approved product information or a qualified colleague", "Ask a stranger for their login", "Promise a guaranteed return", "Invent terms to appear confident", "Skip suitability questions"], "answerIndex": 0, "explanation": "Correct: Consult approved product information or a qualified colleague.", "passage": "", "sourcePage": 11}, {"id": "KBL-07-Q68", "number": 68, "section": "sales", "stem": "Case 7.4: A customer wants to change registered contact information. What do you do?", "options": ["Follow approved identity verification and update procedures", "Share the existing password", "Change it based on a phone call with no verification", "Accept an unknown screenshot as final proof", "Tell them to post details publicly"], "answerIndex": 0, "explanation": "Correct: Follow approved identity verification and update procedures.", "passage": "", "sourcePage": 11}, {"id": "KBL-07-Q69", "number": 69, "section": "sales", "stem": "A customer requests a complaint reference. What should you do?", "options": ["Provide the official acknowledgement or reference as applicable", "Share a different customer's number", "Destroy the complaint", "Refuse any record", "Promise to call from a private number only"], "answerIndex": 0, "explanation": "Correct: Provide the official acknowledgement or reference as applicable.", "passage": "", "sourcePage": 12}, {"id": "KBL-07-Q70", "number": 70, "section": "sales", "stem": "How should a CSA respond to a service mistake?", "options": ["Delete the audit trail", "Make an unofficial cash offer", "Hide the error", "Acknowledge the issue and follow correction procedures", "Blame the customer without evidence"], "answerIndex": 3, "explanation": "Correct: Acknowledge the issue and follow correction procedures.", "passage": "", "sourcePage": 12}, {"id": "KBL-07-Q71", "number": 71, "section": "sales", "stem": "Case 7.7: A customer asks about an SMS alert service. What should be explained?", "options": ["That passwords should be shared", "That charges never change", "The service, eligibility and any applicable charge", "That SMS alerts replace all fraud checks", "Only that it is mandatory for every product"], "answerIndex": 2, "explanation": "Correct: The service, eligibility and any applicable charge.", "passage": "", "sourcePage": 12}, {"id": "KBL-07-Q72", "number": 72, "section": "sales", "stem": "You are unsure whether a customer qualifies for an offer. What should you do?", "options": ["Ask for cash to secure the offer", "Say they qualify without checking", "Invent a waiver", "Check eligibility using verified bank rules", "Change the eligibility rules"], "answerIndex": 3, "explanation": "Correct: Check eligibility using verified bank rules.", "passage": "", "sourcePage": 12}, {"id": "KBL-07-Q73", "number": 73, "section": "sales", "stem": "An elderly visitor struggles with a digital token machine. What is best?", "options": ["Ask the visitor to leave", "Skip verification rules", "Mock the visitor", "Offer respectful assistance and explain the process", "Collect their password"], "answerIndex": 3, "explanation": "Correct: Offer respectful assistance and explain the process.", "passage": "", "sourcePage": 12}, {"id": "KBL-07-Q74", "number": 74, "section": "sales", "stem": "Case 7.10: A customer notices an unknown debit. What is the correct action?", "options": ["Ask for their PIN", "Guarantee funds will return without investigation", "Guide them to report it promptly through official channels", "Post their account details online", "Tell them to ignore it"], "answerIndex": 2, "explanation": "Correct: Guide them to report it promptly through official channels.", "passage": "", "sourcePage": 12}, {"id": "KBL-07-Q75", "number": 75, "section": "sales", "stem": "A client has not understood the difference between debit and credit cards. What is best?", "options": ["Emphasise benefits only", "Say the two products are identical", "Explain how each works, including repayment terms for credit cards", "Request card PINs", "Ignore interest and charges"], "answerIndex": 2, "explanation": "Correct: Explain how each works, including repayment terms for credit cards.", "passage": "", "sourcePage": 12}]}, {"id": "KBL-08", "title": "Karnataka Bank CSA Mock 08", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_08.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-08-Q1", "number": 1, "section": "verbal", "stem": "What expenses were entered in the monthly record?", "options": ["Only bank charges", "Groceries, transport and utility bills", "Only land purchases", "Only education fees", "Only long-term investments"], "answerIndex": 1, "explanation": "Supported directly by the reading passage.", "passage": "A family began keeping separate records for monthly expenses and long-term savings. The monthly record covered groceries, transport and utility bills. A second record tracked progress toward educational expenses planned several years ahead. Separating the two goals helped the family avoid using education savings for routine spending.", "sourcePage": 2}, {"id": "KBL-08-Q2", "number": 2, "section": "verbal", "stem": "What was the second record for?", "options": ["Stock delivery dates", "Future education savings", "Daily travel times", "Employee attendance", "Loan collections"], "answerIndex": 1, "explanation": "Supported directly by the reading passage.", "passage": "A family began keeping separate records for monthly expenses and long-term savings. The monthly record covered groceries, transport and utility bills. A second record tracked progress toward educational expenses planned several years ahead. Separating the two goals helped the family avoid using education savings for routine spending.", "sourcePage": 2}, {"id": "KBL-08-Q3", "number": 3, "section": "verbal", "stem": "What benefit came from separating records?", "options": ["Elimination of all taxes", "Automatic salary increases", "No need to plan expenses", "Guaranteed investment returns", "Less chance of spending future savings on routine bills"], "answerIndex": 4, "explanation": "Supported directly by the reading passage.", "passage": "A family began keeping separate records for monthly expenses and long-term savings. The monthly record covered groceries, transport and utility bills. A second record tracked progress toward educational expenses planned several years ahead. Separating the two goals helped the family avoid using education savings for routine spending.", "sourcePage": 2}, {"id": "KBL-08-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"retain\".", "options": ["discard", "keep", "lose", "refuse", "cancel"], "answerIndex": 1, "explanation": "\"retain\" is closest in meaning to \"keep\".", "passage": "", "sourcePage": 2}, {"id": "KBL-08-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"resolve\".", "options": ["repeat", "settle", "overlook", "delay", "complicate"], "answerIndex": 1, "explanation": "\"resolve\" is closest in meaning to \"settle\".", "passage": "", "sourcePage": 2}, {"id": "KBL-08-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"safe\".", "options": ["guarded", "dangerous", "protected", "stable", "secure"], "answerIndex": 1, "explanation": "The opposite of \"safe\" is \"dangerous\".", "passage": "", "sourcePage": 2}, {"id": "KBL-08-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"scarce\".", "options": ["few", "insufficient", "limited", "abundant", "rare"], "answerIndex": 3, "explanation": "The opposite of \"scarce\" is \"abundant\".", "passage": "", "sourcePage": 3}, {"id": "KBL-08-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: If it rains, the outdoor event ___ postponed.", "options": ["has", "have been", "will be", "being", "would have"], "answerIndex": 2, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-08-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: He is senior ___ me in the department.", "options": ["from", "than", "for", "as", "to"], "answerIndex": 4, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-08-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: Customers should ___ their PIN confidential.", "options": ["kept", "keeping", "keeps", "keep", "to keeping"], "answerIndex": 3, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-08-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"They was waiting near the counter.\"", "options": ["They has waiting near the counter.", "They be waiting near the counter.", "They were wait near the counter.", "They were waiting near the counter.", "They is waiting near the counter."], "answerIndex": 3, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-08-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The manager approved the request.\"", "options": ["The request was approved by the manager.", "The request has approve the manager.", "The manager was approved by the request.", "The request is approve by the manager.", "The request approved the manager."], "answerIndex": 0, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-08-Q13", "number": 13, "section": "quant", "stem": "Find 10% of 480.", "options": ["24", "40", "32", "56", "48"], "answerIndex": 4, "explanation": "10/100 x 480 = 48.", "passage": "", "sourcePage": 3}, {"id": "KBL-08-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 4:7. If there are 132 students, how many girls are there?", "options": ["48", "72", "60", "84", "96"], "answerIndex": 3, "explanation": "One part = 132/(4+7) = 12; girls = 7 x 12.", "passage": "", "sourcePage": 4}, {"id": "KBL-08-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 1600 and sells it at 15% profit. Find the selling price (Rs).", "options": ["1776", "1872", "1808", "1840", "1744"], "answerIndex": 3, "explanation": "SP = 1600 x (1 + 15/100) = Rs 1840.", "passage": "", "sourcePage": 4}, {"id": "KBL-08-Q16", "number": 16, "section": "quant", "stem": "Find the average of 52, 56, 60, 64, 68.", "options": ["51", "60", "57", "54", "63"], "answerIndex": 1, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-08-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 15000 at 8% p.a. for 2 years.", "options": ["2550", "2250", "1950", "2100", "2400"], "answerIndex": 4, "explanation": "SI = 15000 x 8 x 2/100 = Rs 2400.", "passage": "", "sourcePage": 4}, {"id": "KBL-08-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 20000 at 10% per annum for 2 years, compounded annually.", "options": ["4000", "4400", "3600", "4200", "3800"], "answerIndex": 3, "explanation": "CI = 20000 x [(1+10/100)^2 -1] = Rs 4200.", "passage": "", "sourcePage": 4}, {"id": "KBL-08-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 5 days and B in 20 days. Working together, in how many days will they finish?", "options": ["4", "1", "2", "3", "5"], "answerIndex": 0, "explanation": "Combined time = (5 x 20)/(5+20) = 4 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-08-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 36 km/h for 2 hours. Find the distance travelled (km).", "options": ["18", "72", "90", "54", "36"], "answerIndex": 1, "explanation": "Distance = speed x time = 36 x 2 = 72 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-08-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 6, 11, 16, 21, ?", "options": ["16", "21", "26", "11", "31"], "answerIndex": 2, "explanation": "Each step adds 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-08-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 800 is sold at 10% discount. Find the selling price (Rs).", "options": ["640", "760", "680", "720", "600"], "answerIndex": 3, "explanation": "SP = 800 x (100-10)/100 = Rs 720.", "passage": "", "sourcePage": 5}, {"id": "KBL-08-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 160 accounts on Monday and 90 on Tuesday. Branch B opened 180 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["430", "420", "400", "410", "440"], "answerIndex": 0, "explanation": "Total = 160 + 90 + 180 = 430.", "passage": "", "sourcePage": 5}, {"id": "KBL-08-Q24", "number": 24, "section": "quant", "stem": "Ravi is 10 years older than Meera. Their present ages add up to 54 years. What is Ravi's age?", "options": ["28", "34", "30", "26", "32"], "answerIndex": 4, "explanation": "Older age = (sum + difference)/2 = (54+10)/2 = 32.", "passage": "", "sourcePage": 5}, {"id": "KBL-08-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 10 and 20 hours; pipe C empties it in 10 hours. If all are opened together, when will the tank fill?", "options": ["14", "16", "20", "22", "18"], "answerIndex": 2, "explanation": "Net filling rate = 1/10 + 1/20 - 1/10 = 1/20 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-08-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 20 L and 5 L respectively. What is the simplified milk:water ratio?", "options": ["1:4", "6:1", "4:1", "4:2", "5:1"], "answerIndex": 2, "explanation": "Divide both quantities by HCF = 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-08-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 500. Its price rises by 10% and then falls by 10%. Find its final price (Rs).", "options": ["470", "495", "520", "420", "445"], "answerIndex": 1, "explanation": "Final price = 500 x 110/100 x 90/100 = 495.", "passage": "", "sourcePage": 5}, {"id": "KBL-08-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 2 place(s) forward in the alphabet. How is CARD coded?", "options": ["ECTF", "CARD", "GEVH", "IGXJ", "HFWI"], "answerIndex": 0, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-08-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 48 people, A is 39th from the front. What is A's rank from the back?", "options": ["9", "7", "8", "11", "10"], "answerIndex": 4, "explanation": "Back rank = total - front rank +1 = 48-39+1 = 10.", "passage": "", "sourcePage": 6}, {"id": "KBL-08-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 5 km east, then 3 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["26", "38", "22", "34", "30"], "answerIndex": 3, "explanation": "Pythagoras: distance squared = 5^2 + 3^2 = 34.", "passage": "", "sourcePage": 6}, {"id": "KBL-08-Q31", "number": 31, "section": "reasoning", "stem": "A person faces East and turns 90 degrees to the right. Which direction does the person now face?", "options": ["South", "North", "West", "Cannot be determined", "East"], "answerIndex": 0, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-08-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All pens are items. Some items are files. Which conclusion definitely follows?", "options": ["No pens are items", "All files are pens", "All files are items", "All items are pens", "Some items are pens"], "answerIndex": 4, "explanation": "All pens are items implies some items are pens in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-08-Q33", "number": 33, "section": "reasoning", "stem": "Given D > G = C > L, which relation definitely holds?", "options": ["D = L", "L > D", "D > L", "C = L", "G < L"], "answerIndex": 2, "explanation": "Chain: D > G = C > L, so D > L.", "passage": "", "sourcePage": 6}, {"id": "KBL-08-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: C, K, B, G, A. Who sits immediately to the right of C?", "options": ["K", "G", "B", "A", "C"], "answerIndex": 0, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-08-Q35", "number": 35, "section": "reasoning", "stem": "Divya is the mother of Asha. Pooja is the sister of Asha. How is Divya related to Pooja?", "options": ["Mother", "Sister", "Aunt", "Daughter", "Grandmother"], "answerIndex": 0, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-08-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: Q > S > W > X > R. Who is immediately heavier than X?", "options": ["S", "Q", "R", "X", "W"], "answerIndex": 4, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-08-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 6, 18, 54, 162, ?", "options": ["486", "504", "450", "468", "432"], "answerIndex": 0, "explanation": "Every term is multiplied by 3.", "passage": "", "sourcePage": 7}, {"id": "KBL-08-Q38", "number": 38, "section": "reasoning", "stem": "If today is Saturday, what day of the week will it be after 15 days?", "options": ["Thursday", "Saturday", "Sunday", "Friday", "Monday"], "answerIndex": 2, "explanation": "Advance 1 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-08-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are J, N, K, D, H. Who occupies floor 3?", "options": ["K", "D", "N", "H", "J"], "answerIndex": 0, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-08-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in CASHIER?", "options": ["CASHIER", "REIHSAC", "RCASHIE", "ASHIERC", "ACEHIRS"], "answerIndex": 1, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-08-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 2?", "options": ["4", "10", "15", "6", "8"], "answerIndex": 2, "explanation": "15 leaves a remainder when divided by 2.", "passage": "", "sourcePage": 8}, {"id": "KBL-08-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 8 km east, then 3 km west. Where is the final position relative to the starting point?", "options": ["5 km west", "5 km east", "11 km west", "11 km east", "8 km north"], "answerIndex": 1, "explanation": "Net eastward movement = 8-3 = 5 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-08-Q43", "number": 43, "section": "gk", "stem": "Which institution is the central bank of India?", "options": ["Reserve Bank of India", "NABARD", "SIDBI", "State Bank of India", "SEBI"], "answerIndex": 0, "explanation": "Correct: Reserve Bank of India.", "passage": "", "sourcePage": 8}, {"id": "KBL-08-Q44", "number": 44, "section": "gk", "stem": "What does IFSC identify?", "options": ["Bank branch for electronic payments", "ATM cash level", "Customer age", "Account balance", "Cheque paper quality"], "answerIndex": 0, "explanation": "Correct: Bank branch for electronic payments.", "passage": "", "sourcePage": 8}, {"id": "KBL-08-Q45", "number": 45, "section": "gk", "stem": "What is a standing instruction?", "options": ["A branch opening advertisement", "A banknote verification stamp", "A request to close every account", "An authorisation for recurring account transactions", "A cheque without a date"], "answerIndex": 3, "explanation": "Correct: An authorisation for recurring account transactions.", "passage": "", "sourcePage": 8}, {"id": "KBL-08-Q46", "number": 46, "section": "gk", "stem": "Which money is usually held to meet near-term cash needs?", "options": ["Goodwill", "Inventory write-off", "Fixed assets only", "Liquid funds", "Building depreciation"], "answerIndex": 3, "explanation": "Correct: Liquid funds.", "passage": "", "sourcePage": 8}, {"id": "KBL-08-Q47", "number": 47, "section": "gk", "stem": "What does EMI mean?", "options": ["Emergency Monetary Insurance", "Equated Monthly Instalment", "Electronic Money Index", "Equal Monthly Income", "Easy Market Investment"], "answerIndex": 1, "explanation": "Correct: Equated Monthly Instalment.", "passage": "", "sourcePage": 8}, {"id": "KBL-08-Q48", "number": 48, "section": "gk", "stem": "What is a bank overdraft?", "options": ["A currency exchange rate", "A free insurance guarantee", "An approved facility allowing debit beyond available balance up to a limit", "A fixed investment return", "A cash deposit receipt"], "answerIndex": 2, "explanation": "Correct: An approved facility allowing debit beyond available balance up to a limit.", "passage": "", "sourcePage": 9}, {"id": "KBL-08-Q49", "number": 49, "section": "gk", "stem": "What does a bank sanction letter generally convey?", "options": ["Terms of a credit facility approved subject to conditions", "A pension card", "A withdrawal receipt", "A property sale agreement", "Final proof all instalments were paid"], "answerIndex": 0, "explanation": "Correct: Terms of a credit facility approved subject to conditions.", "passage": "", "sourcePage": 9}, {"id": "KBL-08-Q50", "number": 50, "section": "gk", "stem": "Which channel is commonly used to make instant UPI payments?", "options": ["An unsigned cheque", "Only postal mail", "A paper ledger only", "A compatible payment app", "A printed passbook only"], "answerIndex": 3, "explanation": "Correct: A compatible payment app.", "passage": "", "sourcePage": 9}, {"id": "KBL-08-Q51", "number": 51, "section": "gk", "stem": "Which of these usually earns interest for a fixed agreed tenure?", "options": ["Passbook", "Debit card", "Fixed deposit", "Demand draft", "Current account"], "answerIndex": 2, "explanation": "Correct: Fixed deposit.", "passage": "", "sourcePage": 9}, {"id": "KBL-08-Q52", "number": 52, "section": "gk", "stem": "Which payment instrument is a written order directing a bank to pay?", "options": ["Passbook", "Balance sheet", "Cheque", "Receipt", "Invoice"], "answerIndex": 2, "explanation": "Correct: Cheque.", "passage": "", "sourcePage": 9}, {"id": "KBL-08-Q53", "number": 53, "section": "gk", "stem": "Which type of rate is used for RBI lending to banks under a repo transaction?", "options": ["Exchange commission", "Dividend yield", "Repo rate", "Stamp duty", "GST rate"], "answerIndex": 2, "explanation": "Correct: Repo rate.", "passage": "", "sourcePage": 9}, {"id": "KBL-08-Q54", "number": 54, "section": "computer", "stem": "Which tool can help compare two sets of numbers visually?", "options": ["Operating-system update", "Chart", "Password manager alone", "Antivirus scan", "Keyboard driver"], "answerIndex": 1, "explanation": "Correct: Chart.", "passage": "", "sourcePage": 9}, {"id": "KBL-08-Q55", "number": 55, "section": "computer", "stem": "What is an operating-system user account used for?", "options": ["Only to scan cheques", "To control the national currency", "Managing individual access and settings", "To guarantee a loan", "Only to calculate interest"], "answerIndex": 2, "explanation": "Correct: Managing individual access and settings.", "passage": "", "sourcePage": 10}, {"id": "KBL-08-Q56", "number": 56, "section": "computer", "stem": "What is a computer virus?", "options": ["Malicious code that can replicate by infecting files or programs", "A bank cheque", "An internet cable", "A normal spreadsheet formula", "A computer monitor"], "answerIndex": 0, "explanation": "Correct: Malicious code that can replicate by infecting files or programs.", "passage": "", "sourcePage": 10}, {"id": "KBL-08-Q57", "number": 57, "section": "computer", "stem": "What is a cache?", "options": ["A tax deduction", "Storage that helps speed up repeated access to data", "A loan guarantee", "A mandatory paper passbook", "A type of keyboard layout only"], "answerIndex": 1, "explanation": "Correct: Storage that helps speed up repeated access to data.", "passage": "", "sourcePage": 10}, {"id": "KBL-08-Q58", "number": 58, "section": "computer", "stem": "Which file extension is common for modern Excel workbooks?", "options": [".png", ".mp3", ".zip", ".exe", ".xlsx"], "answerIndex": 4, "explanation": "Correct: .xlsx.", "passage": "", "sourcePage": 10}, {"id": "KBL-08-Q59", "number": 59, "section": "computer", "stem": "What does PDF stand for?", "options": ["Printed Document Function", "Program Data Form", "Personal Data Folder", "Public Display File", "Portable Document Format"], "answerIndex": 4, "explanation": "Correct: Portable Document Format.", "passage": "", "sourcePage": 10}, {"id": "KBL-08-Q60", "number": 60, "section": "computer", "stem": "What is a backup?", "options": ["A renamed folder", "A web advertisement", "A separate copy of data for recovery", "A bank overdraft", "A deleted file only"], "answerIndex": 2, "explanation": "Correct: A separate copy of data for recovery.", "passage": "", "sourcePage": 10}, {"id": "KBL-08-Q61", "number": 61, "section": "computer", "stem": "What is the main purpose of a strong password?", "options": ["Create credit history", "Increase screen brightness", "Reduce risk of unauthorised account access", "Speed up broadband automatically", "Improve print quality"], "answerIndex": 2, "explanation": "Correct: Reduce risk of unauthorised account access.", "passage": "", "sourcePage": 10}, {"id": "KBL-08-Q62", "number": 62, "section": "computer", "stem": "What does SQL stand for?", "options": ["System Query Loop", "Sequential Quality Link", "Structured Query Language", "Standard Quick Logic", "Secure Queue Ledger"], "answerIndex": 2, "explanation": "Correct: Structured Query Language.", "passage": "", "sourcePage": 11}, {"id": "KBL-08-Q63", "number": 63, "section": "computer", "stem": "What is software update primarily used for?", "options": ["Increasing electricity voltage", "Replacing all files with images", "Changing the computer's weight", "Applying improvements and security fixes", "Printing cash vouchers"], "answerIndex": 3, "explanation": "Correct: Applying improvements and security fixes.", "passage": "", "sourcePage": 11}, {"id": "KBL-08-Q64", "number": 64, "section": "computer", "stem": "Which part of a computer executes arithmetic and logic operations?", "options": ["Cooling fan", "Printer port", "ALU", "Display panel", "Optical drive"], "answerIndex": 2, "explanation": "Correct: ALU.", "passage": "", "sourcePage": 11}, {"id": "KBL-08-Q65", "number": 65, "section": "sales", "stem": "Case 8.1: A customer notices an unknown debit. What is the correct action?", "options": ["Guide them to report it promptly through official channels", "Post their account details online", "Ask for their PIN", "Guarantee funds will return without investigation", "Tell them to ignore it"], "answerIndex": 0, "explanation": "Correct: Guide them to report it promptly through official channels.", "passage": "", "sourcePage": 11}, {"id": "KBL-08-Q66", "number": 66, "section": "sales", "stem": "A client has not understood the difference between debit and credit cards. What is best?", "options": ["Request card PINs", "Say the two products are identical", "Explain how each works, including repayment terms for credit cards", "Emphasise benefits only", "Ignore interest and charges"], "answerIndex": 2, "explanation": "Correct: Explain how each works, including repayment terms for credit cards.", "passage": "", "sourcePage": 11}, {"id": "KBL-08-Q67", "number": 67, "section": "sales", "stem": "A customer asks about a fee waiver. What is the best response?", "options": ["Check eligibility and the published policy", "Promise a waiver to everyone", "Ask for an unofficial payment", "Change the fee table personally", "Avoid documenting the request"], "answerIndex": 0, "explanation": "Correct: Check eligibility and the published policy.", "passage": "", "sourcePage": 11}, {"id": "KBL-08-Q68", "number": 68, "section": "sales", "stem": "Case 8.4: The customer is considering a loan but worries about instalments. What helps?", "options": ["Focus only on the maximum loan amount", "Omit interest rates", "Promise a grant", "Suggest hiding existing debts", "Show repayment obligations and assess affordability"], "answerIndex": 4, "explanation": "Correct: Show repayment obligations and assess affordability.", "passage": "", "sourcePage": 11}, {"id": "KBL-08-Q69", "number": 69, "section": "sales", "stem": "A client wants to open an account for another adult without that person present or authorised. What is best?", "options": ["Use your own identity", "Create a fictional address", "Explain valid account-opening and authorisation requirements", "Forge the absent person's signature", "Skip all consent"], "answerIndex": 2, "explanation": "Correct: Explain valid account-opening and authorisation requirements.", "passage": "", "sourcePage": 12}, {"id": "KBL-08-Q70", "number": 70, "section": "sales", "stem": "A customer forgot online-banking credentials. What is best?", "options": ["Guide them through official recovery after verification", "Disable all verification", "Set a shared password for everyone", "Ask for an old password aloud", "Share an employee's password"], "answerIndex": 0, "explanation": "Correct: Guide them through official recovery after verification.", "passage": "", "sourcePage": 12}, {"id": "KBL-08-Q71", "number": 71, "section": "sales", "stem": "Case 8.7: A customer says the mobile banking app feels unsafe. What should the CSA do?", "options": ["Dismiss the concern", "Ask for the OTP to demonstrate", "Promise no digital fraud can ever occur", "Explain security features, verify needs, and offer guided help", "Force immediate enrolment"], "answerIndex": 3, "explanation": "Correct: Explain security features, verify needs, and offer guided help.", "passage": "", "sourcePage": 12}, {"id": "KBL-08-Q72", "number": 72, "section": "sales", "stem": "A customer asks which savings account suits frequent withdrawals. What is best?", "options": ["Hide account fees", "Open accounts without approval", "Recommend a long lock-in without asking", "Sell only the account with the highest sales incentive", "Ask about usage and compare account features transparently"], "answerIndex": 4, "explanation": "Correct: Ask about usage and compare account features transparently.", "passage": "", "sourcePage": 12}, {"id": "KBL-08-Q73", "number": 73, "section": "sales", "stem": "A customer asks for loan processing charges. What should you do?", "options": ["Hide charges until after signature", "Ask the customer to pay your personal account", "Make up a lower fee", "Say there are never any charges", "State the applicable charges and refer to official disclosures"], "answerIndex": 4, "explanation": "Correct: State the applicable charges and refer to official disclosures.", "passage": "", "sourcePage": 12}, {"id": "KBL-08-Q74", "number": 74, "section": "sales", "stem": "Case 8.10: Your sales target conflicts with customer suitability. Which takes priority?", "options": ["Hiding risk warnings", "Changing signed forms", "Closing a sale irrespective of need", "Highest sales commission", "Customer suitability and compliance"], "answerIndex": 4, "explanation": "Correct: Customer suitability and compliance.", "passage": "", "sourcePage": 12}, {"id": "KBL-08-Q75", "number": 75, "section": "sales", "stem": "A customer asks whether minimum balance charges apply. What is best?", "options": ["Say all accounts are free", "Ask for a password first", "Explain the relevant account conditions accurately", "Hide exceptions", "Invent a new charge"], "answerIndex": 2, "explanation": "Correct: Explain the relevant account conditions accurately.", "passage": "", "sourcePage": 12}]}, {"id": "KBL-09", "title": "Karnataka Bank CSA Mock 09", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_09.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-09-Q1", "number": 1, "section": "verbal", "stem": "Why was verification required?", "options": ["To increase loan interest", "To change the branch name", "To cancel online banking", "To delay all customers", "To protect account access"], "answerIndex": 4, "explanation": "Supported directly by the reading passage.", "passage": "A customer wanted to update the mobile number linked with a bank account. The employee asked the customer to use the bank's approved verification procedure rather than accept an informal request. After verification, the employee explained how to check that alerts reach the new number. The employee also reminded the customer to secure the phone with a strong screen lock.", "sourcePage": 2}, {"id": "KBL-09-Q2", "number": 2, "section": "verbal", "stem": "What should the customer check after the update?", "options": ["Whether alerts reach the new number", "Whether the branch has a cafeteria", "Whether ATM cash is coloured", "Whether deposit rates double", "Whether old messages vanish everywhere"], "answerIndex": 0, "explanation": "Supported directly by the reading passage.", "passage": "A customer wanted to update the mobile number linked with a bank account. The employee asked the customer to use the bank's approved verification procedure rather than accept an informal request. After verification, the employee explained how to check that alerts reach the new number. The employee also reminded the customer to secure the phone with a strong screen lock.", "sourcePage": 2}, {"id": "KBL-09-Q3", "number": 3, "section": "verbal", "stem": "Which additional safety measure was advised?", "options": ["Ignore suspicious calls", "Disable every alert", "Write the OTP on social media", "Use a strong screen lock", "Share phone PIN freely"], "answerIndex": 3, "explanation": "Supported directly by the reading passage.", "passage": "A customer wanted to update the mobile number linked with a bank account. The employee asked the customer to use the bank's approved verification procedure rather than accept an informal request. After verification, the employee explained how to check that alerts reach the new number. The employee also reminded the customer to secure the phone with a strong screen lock.", "sourcePage": 2}, {"id": "KBL-09-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"notify\".", "options": ["collect", "conceal", "reject", "inform", "disagree"], "answerIndex": 3, "explanation": "\"notify\" is closest in meaning to \"inform\".", "passage": "", "sourcePage": 2}, {"id": "KBL-09-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"verify\".", "options": ["confirm", "assume", "invent", "ignore", "delay"], "answerIndex": 0, "explanation": "\"verify\" is closest in meaning to \"confirm\".", "passage": "", "sourcePage": 2}, {"id": "KBL-09-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"increase\".", "options": ["rise", "grow", "expand", "multiply", "decrease"], "answerIndex": 4, "explanation": "The opposite of \"increase\" is \"decrease\".", "passage": "", "sourcePage": 2}, {"id": "KBL-09-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"temporary\".", "options": ["momentary", "brief", "permanent", "passing", "short"], "answerIndex": 2, "explanation": "The opposite of \"temporary\" is \"permanent\".", "passage": "", "sourcePage": 3}, {"id": "KBL-09-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: The account details must be entered ___.", "options": ["more carefuler", "carefully", "caring", "care", "careful"], "answerIndex": 1, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-09-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: Every form ___ checked before submission.", "options": ["have", "are", "be", "is", "were"], "answerIndex": 3, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-09-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: The manager, along with the officers, ___ present.", "options": ["be", "were", "are", "have", "was"], "answerIndex": 4, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-09-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"She is working here since 2020.\"", "options": ["She work here since 2020.", "She worked here since 2020 and still.", "She have been working here since 2020.", "She was been working here since 2020.", "She has been working here since 2020."], "answerIndex": 4, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-09-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The team completed the audit.\"", "options": ["The audit were completed by the team.", "The audit completed the team.", "The audit is completing by the team.", "The audit was completed by the team.", "The team was completed by the audit."], "answerIndex": 3, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-09-Q13", "number": 13, "section": "quant", "stem": "Find 25% of 320.", "options": ["72", "68", "76", "84", "80"], "answerIndex": 4, "explanation": "25/100 x 320 = 80.", "passage": "", "sourcePage": 3}, {"id": "KBL-09-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 5:6. If there are 143 students, how many girls are there?", "options": ["39", "52", "78", "65", "91"], "answerIndex": 2, "explanation": "One part = 143/(5+6) = 13; girls = 6 x 13.", "passage": "", "sourcePage": 4}, {"id": "KBL-09-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 1000 and sells it at 25% profit. Find the selling price (Rs).", "options": ["1250", "1190", "1270", "1210", "1230"], "answerIndex": 0, "explanation": "SP = 1000 x (1 + 25/100) = Rs 1250.", "passage": "", "sourcePage": 4}, {"id": "KBL-09-Q16", "number": 16, "section": "quant", "stem": "Find the average of 39, 43, 47, 51, 55.", "options": ["50", "41", "44", "47", "38"], "answerIndex": 3, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-09-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 7000 at 12% p.a. for 2 years.", "options": ["1750", "1470", "1680", "1540", "1610"], "answerIndex": 2, "explanation": "SI = 7000 x 12 x 2/100 = Rs 1680.", "passage": "", "sourcePage": 4}, {"id": "KBL-09-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 10000 at 20% per annum for 2 years, compounded annually.", "options": ["4400", "4200", "4500", "4100", "4300"], "answerIndex": 0, "explanation": "CI = 10000 x [(1+20/100)^2 -1] = Rs 4400.", "passage": "", "sourcePage": 4}, {"id": "KBL-09-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 6 days and B in 12 days. Working together, in how many days will they finish?", "options": ["1", "2", "4", "3", "5"], "answerIndex": 2, "explanation": "Combined time = (6 x 12)/(6+12) = 4 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-09-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 72 km/h for 5 hours. Find the distance travelled (km).", "options": ["252", "288", "324", "396", "360"], "answerIndex": 4, "explanation": "Distance = speed x time = 72 x 5 = 360 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-09-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 8, 12, 16, 20, ?", "options": ["28", "12", "24", "16", "20"], "answerIndex": 2, "explanation": "Each step adds 4.", "passage": "", "sourcePage": 5}, {"id": "KBL-09-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 1000 is sold at 10% discount. Find the selling price (Rs).", "options": ["950", "900", "850", "800", "750"], "answerIndex": 1, "explanation": "SP = 1000 x (100-10)/100 = Rs 900.", "passage": "", "sourcePage": 5}, {"id": "KBL-09-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 100 accounts on Monday and 90 on Tuesday. Branch B opened 220 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["400", "380", "390", "410", "420"], "answerIndex": 3, "explanation": "Total = 100 + 90 + 220 = 410.", "passage": "", "sourcePage": 5}, {"id": "KBL-09-Q24", "number": 24, "section": "quant", "stem": "Ravi is 12 years older than Meera. Their present ages add up to 46 years. What is Ravi's age?", "options": ["23", "25", "29", "31", "27"], "answerIndex": 2, "explanation": "Older age = (sum + difference)/2 = (46+12)/2 = 29.", "passage": "", "sourcePage": 5}, {"id": "KBL-09-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 8 and 24 hours; pipe C empties it in 12 hours. If all are opened together, when will the tank fill?", "options": ["14", "12", "8", "6", "10"], "answerIndex": 1, "explanation": "Net filling rate = 1/8 + 1/24 - 1/12 = 1/12 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-09-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 20 L and 5 L respectively. What is the simplified milk:water ratio?", "options": ["6:1", "1:4", "5:1", "4:2", "4:1"], "answerIndex": 4, "explanation": "Divide both quantities by HCF = 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-09-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 500. Its price rises by 25% and then falls by 20%. Find its final price (Rs).", "options": ["525", "500", "475", "450", "425"], "answerIndex": 1, "explanation": "Final price = 500 x 125/100 x 80/100 = 500.", "passage": "", "sourcePage": 5}, {"id": "KBL-09-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 2 place(s) forward in the alphabet. How is DATA coded?", "options": ["FCVC", "IFYF", "JGZG", "DATA", "HEXE"], "answerIndex": 0, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-09-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 71 people, A is 64th from the front. What is A's rank from the back?", "options": ["9", "7", "6", "8", "5"], "answerIndex": 3, "explanation": "Back rank = total - front rank +1 = 71-64+1 = 8.", "passage": "", "sourcePage": 6}, {"id": "KBL-09-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 5 km east, then 3 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["38", "22", "30", "26", "34"], "answerIndex": 4, "explanation": "Pythagoras: distance squared = 5^2 + 3^2 = 34.", "passage": "", "sourcePage": 6}, {"id": "KBL-09-Q31", "number": 31, "section": "reasoning", "stem": "A person faces West and turns 90 degrees to the left. Which direction does the person now face?", "options": ["South", "East", "Cannot be determined", "West", "North"], "answerIndex": 0, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-09-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All clerks are employees. Some employees are trainees. Which conclusion definitely follows?", "options": ["All trainees are clerks", "Some employees are clerks", "All employees are clerks", "No clerks are employees", "All trainees are employees"], "answerIndex": 1, "explanation": "All clerks are employees implies some employees are clerks in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-09-Q33", "number": 33, "section": "reasoning", "stem": "Given K > B = A > E, which relation definitely holds?", "options": ["K = E", "K > E", "A = E", "E > K", "B < E"], "answerIndex": 1, "explanation": "Chain: K > B = A > E, so K > E.", "passage": "", "sourcePage": 6}, {"id": "KBL-09-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: A, G, E, J, D. Who sits immediately to the right of A?", "options": ["J", "E", "D", "G", "A"], "answerIndex": 3, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-09-Q35", "number": 35, "section": "reasoning", "stem": "Leena is the mother of Maya. Asha is the sister of Maya. How is Leena related to Asha?", "options": ["Aunt", "Daughter", "Sister", "Mother", "Grandmother"], "answerIndex": 3, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-09-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: Q > W > X > T > V. Who is immediately heavier than W?", "options": ["Q", "V", "X", "T", "W"], "answerIndex": 0, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-09-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 3, 9, 27, 81, ?", "options": ["252", "216", "234", "243", "225"], "answerIndex": 3, "explanation": "Every term is multiplied by 3.", "passage": "", "sourcePage": 7}, {"id": "KBL-09-Q38", "number": 38, "section": "reasoning", "stem": "If today is Saturday, what day of the week will it be after 26 days?", "options": ["Tuesday", "Wednesday", "Thursday", "Friday", "Sunday"], "answerIndex": 2, "explanation": "Advance 5 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-09-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are M, A, D, H, J. Who occupies floor 4?", "options": ["A", "H", "M", "D", "J"], "answerIndex": 1, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-09-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in CASHIER?", "options": ["REIHSAC", "CASHIER", "RCASHIE", "ASHIERC", "ACEHIRS"], "answerIndex": 0, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-09-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 5?", "options": ["15", "36", "25", "10", "20"], "answerIndex": 1, "explanation": "36 leaves a remainder when divided by 5.", "passage": "", "sourcePage": 8}, {"id": "KBL-09-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 6 km east, then 5 km west. Where is the final position relative to the starting point?", "options": ["11 km west", "6 km north", "1 km east", "11 km east", "1 km west"], "answerIndex": 2, "explanation": "Net eastward movement = 6-5 = 1 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-09-Q43", "number": 43, "section": "gk", "stem": "Which payment instrument is a written order directing a bank to pay?", "options": ["Passbook", "Invoice", "Receipt", "Balance sheet", "Cheque"], "answerIndex": 4, "explanation": "Correct: Cheque.", "passage": "", "sourcePage": 8}, {"id": "KBL-09-Q44", "number": 44, "section": "gk", "stem": "Which type of rate is used for RBI lending to banks under a repo transaction?", "options": ["Repo rate", "Dividend yield", "GST rate", "Stamp duty", "Exchange commission"], "answerIndex": 0, "explanation": "Correct: Repo rate.", "passage": "", "sourcePage": 8}, {"id": "KBL-09-Q45", "number": 45, "section": "gk", "stem": "What is a credit score intended to help assess?", "options": ["Branch temperature", "Height of a customer", "Mobile data speed", "Creditworthiness", "Physical cash weight"], "answerIndex": 3, "explanation": "Correct: Creditworthiness.", "passage": "", "sourcePage": 8}, {"id": "KBL-09-Q46", "number": 46, "section": "gk", "stem": "A transaction reference number helps to do what?", "options": ["Set the interest rate", "Reveal the customer PIN", "Change the account type automatically", "Track or identify a specific transaction", "Create currency"], "answerIndex": 3, "explanation": "Correct: Track or identify a specific transaction.", "passage": "", "sourcePage": 8}, {"id": "KBL-09-Q47", "number": 47, "section": "gk", "stem": "What is the meaning of liquidity for an asset?", "options": ["Ease of turning it into cash with limited loss", "Its tax bracket always", "Its storage location only", "Its physical size", "Its printed colour"], "answerIndex": 0, "explanation": "Correct: Ease of turning it into cash with limited loss.", "passage": "", "sourcePage": 8}, {"id": "KBL-09-Q48", "number": 48, "section": "gk", "stem": "What is interest on a deposit?", "options": ["Amount paid by the bank under the deposit terms", "A penalty on every cash withdrawal", "The customer identity number", "An ATM access code", "Branch rent"], "answerIndex": 0, "explanation": "Correct: Amount paid by the bank under the deposit terms.", "passage": "", "sourcePage": 9}, {"id": "KBL-09-Q49", "number": 49, "section": "gk", "stem": "What does ATM stand for?", "options": ["Automatic Transfer Money", "Automated Tax Machine", "Approved Transaction Method", "Account Tracking Module", "Automated Teller Machine"], "answerIndex": 4, "explanation": "Correct: Automated Teller Machine.", "passage": "", "sourcePage": 9}, {"id": "KBL-09-Q50", "number": 50, "section": "gk", "stem": "What is the full form of UPI?", "options": ["United Processing Index", "Universal Payment Insurance", "Unified Payments Interface", "User Payment Institution", "Unified Postal Interface"], "answerIndex": 2, "explanation": "Correct: Unified Payments Interface.", "passage": "", "sourcePage": 9}, {"id": "KBL-09-Q51", "number": 51, "section": "gk", "stem": "A bank balance sheet shows assets, liabilities and what?", "options": ["Equity / capital", "Sales slogans", "Train schedules", "Daily weather", "Election dates"], "answerIndex": 0, "explanation": "Correct: Equity / capital.", "passage": "", "sourcePage": 9}, {"id": "KBL-09-Q52", "number": 52, "section": "gk", "stem": "Which is a common feature of a current account?", "options": ["No payment capability", "Only for children", "Only quarterly deposits", "Mandatory fixed term", "Designed for frequent business transactions"], "answerIndex": 4, "explanation": "Correct: Designed for frequent business transactions.", "passage": "", "sourcePage": 9}, {"id": "KBL-09-Q53", "number": 53, "section": "gk", "stem": "What is a direct debit mandate?", "options": ["Unlimited permission to share passwords", "A bank holiday notice", "Permission for eligible automated debits", "A new cheque number", "A credit score report"], "answerIndex": 2, "explanation": "Correct: Permission for eligible automated debits.", "passage": "", "sourcePage": 9}, {"id": "KBL-09-Q54", "number": 54, "section": "computer", "stem": "Which part of a computer executes arithmetic and logic operations?", "options": ["Cooling fan", "Display panel", "ALU", "Optical drive", "Printer port"], "answerIndex": 2, "explanation": "Correct: ALU.", "passage": "", "sourcePage": 9}, {"id": "KBL-09-Q55", "number": 55, "section": "computer", "stem": "What does DNS commonly do?", "options": ["Increases hardware RAM", "Prints pages", "Maps domain names to IP addresses", "Deletes all cookies", "Provides loan interest"], "answerIndex": 2, "explanation": "Correct: Maps domain names to IP addresses.", "passage": "", "sourcePage": 10}, {"id": "KBL-09-Q56", "number": 56, "section": "computer", "stem": "What is a web browser used for?", "options": ["Cooling a computer", "Changing network cables", "Accessing web pages", "Printing cheques only", "Scanning banknotes"], "answerIndex": 2, "explanation": "Correct: Accessing web pages.", "passage": "", "sourcePage": 10}, {"id": "KBL-09-Q57", "number": 57, "section": "computer", "stem": "Which keyboard shortcut typically saves a document?", "options": ["Ctrl+O", "Ctrl+N", "Ctrl+F", "Ctrl+S", "Ctrl+A"], "answerIndex": 3, "explanation": "Correct: Ctrl+S.", "passage": "", "sourcePage": 10}, {"id": "KBL-09-Q58", "number": 58, "section": "computer", "stem": "Which formula adds cells A1 to A5 in Excel?", "options": ["=TOTAL(A1:A5)", "=PLUS(A1,A5)", "=COUNT(A1:A5)", "=SUM(A1:A5)", "=ADD(A1-A5)"], "answerIndex": 3, "explanation": "Correct: =SUM(A1:A5).", "passage": "", "sourcePage": 10}, {"id": "KBL-09-Q59", "number": 59, "section": "computer", "stem": "What is an email attachment?", "options": ["The inbox folder only", "A file sent along with an email message", "The subject line only", "The sender's password", "A phone call"], "answerIndex": 1, "explanation": "Correct: A file sent along with an email message.", "passage": "", "sourcePage": 10}, {"id": "KBL-09-Q60", "number": 60, "section": "computer", "stem": "What is a database?", "options": ["An ink cartridge", "A keyboard shortcut", "Only a monitor", "Organised collection of data", "A cash drawer"], "answerIndex": 3, "explanation": "Correct: Organised collection of data.", "passage": "", "sourcePage": 10}, {"id": "KBL-09-Q61", "number": 61, "section": "computer", "stem": "Which is safer for online banking?", "options": ["Using the official site or app and verifying its address", "Saving PIN in public notes", "Following an unknown short link", "Disabling all security checks", "Sharing OTP in chat"], "answerIndex": 0, "explanation": "Correct: Using the official site or app and verifying its address.", "passage": "", "sourcePage": 10}, {"id": "KBL-09-Q62", "number": 62, "section": "computer", "stem": "Which shortcut commonly searches within a document?", "options": ["Ctrl+F", "Ctrl+W", "Ctrl+Q", "Ctrl+B", "Ctrl+R"], "answerIndex": 0, "explanation": "Correct: Ctrl+F.", "passage": "", "sourcePage": 11}, {"id": "KBL-09-Q63", "number": 63, "section": "computer", "stem": "In a spreadsheet, which symbol usually begins a formula?", "options": ["!", "#", "@", "&", "="], "answerIndex": 4, "explanation": "Correct: =.", "passage": "", "sourcePage": 11}, {"id": "KBL-09-Q64", "number": 64, "section": "computer", "stem": "What is phishing?", "options": ["Fraudulent attempt to steal information through deception", "Saving a spreadsheet", "Encrypting a hard drive", "Replacing a keyboard", "Installing a printer"], "answerIndex": 0, "explanation": "Correct: Fraudulent attempt to steal information through deception.", "passage": "", "sourcePage": 11}, {"id": "KBL-09-Q65", "number": 65, "section": "sales", "stem": "Case 9.1: Your sales target conflicts with customer suitability. Which takes priority?", "options": ["Changing signed forms", "Hiding risk warnings", "Highest sales commission", "Customer suitability and compliance", "Closing a sale irrespective of need"], "answerIndex": 3, "explanation": "Correct: Customer suitability and compliance.", "passage": "", "sourcePage": 11}, {"id": "KBL-09-Q66", "number": 66, "section": "sales", "stem": "A customer asks whether minimum balance charges apply. What is best?", "options": ["Invent a new charge", "Hide exceptions", "Explain the relevant account conditions accurately", "Say all accounts are free", "Ask for a password first"], "answerIndex": 2, "explanation": "Correct: Explain the relevant account conditions accurately.", "passage": "", "sourcePage": 11}, {"id": "KBL-09-Q67", "number": 67, "section": "sales", "stem": "You discover a marketing leaflet has an outdated rate. What should you do?", "options": ["Promise the old rate", "Use updated approved information and report the outdated material", "Change the date by hand without approval", "Continue distributing it knowingly", "Conceal the issue"], "answerIndex": 1, "explanation": "Correct: Use updated approved information and report the outdated material.", "passage": "", "sourcePage": 11}, {"id": "KBL-09-Q68", "number": 68, "section": "sales", "stem": "Case 9.4: An employee suggests using an informal payment link to collect fees. What is best?", "options": ["Use only approved bank payment channels", "Suppress receipts", "Keep collections off the record", "Accept payments to a personal wallet", "Share the login to the payment system"], "answerIndex": 0, "explanation": "Correct: Use only approved bank payment channels.", "passage": "", "sourcePage": 11}, {"id": "KBL-09-Q69", "number": 69, "section": "sales", "stem": "A customer requests a private conversation about debt difficulties. What is best?", "options": ["Discuss the debt loudly in a queue", "Threaten the customer", "Reveal details to strangers", "Promise automatic loan cancellation", "Arrange a discreet discussion and explain permitted assistance options"], "answerIndex": 4, "explanation": "Correct: Arrange a discreet discussion and explain permitted assistance options.", "passage": "", "sourcePage": 12}, {"id": "KBL-09-Q70", "number": 70, "section": "sales", "stem": "A customer has difficulty reading a product disclosure. What should you do?", "options": ["Read only the advertised benefits", "Explain the key terms in plain language and allow questions", "Suggest they trust the salesperson blindly", "Ask them to sign unread", "Conceal charges"], "answerIndex": 1, "explanation": "Correct: Explain the key terms in plain language and allow questions.", "passage": "", "sourcePage": 12}, {"id": "KBL-09-Q71", "number": 71, "section": "sales", "stem": "Case 9.7: The advertised offer does not fit a customer's needs. What is ethical?", "options": ["Misrepresent the offer", "Conceal charges", "Apply in another person's name", "Offer appropriate alternatives and explain why", "Pressure the customer to sign"], "answerIndex": 3, "explanation": "Correct: Offer appropriate alternatives and explain why.", "passage": "", "sourcePage": 12}, {"id": "KBL-09-Q72", "number": 72, "section": "sales", "stem": "A customer struggles with a form in English. What should you do?", "options": ["Ask for passwords", "Explain the form clearly in a language you can appropriately support", "Skip essential disclosures", "Fill in details without consent", "Refuse to explain"], "answerIndex": 1, "explanation": "Correct: Explain the form clearly in a language you can appropriately support.", "passage": "", "sourcePage": 12}, {"id": "KBL-09-Q73", "number": 73, "section": "sales", "stem": "A customer says a cheque was deposited but not credited. What do you do?", "options": ["Ignore the customer", "Discard the deposit receipt", "Promise immediate settlement regardless of status", "Verify the deposit and explain clearing and complaint steps", "Share someone else's cheque image"], "answerIndex": 3, "explanation": "Correct: Verify the deposit and explain clearing and complaint steps.", "passage": "", "sourcePage": 12}, {"id": "KBL-09-Q74", "number": 74, "section": "sales", "stem": "Case 9.10: A customer reports an ATM cash-withdrawal dispute. What is best?", "options": ["Close the account without consent", "Capture details and initiate the official dispute process", "Immediately reimburse from personal cash", "Ignore transaction evidence", "Request the card PIN"], "answerIndex": 1, "explanation": "Correct: Capture details and initiate the official dispute process.", "passage": "", "sourcePage": 12}, {"id": "KBL-09-Q75", "number": 75, "section": "sales", "stem": "A client asks to compare account options. What is good practice?", "options": ["Hide a cheaper suitable option", "Make up competitor charges", "Compare costs and benefits against the customer's needs", "Guarantee every account has the same terms", "Show only the promoted plan"], "answerIndex": 2, "explanation": "Correct: Compare costs and benefits against the customer's needs.", "passage": "", "sourcePage": 12}]}, {"id": "KBL-10", "title": "Karnataka Bank CSA Mock 10", "durationMinutes": 60, "pdf": "data/karnataka/pdfs/Karnataka_Bank_CSA_Mock_10.pdf", "sections": [{"id": "verbal", "name": "Verbal Ability", "count": 12}, {"id": "quant", "name": "Quantitative Aptitude", "count": 15}, {"id": "reasoning", "name": "Logical Reasoning", "count": 15}, {"id": "gk", "name": "General Knowledge / Banking", "count": 11}, {"id": "computer", "name": "Computer Awareness", "count": 11}, {"id": "sales", "name": "Sales Aptitude", "count": 11}], "questions": [{"id": "KBL-10-Q1", "number": 1, "section": "verbal", "stem": "What was the purpose of discussing instalments?", "options": ["To assess affordability", "To guarantee instant approval", "To hide the interest rate", "To remove repayment", "To avoid all documents"], "answerIndex": 0, "explanation": "Supported directly by the reading passage.", "passage": "A local entrepreneur planned to borrow funds for equipment. The banker discussed the repayment schedule and the likely effect of monthly instalments on the business budget. The entrepreneur prepared sales estimates and a list of existing obligations. The discussion focused on whether the loan amount was manageable rather than on approval at any cost.", "sourcePage": 2}, {"id": "KBL-10-Q2", "number": 2, "section": "verbal", "stem": "What did the entrepreneur prepare?", "options": ["Only a business logo", "Personal passwords", "A list of public holidays", "Sales estimates and existing obligations", "Staff social media accounts"], "answerIndex": 3, "explanation": "Supported directly by the reading passage.", "passage": "A local entrepreneur planned to borrow funds for equipment. The banker discussed the repayment schedule and the likely effect of monthly instalments on the business budget. The entrepreneur prepared sales estimates and a list of existing obligations. The discussion focused on whether the loan amount was manageable rather than on approval at any cost.", "sourcePage": 2}, {"id": "KBL-10-Q3", "number": 3, "section": "verbal", "stem": "What guided the discussion?", "options": ["Skipping all checks", "Advertising an unrelated product", "The highest possible loan irrespective of need", "Manageable borrowing rather than approval at any cost", "Borrowing without consent"], "answerIndex": 3, "explanation": "Supported directly by the reading passage.", "passage": "A local entrepreneur planned to borrow funds for equipment. The banker discussed the repayment schedule and the likely effect of monthly instalments on the business budget. The entrepreneur prepared sales estimates and a list of existing obligations. The discussion focused on whether the loan amount was manageable rather than on approval at any cost.", "sourcePage": 2}, {"id": "KBL-10-Q4", "number": 4, "section": "verbal", "stem": "Choose the closest meaning of \"expand\".", "options": ["limit", "deny", "increase", "reduce", "close"], "answerIndex": 2, "explanation": "\"expand\" is closest in meaning to \"increase\".", "passage": "", "sourcePage": 2}, {"id": "KBL-10-Q5", "number": 5, "section": "verbal", "stem": "Choose the closest meaning of \"diligent\".", "options": ["careless", "slow", "brief", "uncertain", "hardworking"], "answerIndex": 4, "explanation": "\"diligent\" is closest in meaning to \"hardworking\".", "passage": "", "sourcePage": 2}, {"id": "KBL-10-Q6", "number": 6, "section": "verbal", "stem": "Choose the opposite meaning of \"transparent\".", "options": ["visible", "obvious", "opaque", "clear", "open"], "answerIndex": 2, "explanation": "The opposite of \"transparent\" is \"opaque\".", "passage": "", "sourcePage": 2}, {"id": "KBL-10-Q7", "number": 7, "section": "verbal", "stem": "Choose the opposite meaning of \"accept\".", "options": ["welcome", "approve", "reject", "receive", "admit"], "answerIndex": 2, "explanation": "The opposite of \"accept\" is \"reject\".", "passage": "", "sourcePage": 3}, {"id": "KBL-10-Q8", "number": 8, "section": "verbal", "stem": "Choose the best word or phrase: The bank does not ___ personal passwords by email.", "options": ["request", "requested", "to request", "requests", "requesting"], "answerIndex": 0, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-10-Q9", "number": 9, "section": "verbal", "stem": "Choose the best word or phrase: Customers should ___ their PIN confidential.", "options": ["kept", "keeping", "keeps", "to keeping", "keep"], "answerIndex": 4, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-10-Q10", "number": 10, "section": "verbal", "stem": "Choose the best word or phrase: Please submit the form ___ Friday.", "options": ["beside", "at", "onwards", "across", "by"], "answerIndex": 4, "explanation": "Use standard grammar and subject-verb agreement.", "passage": "", "sourcePage": 3}, {"id": "KBL-10-Q11", "number": 11, "section": "verbal", "stem": "Choose the grammatically correct version of: \"The information are confidential.\"", "options": ["The information have confidential.", "The informations are confidential.", "The information is confidential.", "The information were confidential always.", "The information be confidential."], "answerIndex": 2, "explanation": "The corrected sentence uses the proper verb form.", "passage": "", "sourcePage": 3}, {"id": "KBL-10-Q12", "number": 12, "section": "verbal", "stem": "Choose the correct passive form: \"The clerk verified the documents.\"", "options": ["The documents verified the clerk.", "The documents were verified by the clerk.", "The documents is verified by the clerk.", "The documents are verifying the clerk.", "The clerk was verified by the documents."], "answerIndex": 1, "explanation": "Past simple passive uses was/were + past participle.", "passage": "", "sourcePage": 3}, {"id": "KBL-10-Q13", "number": 13, "section": "quant", "stem": "Find 20% of 600.", "options": ["110", "130", "120", "90", "100"], "answerIndex": 2, "explanation": "20/100 x 600 = 120.", "passage": "", "sourcePage": 3}, {"id": "KBL-10-Q14", "number": 14, "section": "quant", "stem": "In a class, the ratio of boys to girls is 3:5. If there are 72 students, how many girls are there?", "options": ["54", "18", "45", "27", "36"], "answerIndex": 2, "explanation": "One part = 72/(3+5) = 9; girls = 5 x 9.", "passage": "", "sourcePage": 4}, {"id": "KBL-10-Q15", "number": 15, "section": "quant", "stem": "A shop buys an item for Rs 1000 and sells it at 20% profit. Find the selling price (Rs).", "options": ["1180", "1140", "1160", "1220", "1200"], "answerIndex": 4, "explanation": "SP = 1000 x (1 + 20/100) = Rs 1200.", "passage": "", "sourcePage": 4}, {"id": "KBL-10-Q16", "number": 16, "section": "quant", "stem": "Find the average of 36, 40, 44, 48, 52.", "options": ["41", "35", "38", "44", "47"], "answerIndex": 3, "explanation": "The numbers are evenly spaced; the middle number equals the average.", "passage": "", "sourcePage": 4}, {"id": "KBL-10-Q17", "number": 17, "section": "quant", "stem": "Find simple interest (Rs) on Rs 11000 at 5% p.a. for 2 years.", "options": ["1100", "770", "990", "880", "1210"], "answerIndex": 0, "explanation": "SI = 11000 x 5 x 2/100 = Rs 1100.", "passage": "", "sourcePage": 4}, {"id": "KBL-10-Q18", "number": 18, "section": "quant", "stem": "Find compound interest (Rs) on Rs 30000 at 10% per annum for 2 years, compounded annually.", "options": ["6300", "5700", "6000", "5400", "6600"], "answerIndex": 0, "explanation": "CI = 30000 x [(1+10/100)^2 -1] = Rs 6300.", "passage": "", "sourcePage": 4}, {"id": "KBL-10-Q19", "number": 19, "section": "quant", "stem": "A completes a task in 6 days and B in 12 days. Working together, in how many days will they finish?", "options": ["2", "4", "5", "3", "1"], "answerIndex": 1, "explanation": "Combined time = (6 x 12)/(6+12) = 4 days.", "passage": "", "sourcePage": 4}, {"id": "KBL-10-Q20", "number": 20, "section": "quant", "stem": "A vehicle moves at 80 km/h for 4 hours. Find the distance travelled (km).", "options": ["200", "240", "280", "360", "320"], "answerIndex": 4, "explanation": "Distance = speed x time = 80 x 4 = 320 km.", "passage": "", "sourcePage": 4}, {"id": "KBL-10-Q21", "number": 21, "section": "quant", "stem": "Find the next term: 8, 19, 30, 41, ?", "options": ["19", "41", "30", "63", "52"], "answerIndex": 4, "explanation": "Each step adds 11.", "passage": "", "sourcePage": 5}, {"id": "KBL-10-Q22", "number": 22, "section": "quant", "stem": "An item marked Rs 1600 is sold at 20% discount. Find the selling price (Rs).", "options": ["1040", "1360", "1280", "1200", "1120"], "answerIndex": 2, "explanation": "SP = 1600 x (100-20)/100 = Rs 1280.", "passage": "", "sourcePage": 5}, {"id": "KBL-10-Q23", "number": 23, "section": "quant", "stem": "Branch A opened 80 accounts on Monday and 230 on Tuesday. Branch B opened 180 on Monday. How many accounts did both branches open on those stated days altogether?", "options": ["480", "470", "490", "460", "500"], "answerIndex": 2, "explanation": "Total = 80 + 230 + 180 = 490.", "passage": "", "sourcePage": 5}, {"id": "KBL-10-Q24", "number": 24, "section": "quant", "stem": "Ravi is 6 years older than Meera. Their present ages add up to 52 years. What is Ravi's age?", "options": ["29", "31", "27", "25", "23"], "answerIndex": 0, "explanation": "Older age = (sum + difference)/2 = (52+6)/2 = 29.", "passage": "", "sourcePage": 5}, {"id": "KBL-10-Q25", "number": 25, "section": "quant", "stem": "Pipes A and B fill a tank in 10 and 20 hours; pipe C empties it in 10 hours. If all are opened together, when will the tank fill?", "options": ["14", "16", "18", "22", "20"], "answerIndex": 4, "explanation": "Net filling rate = 1/10 + 1/20 - 1/10 = 1/20 tank/hour.", "passage": "", "sourcePage": 5}, {"id": "KBL-10-Q26", "number": 26, "section": "quant", "stem": "Milk and water are mixed in quantities 40 L and 5 L respectively. What is the simplified milk:water ratio?", "options": ["10:1", "8:1", "9:1", "1:8", "8:2"], "answerIndex": 1, "explanation": "Divide both quantities by HCF = 5.", "passage": "", "sourcePage": 5}, {"id": "KBL-10-Q27", "number": 27, "section": "quant", "stem": "A product costs Rs 600. Its price rises by 20% and then falls by 20%. Find its final price (Rs).", "options": ["606", "576", "516", "546", "486"], "answerIndex": 1, "explanation": "Final price = 600 x 120/100 x 80/100 = 576.", "passage": "", "sourcePage": 5}, {"id": "KBL-10-Q28", "number": 28, "section": "reasoning", "stem": "In a code language, every letter is shifted 2 place(s) forward in the alphabet. How is CASH coded?", "options": ["HFXM", "ECUJ", "IGYN", "CASH", "GEWL"], "answerIndex": 1, "explanation": "Shift each letter forward, wrapping after Z.", "passage": "", "sourcePage": 6}, {"id": "KBL-10-Q29", "number": 29, "section": "reasoning", "stem": "In a queue of 69 people, A is 51th from the front. What is A's rank from the back?", "options": ["16", "19", "18", "17", "20"], "answerIndex": 1, "explanation": "Back rank = total - front rank +1 = 69-51+1 = 19.", "passage": "", "sourcePage": 6}, {"id": "KBL-10-Q30", "number": 30, "section": "reasoning", "stem": "Ritu walks 2 km east, then 7 km north. What is the square of her straight-line distance from the starting point (km squared)?", "options": ["53", "49", "45", "57", "41"], "answerIndex": 0, "explanation": "Pythagoras: distance squared = 2^2 + 7^2 = 53.", "passage": "", "sourcePage": 6}, {"id": "KBL-10-Q31", "number": 31, "section": "reasoning", "stem": "A person faces East and turns 90 degrees to the left. Which direction does the person now face?", "options": ["Cannot be determined", "East", "South", "North", "West"], "answerIndex": 3, "explanation": "The turn is from the person's facing direction.", "passage": "", "sourcePage": 6}, {"id": "KBL-10-Q32", "number": 32, "section": "reasoning", "stem": "Statements: All roses are flowers. Some flowers are plants. Which conclusion definitely follows?", "options": ["All plants are roses", "No roses are flowers", "All plants are flowers", "Some flowers are roses", "All flowers are roses"], "answerIndex": 3, "explanation": "All roses are flowers implies some flowers are roses in standard bank-exam syllogism convention.", "passage": "", "sourcePage": 6}, {"id": "KBL-10-Q33", "number": 33, "section": "reasoning", "stem": "Given B > M = L > H, which relation definitely holds?", "options": ["B > H", "B = H", "M < H", "H > B", "L = H"], "answerIndex": 0, "explanation": "Chain: B > M = L > H, so B > H.", "passage": "", "sourcePage": 6}, {"id": "KBL-10-Q34", "number": 34, "section": "reasoning", "stem": "Five people sit in a row facing north, from left to right in this order: E, F, H, C, K. Who sits immediately to the right of C?", "options": ["K", "E", "H", "F", "C"], "answerIndex": 0, "explanation": "Facing north, right is the next position to the reader's right.", "passage": "", "sourcePage": 7}, {"id": "KBL-10-Q35", "number": 35, "section": "reasoning", "stem": "Rina is the mother of Leena. Divya is the sister of Leena. How is Rina related to Divya?", "options": ["Sister", "Mother", "Grandmother", "Daughter", "Aunt"], "answerIndex": 1, "explanation": "Siblings share the stated mother.", "passage": "", "sourcePage": 7}, {"id": "KBL-10-Q36", "number": 36, "section": "reasoning", "stem": "Five people have different weights, in decreasing order: Q > V > W > R > P. Who is immediately heavier than W?", "options": ["P", "Q", "W", "V", "R"], "answerIndex": 3, "explanation": "Move one place to the left in decreasing order.", "passage": "", "sourcePage": 7}, {"id": "KBL-10-Q37", "number": 37, "section": "reasoning", "stem": "Find the missing number: 2, 6, 18, 54, ?", "options": ["156", "168", "150", "162", "144"], "answerIndex": 3, "explanation": "Every term is multiplied by 3.", "passage": "", "sourcePage": 7}, {"id": "KBL-10-Q38", "number": 38, "section": "reasoning", "stem": "If today is Tuesday, what day of the week will it be after 15 days?", "options": ["Wednesday", "Thursday", "Friday", "Sunday", "Saturday"], "answerIndex": 0, "explanation": "Advance 1 day(s) modulo seven.", "passage": "", "sourcePage": 7}, {"id": "KBL-10-Q39", "number": 39, "section": "reasoning", "stem": "Five people live on floors 1 to 5, bottom to top. From floor 1 upward, they are L, J, E, N, K. Who occupies floor 4?", "options": ["J", "E", "K", "L", "N"], "answerIndex": 4, "explanation": "Count floors from the bottom (floor 1).", "passage": "", "sourcePage": 7}, {"id": "KBL-10-Q40", "number": 40, "section": "reasoning", "stem": "What is the reverse order of the letters in DEPOSIT?", "options": ["TDEPOSI", "TISOPED", "DEIOPST", "EPOSITD", "DEPOSIT"], "answerIndex": 1, "explanation": "Write the letters from last to first.", "passage": "", "sourcePage": 7}, {"id": "KBL-10-Q41", "number": 41, "section": "reasoning", "stem": "Which number is NOT divisible by 4?", "options": ["20", "8", "29", "12", "16"], "answerIndex": 2, "explanation": "29 leaves a remainder when divided by 4.", "passage": "", "sourcePage": 8}, {"id": "KBL-10-Q42", "number": 42, "section": "reasoning", "stem": "A person walks 8 km east, then 5 km west. Where is the final position relative to the starting point?", "options": ["13 km west", "13 km east", "8 km north", "3 km west", "3 km east"], "answerIndex": 4, "explanation": "Net eastward movement = 8-5 = 3 km.", "passage": "", "sourcePage": 8}, {"id": "KBL-10-Q43", "number": 43, "section": "gk", "stem": "Which is a common feature of a current account?", "options": ["Only quarterly deposits", "Designed for frequent business transactions", "Only for children", "Mandatory fixed term", "No payment capability"], "answerIndex": 1, "explanation": "Correct: Designed for frequent business transactions.", "passage": "", "sourcePage": 8}, {"id": "KBL-10-Q44", "number": 44, "section": "gk", "stem": "What is a direct debit mandate?", "options": ["A credit score report", "A new cheque number", "Unlimited permission to share passwords", "A bank holiday notice", "Permission for eligible automated debits"], "answerIndex": 4, "explanation": "Correct: Permission for eligible automated debits.", "passage": "", "sourcePage": 8}, {"id": "KBL-10-Q45", "number": 45, "section": "gk", "stem": "What is financial inclusion?", "options": ["Replacing loans with cash only", "Eliminating savings accounts", "Restricting banking to high incomes", "Expanding access to useful affordable financial services", "Stopping digital payments"], "answerIndex": 3, "explanation": "Correct: Expanding access to useful affordable financial services.", "passage": "", "sourcePage": 8}, {"id": "KBL-10-Q46", "number": 46, "section": "gk", "stem": "What happens when a customer transfers money from their own account to another account?", "options": ["Funds are debited from sender and credited to recipient", "Both accounts are always credited", "No ledger changes", "Both accounts are always debited", "All transfers become loans"], "answerIndex": 0, "explanation": "Correct: Funds are debited from sender and credited to recipient.", "passage": "", "sourcePage": 8}, {"id": "KBL-10-Q47", "number": 47, "section": "gk", "stem": "What does RTGS stand for?", "options": ["Real Time Gross Settlement", "Real Time Government Savings", "Rapid Transaction General Service", "Real Transfer Government System", "Regional Trade Gross Service"], "answerIndex": 0, "explanation": "Correct: Real Time Gross Settlement.", "passage": "", "sourcePage": 8}, {"id": "KBL-10-Q48", "number": 48, "section": "gk", "stem": "What is a nominee in banking?", "options": ["A person designated to receive proceeds as per applicable rules", "The bank cashier", "The account auditor", "The loan guarantor in all cases", "The branch security guard"], "answerIndex": 0, "explanation": "Correct: A person designated to receive proceeds as per applicable rules.", "passage": "", "sourcePage": 9}, {"id": "KBL-10-Q49", "number": 49, "section": "gk", "stem": "Which institution mainly supports agriculture and rural development financing?", "options": ["ECI", "SEBI", "ISRO", "IRDAI", "NABARD"], "answerIndex": 4, "explanation": "Correct: NABARD.", "passage": "", "sourcePage": 9}, {"id": "KBL-10-Q50", "number": 50, "section": "gk", "stem": "Who issues regulations governing many Indian banking operations?", "options": ["Food Corporation of India", "University Grants Commission", "Reserve Bank of India", "Indian Railways", "Election Commission"], "answerIndex": 2, "explanation": "Correct: Reserve Bank of India.", "passage": "", "sourcePage": 9}, {"id": "KBL-10-Q51", "number": 51, "section": "gk", "stem": "What is a beneficiary in a fund transfer?", "options": ["Insurance surveyor", "ATM manufacturer", "Person printing the receipt", "Intended recipient of funds", "Branch architect"], "answerIndex": 3, "explanation": "Correct: Intended recipient of funds.", "passage": "", "sourcePage": 9}, {"id": "KBL-10-Q52", "number": 52, "section": "gk", "stem": "What is a fixed deposit maturity date?", "options": ["Last day of every financial quarter", "Date of account opening always", "ATM maintenance time", "Bank nationalisation day", "Date when the agreed deposit tenure ends"], "answerIndex": 4, "explanation": "Correct: Date when the agreed deposit tenure ends.", "passage": "", "sourcePage": 9}, {"id": "KBL-10-Q53", "number": 53, "section": "gk", "stem": "What is a bank audit mainly intended to examine?", "options": ["Local cinema schedules", "Election rallies", "Branch wall colour", "Staff dress preferences", "Records, controls and compliance"], "answerIndex": 4, "explanation": "Correct: Records, controls and compliance.", "passage": "", "sourcePage": 9}, {"id": "KBL-10-Q54", "number": 54, "section": "computer", "stem": "What is phishing?", "options": ["Fraudulent attempt to steal information through deception", "Encrypting a hard drive", "Installing a printer", "Replacing a keyboard", "Saving a spreadsheet"], "answerIndex": 0, "explanation": "Correct: Fraudulent attempt to steal information through deception.", "passage": "", "sourcePage": 9}, {"id": "KBL-10-Q55", "number": 55, "section": "computer", "stem": "Which application is primarily used for spreadsheets?", "options": ["Microsoft Paint", "Media Player", "Notepad", "Calculator", "Microsoft Excel"], "answerIndex": 4, "explanation": "Correct: Microsoft Excel.", "passage": "", "sourcePage": 10}, {"id": "KBL-10-Q56", "number": 56, "section": "computer", "stem": "What is cloud storage?", "options": ["A type of printer ink", "Data stored on remote servers accessible via a network", "Only a local paper filing cabinet", "An offline-only keyboard", "A physical bank locker"], "answerIndex": 1, "explanation": "Correct: Data stored on remote servers accessible via a network.", "passage": "", "sourcePage": 10}, {"id": "KBL-10-Q57", "number": 57, "section": "computer", "stem": "What is a spreadsheet cell?", "options": ["A cloud server", "Intersection of row and column", "An email address", "A network password", "A printer cartridge"], "answerIndex": 1, "explanation": "Correct: Intersection of row and column.", "passage": "", "sourcePage": 10}, {"id": "KBL-10-Q58", "number": 58, "section": "computer", "stem": "What is a hyperlink?", "options": ["A printer driver", "An antivirus alert", "Clickable reference to another resource", "A storage disk", "A mouse cable"], "answerIndex": 2, "explanation": "Correct: Clickable reference to another resource.", "passage": "", "sourcePage": 10}, {"id": "KBL-10-Q59", "number": 59, "section": "computer", "stem": "What does IP address identify on a network?", "options": ["A fixed deposit maturity date", "The amount of RAM", "Network interface location for communication", "A printer toner size", "The user's Aadhaar details"], "answerIndex": 2, "explanation": "Correct: Network interface location for communication.", "passage": "", "sourcePage": 10}, {"id": "KBL-10-Q60", "number": 60, "section": "computer", "stem": "Which shortcut commonly selects all text or items?", "options": ["Ctrl+S", "Ctrl+P", "Ctrl+A", "Ctrl+D", "Ctrl+L"], "answerIndex": 2, "explanation": "Correct: Ctrl+A.", "passage": "", "sourcePage": 10}, {"id": "KBL-10-Q61", "number": 61, "section": "computer", "stem": "Which tool is normally used to create presentations?", "options": ["Microsoft PowerPoint", "Windows Explorer", "File compression utility", "Notepad", "Calculator"], "answerIndex": 0, "explanation": "Correct: Microsoft PowerPoint.", "passage": "", "sourcePage": 10}, {"id": "KBL-10-Q62", "number": 62, "section": "computer", "stem": "Which shortcut pastes copied content?", "options": ["Ctrl+F", "Ctrl+V", "Ctrl+C", "Ctrl+Z", "Ctrl+S"], "answerIndex": 1, "explanation": "Correct: Ctrl+V.", "passage": "", "sourcePage": 11}, {"id": "KBL-10-Q63", "number": 63, "section": "computer", "stem": "Which protocol helps secure website traffic?", "options": ["POP3 only", "HTTP without encryption", "SMTP only", "FTP only", "HTTPS"], "answerIndex": 4, "explanation": "Correct: HTTPS.", "passage": "", "sourcePage": 11}, {"id": "KBL-10-Q64", "number": 64, "section": "computer", "stem": "What is the purpose of antivirus software?", "options": ["Make passwords public", "Increase loan interest", "Create banknotes", "Replace all backups", "Detect and help block malicious software"], "answerIndex": 4, "explanation": "Correct: Detect and help block malicious software.", "passage": "", "sourcePage": 11}, {"id": "KBL-10-Q65", "number": 65, "section": "sales", "stem": "Case 10.1: A customer reports an ATM cash-withdrawal dispute. What is best?", "options": ["Request the card PIN", "Capture details and initiate the official dispute process", "Close the account without consent", "Ignore transaction evidence", "Immediately reimburse from personal cash"], "answerIndex": 1, "explanation": "Correct: Capture details and initiate the official dispute process.", "passage": "", "sourcePage": 11}, {"id": "KBL-10-Q66", "number": 66, "section": "sales", "stem": "A client asks to compare account options. What is good practice?", "options": ["Make up competitor charges", "Compare costs and benefits against the customer's needs", "Hide a cheaper suitable option", "Guarantee every account has the same terms", "Show only the promoted plan"], "answerIndex": 1, "explanation": "Correct: Compare costs and benefits against the customer's needs.", "passage": "", "sourcePage": 11}, {"id": "KBL-10-Q67", "number": 67, "section": "sales", "stem": "A customer asks about an account nomination. What should you do?", "options": ["Choose a nominee without consent", "Explain the nomination facility and approved procedure", "Hide the form", "Insist the CSA must be nominee", "Promise legal ownership rules are identical in all cases"], "answerIndex": 1, "explanation": "Correct: Explain the nomination facility and approved procedure.", "passage": "", "sourcePage": 11}, {"id": "KBL-10-Q68", "number": 68, "section": "sales", "stem": "Case 10.4: A colleague suggests skipping KYC to meet a target. What should you do?", "options": ["Ignore suspicious activity", "Use someone else's identity documents", "Follow KYC procedures and escalate pressure if necessary", "Skip steps to close the sale", "Alter the forms"], "answerIndex": 2, "explanation": "Correct: Follow KYC procedures and escalate pressure if necessary.", "passage": "", "sourcePage": 11}, {"id": "KBL-10-Q69", "number": 69, "section": "sales", "stem": "A customer reports a phishing call. The best guidance is to:", "options": ["Avoid sharing credentials and contact the bank using official channels", "Click all links in the message", "Install an unknown app", "Share OTP with the caller", "Send a photo of their password"], "answerIndex": 0, "explanation": "Correct: Avoid sharing credentials and contact the bank using official channels.", "passage": "", "sourcePage": 12}, {"id": "KBL-10-Q70", "number": 70, "section": "sales", "stem": "A client asks whether an investment is risk free. What should the CSA do?", "options": ["Provide accurate risk information and avoid absolute guarantees", "Conceal product documents", "Claim all returns are fixed by law", "Guarantee all investments", "Recommend borrowing to invest without review"], "answerIndex": 0, "explanation": "Correct: Provide accurate risk information and avoid absolute guarantees.", "passage": "", "sourcePage": 12}, {"id": "KBL-10-Q71", "number": 71, "section": "sales", "stem": "Case 10.7: During cash handling you notice a mismatch. What is the correct step?", "options": ["Accuse the next customer", "Reconcile carefully and report under procedure", "Hide the shortage", "Alter figures to match", "Use a personal payment to avoid a record"], "answerIndex": 1, "explanation": "Correct: Reconcile carefully and report under procedure.", "passage": "", "sourcePage": 12}, {"id": "KBL-10-Q72", "number": 72, "section": "sales", "stem": "The bank changes a product fee. What should the CSA communicate?", "options": ["A claim the fee is impossible to change", "Only old promotional claims", "An arbitrary amount", "A personal discount not authorised", "The current published terms and effective conditions"], "answerIndex": 4, "explanation": "Correct: The current published terms and effective conditions.", "passage": "", "sourcePage": 12}, {"id": "KBL-10-Q73", "number": 73, "section": "sales", "stem": "A customer with a disability requests a reasonable accommodation. What is best?", "options": ["Sell a higher-priced product instead", "Require public disclosure of medical records", "Mock the request", "Follow accessible service procedures and offer appropriate help", "Refuse all assistance"], "answerIndex": 3, "explanation": "Correct: Follow accessible service procedures and offer appropriate help.", "passage": "", "sourcePage": 12}, {"id": "KBL-10-Q74", "number": 74, "section": "sales", "stem": "Case 10.10: A customer offers a personal gift in exchange for bypassing checks. What do you do?", "options": ["Hide the exception", "Decline and follow the bank's ethics policy", "Offer a private rate", "Skip controls", "Accept the gift"], "answerIndex": 1, "explanation": "Correct: Decline and follow the bank's ethics policy.", "passage": "", "sourcePage": 12}, {"id": "KBL-10-Q75", "number": 75, "section": "sales", "stem": "A customer declines insurance after the terms are explained. What should the CSA do?", "options": ["Respect the decision and document consent appropriately", "Claim it is legally mandatory when it is not", "Add it without permission", "Keep pressuring until they agree", "Hide the rejection"], "answerIndex": 0, "explanation": "Correct: Respect the decision and document consent appropriately.", "passage": "", "sourcePage": 12}]}], "paperLinks": [{"title": "IBPS Clerk Prelims 2025 - 4 Oct Shift 1", "url": "https://www.careerpower.in/blog/wp-content/uploads/2025/10/04151758/IBPS-Clerk-Pre-2025-Memory-Based-Paper-Based-on-4-Oct-1st-Shift.pdf"}, {"title": "IBPS Clerk Prelims 2025 - 4 Oct Shift 2", "url": "https://www.careerpower.in/blog/wp-content/uploads/2026/10/08111747/IBPS-Clerk-Pre-2025-Memory-Based-Paper-4-Oct-2025-2nd-shift.pdf"}, {"title": "IBPS Clerk Prelims 2025 - 4 Oct Shift 3", "url": "https://www.careerpower.in/blog/wp-content/uploads/2026/10/08111742/IBPS-Clerk-Pre-2025-Memory-Based-Paper-4-Oct-2025-3rd-shift.pdf"}, {"title": "IBPS Clerk Prelims 2025 - 4 Oct Shift 4", "url": "https://www.careerpower.in/blog/wp-content/uploads/2026/10/08111737/IBPS-Clerk-Pre-2025-Memory-Based-Paper-4-Oct-2025-4th-shift.pdf"}, {"title": "IBPS Clerk Prelims 2025 - 5 Oct", "url": "https://www.careerpower.in/blog/wp-content/uploads/2025/10/07125141/ibps-clerk-5-october-english-question-paper.pdf"}, {"title": "IBPS Clerk Prelims 2024", "url": "https://www.careerpower.in/blog/wp-content/uploads/2025/06/17164303/IBPS-Clerk-Pre-2024-Memory-Based-Question-Paper.pdf"}, {"title": "IBPS Clerk Prelims 2023", "url": "https://www.careerpower.in/blog/wp-content/uploads/2024/07/01125641/ibps-clerk-question-paper-2023.pdf"}, {"title": "IBPS Clerk Prelims 2022", "url": "https://www.careerpower.in/blog/wp-content/uploads/2024/07/01125640/ibps-clerk-question-paper-2022.pdf"}, {"title": "IBPS Clerk Prelims 2021", "url": "https://www.careerpower.in/blog/wp-content/uploads/2024/07/01130144/ibps-clerk-question-paper-2021.pdf"}, {"title": "IBPS Clerk Prelims 2019", "url": "https://www.adda247.com/jobs/wp-content/uploads/2021/05/24110246/IBPS_Clerk_Prelims_2019_Memory_Based_Paper_For_Practice.pdf"}]};
